(window.JCPA_DATA=window.JCPA_DATA||{})["securities"]={"id":"securities","name":"قانون الأوراق المالية","full":"قانون الأوراق المالية رقم (18) لسنة 2017","icon":"📊","articles":[{"n":"1","chapter":"","notes":[],"source":"يسمى هذا القانون ( قانون الاوراق المالية لسنة ٢٠١٧ ) ويعمل به من تاريخ نشره في الجريدة الرسمية .","title":"اسم القانون وبدء العمل به","memo":"⭐ قانون الأوراق المالية لسنة ٢٠١٧\n⭐ يعمل به من تاريخ نشره في الجريدة الرسمية","qs":[{"q":"يعمل بقانون الأوراق المالية لسنة ٢٠١٧ اعتباراً من:","o":["تاريخ نشره في الجريدة الرسمية","مرور ثلاثين يوماً على نشره في الجريدة الرسمية","تاريخ مصادقة مجلس الوزراء عليه","بداية السنة المالية التالية لنشره"],"a":0}]},{"n":"2","chapter":"تعاريف","notes":[],"source":"يكون للكلمات والعبارات التالية حيثما وردت في هذا القانون المعاني المخصصة لها ادناه ما لم تدل القرينة على غير ذلك:-\nالهيئة : هيئة الاوراق المالية .\nالمجلس : مجلس مفوضي الهيئة.\nالرئيس : رئيس المجلس.\nسوق تداول الاوراق المالية : اي سوق منظم او اي استخدام دوري او مستمر لوسائل الاتصال يتيح تداول الاوراق والاصول المالية.\nالسوق المالي : أي سوق لتداول الاوراق المالية مرخص من الهيئة وفقا لاحكام هذا القانون.\nالمركز : مركز ايداع الاوراق المالية .\nالشخص : الشخص الطبيعي او الاعتباري .\nالوسيط المالي : الشخص الذي يمارس شراء الاوراق المالية وبيعها لحساب الغير .\nالوسيط لحسابه : الشخص الذي يمارس شراء الاوراق المالية وبيعها لحسابه الخاص مباشرة من خلال السوق المالي.\nامين الاستثمار : الشخص الاعتباري الذي يمارس متابعة ادارة استثمارات العملاء ومراقبتها للتاكد من مطابقتها للاسس والاهداف الاستثمارية للعميل المنصوص عليها في اتفاقية الاستثمار الموقعة بين العميل ومدير الاستثمار .\nمدير الاستثمار : الشخص الذي يمارس ادارة محافظ الاوراق المالية لحساب الغير بما في ذلك ادارة صندوق الاستثمار المشترك .\nالمستشار المالي : الشخص الذي يمارس تقديم النصح والمشورة للغير في مجال الاستثمار في الاوراق المالية مقابل اجر او عمولة .\nمدير الإصدار : الشخص الاعتباري الذي يمارس ادارة اصدارات الاوراق المالية وتسويقها نيابة عن المصدر .\nشركة الخدمات المالية : الشخص الاعتباري الذي يمارس عملا او اكثر من اعمال الوسيط المالي او الوسيط لحسابه او امين الاستثمار او مدير الاستثمار او المستشار المالي او مدير الاصدار او أي نشاط اخر تحدده الهيئة بموجب هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه .\nالحافظ الامين : الشخص الاعتباري الذي يمارس اعمال الحفظ الامين للاوراق المالية .\nالمرخص له : الشخص المرخص من الهيئة وفقا لاحكام هذا القانون .\nالمعتمد : الشخص الطبيعي الذي يكون عضوا في مجلس ادارة شركة خدمات مالية او هيئة مديريها او مديرا او مسؤولا اداريا او موظفا فيها ، او ممن يشغل وضعا مشابها في الشركة او يمارس صلاحيات مماثلة لدى وسيط مالي او وسيط لحسابه او امين استثمار او مدير استثمار او مستشار مالي او مدير اصدار او شركة خدمات مالية ولا يشمل ذلك المستخدمين في الوظائف المكتبية والخدماتية وتلك التي لا علاقة لها بالنشاط المتعلق بالاوراق المالية .\nالمصدر : الشخص الاعتباري الذي يصدر اوراقا مالية او يعلن عن رغبته في اصدارها .\nالمصدر العام : المصدر الذي قدم الى الهيئة نشرة اصدار اصبحت نافذة لديها.\nالعرض العام : عرض لبيع اي ورقة مالية لاكثر من ثلاثين شخصا من الجمهور ويشمل ذلك الاصدار العام والطرح العام.\nعرض التملك العام : اي عرض يقصد به شراء (٤٠ %) او اكثر من الاوراق المالية العائدة الى مصدر واحد ، او حيازتها عن طريق المبادلة .\nصندوق الاستثمار المشترك : الصندوق الذي يتم انشاؤه ويمارس اعماله وفقا لاحكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه.\nشركة الاستثمار المشترك : الشركة المساهمة العامة التي تقتصر غاياتها على استثمار اموالها واموال الغير في الاوراق المالية على اختلاف انواعها باستثناء البنوك وشركات التأمين التي تمارس اعمالها بهذه الصفة .\nالحساب المشترك للاستثمار : الحساب الذي يضم الاستثمارات العائدة لاكثر من شخص واحد وذلك لاغراض ادارة هذا الحساب .\nالمعلومة الجوهرية : اي واقعة او معلومة قد تؤثر في قرار الشخص لشراء الورقة المالية او الاحتفاظ بها او بيعها او التصرف بها .\nالاعمال المحظورة : اي عمل او ممارسة او خطة او نهج او وسيلة محظورة بموجب هذا القانون او الانظمة او التعليمات او القرارات الصادرة بمقتضاه .\nالتضليل : اي بيان غير صحيح يتعلق بمعلومة جوهرية او اي حذف او اخفاء لمعلومة جوهرية او اي معلومة اخرى لازمة لتكون البيانات المقدمة صحيحة ودقيقة.\nالخداع : اي عمل او ممارسة او خطة او نهج او وسيلة يقصد باي منها التغرير بالآخرين او قد يؤدي الى التغرير بهم .\nالمعلومات الداخلية : المعلومات غير المعلن عنها المتعلقة بمصدر او اكثر، او بورقة مالية او اكثر، والتي قد تؤثر على سعر اي ورقة مالية في حال الاعلان عنها ، ولا يشمل ذلك الاستنتاجات المبنية على الدراسات والبحوث والتحاليل الاقتصادية المالية .\nالشخص المطلع : الشخص الذي يطلع على المعلومات الداخلية بحكم منصبه او وظيفته.\nعقد التداول : العقد الذي يتم بموجبه شراء اوراق مالية وبيعها .\nالتعامل : تسجيل الاوراق المالية او اصدارها او الاكتتاب بها او الترويج لها او تسويقها او حفظها او ادراجها او ايداعها او تداولها او تسويتها او شراؤها من مصدرها او العرض العام لها او العرض العام لتملكها او تمويل التعامل بها او اقراضها او اقتراضها او البيع المكشوف لها او رهنها او ارتهانها او اي نشاط اخر يقره المجلس.\nالتقاص : العملية التي يتم بموجبها احتساب صافي حقوق والتزامات اطراف التداول الناشئة عن أي عقد تداول وذلك لتسليم الاوراق المالية او لتسديد اثمانها في التاريخ المحدد للتسوية .\nالتسوية : العملية التي يتم بموجبها اتمام اي عقد تداول لنقل ملكية الاوراق المالية من البائع الى المشتري وتسديد اثمانها بشكل نهائي وغير مشروط .\nالتسليم مقابل الدفع : طريقة من طرق التسوية ، يتم بموجبها تسليم الاوراق المالية مقابل تسديد اثمانها .\nالمحكمة المختصة : محكمة بداية عمان .\nالاقرباء : الزوج والزوجة والاولاد القصر .","title":"التعاريف","memo":"⭐ العرض العام: عرض لبيع ورقة مالية لأكثر من ثلاثين شخصاً من الجمهور (يشمل الإصدار العام والطرح العام)\n⭐ عرض التملك العام: شراء (٤٠%) أو أكثر من الأوراق المالية العائدة لمصدر واحد أو حيازتها بالمبادلة\n⭐ المحكمة المختصة: محكمة بداية عمان، والأقرباء: الزوج والزوجة والأولاد القصر\n⭐ أمين الاستثمار ومدير الإصدار وشركة الخدمات المالية والحافظ الأمين أشخاص اعتباريون حصراً","qs":[{"q":"وفقاً لقانون الأوراق المالية، يُعد العرض عرضاً عاماً إذا كان عرضاً لبيع ورقة مالية لـ:","o":["أكثر من ثلاثين شخصاً من الجمهور","أكثر من عشرين شخصاً من الجمهور","أكثر من خمسين شخصاً من الجمهور","أكثر من مئة شخص من الجمهور"],"a":0},{"q":"يُقصد بعرض التملك العام أي عرض يقصد به شراء أو حيازة الأوراق المالية العائدة إلى مصدر واحد بنسبة:","o":["(٤٠%) أو أكثر","(٢٥%) أو أكثر","(٥٠%) أو أكثر","(٧٥%) أو أكثر"],"a":0},{"q":"المحكمة المختصة وفقاً لتعريفات قانون الأوراق المالية هي:","o":["محكمة بداية عمان","محكمة استئناف عمان","المحكمة الإدارية","محكمة صلح جزاء عمان"],"a":0},{"q":"يشمل تعريف (الأقرباء) في قانون الأوراق المالية جميع ما يلي باستثناء:","o":["الأولاد البالغين","الزوج","الزوجة","الأولاد القصر"],"a":0}]},{"n":"3","chapter":"تعاريف","notes":[],"source":"أ- يقصد بالاوراق المالية أي حقوق ملكية أو أي دلالات أو بينات متعارف عليها على انها أوراق مالية ، سواء كانت محلية أو اجنبية ، يوافق المجلس على اعتبارها كذلك .\nب-تشمل الاوراق المالية ، بصورة خاصة ، ما يلي :-\n١-اسهم الشركات القابلة للتحويل والتداول .\n٢-اسناد القرض الصادرة عن الشركات .\n٣-الاوراق المالية الصادرة عن الحكومة او المؤسسات الرسمية العامة او المؤسسات العامة او البلديات .\n٤-ايصالات ايداع الاوراق المالية .\n٥-الاسهم والوحدات الاستثمارية في صناديق الاستثمار المشترك .\n٦-اسناد خيار المساهمة .\n٧-العقود آنية التسوية والعقود آجلة التسوية .\n٨-عقود خيار الشراء وعقود خيار البيع .\n٩-أي حق في الحصول على أي مما ذكر في البنود من (١-٨) من هذه الفقرة بموافقة المجلس .","title":"مفهوم الأوراق المالية","memo":"⭐ الأوراق المالية: أي حقوق ملكية أو دلالات أو بينات متعارف عليها كأوراق مالية، محلية أو أجنبية، يوافق المجلس على اعتبارها كذلك\n⭐ تشمل: الأسهم القابلة للتحويل والتداول، أسناد القرض، أوراق الحكومة والمؤسسات العامة والبلديات، إيصالات الإيداع، وحدات صناديق الاستثمار، أسناد خيار المساهمة، العقود آنية وآجلة التسوية، عقود خيار الشراء والبيع","qs":[{"q":"الجهة التي توافق على اعتبار حقوق الملكية أو الدلالات المتعارف عليها أوراقاً مالية هي:","o":["مجلس مفوضي الهيئة","مجلس الوزراء","رئيس الوزراء","مجلس إدارة السوق المالي"],"a":0},{"q":"أي مما يلي لا يُعد من الأوراق المالية التي نص عليها القانون بصورة خاصة؟","o":["الكمبيالات","أسناد القرض الصادرة عن الشركات","إيصالات إيداع الأوراق المالية","عقود خيار الشراء وعقود خيار البيع"],"a":0},{"q":"يُعد أي حق في الحصول على أي من الأوراق المالية المذكورة في البنود (١-٨) ورقة مالية بشرط:","o":["موافقة المجلس","موافقة مجلس الوزراء","موافقة السوق المالي","تسجيله لدى مركز الإيداع"],"a":0}]},{"n":"4","chapter":"تعاريف","notes":[],"source":"لاتعتبر اوراقا مالية :-\nأ-الاوراق التجارية بما في ذلك الشيكات والكمبيالات .\nب-الاعتمادات المستندية والحوالات والادوات التي تتداولها البنوك حصراً فيما بينها .\nج-بوالص التامين والحقوق المترتبة في صناديق التقاعد للمنتفعين التي تتم تغذيتها من غير مصادر مساهماتهم .","title":"ما لا يعتبر أوراقاً مالية","memo":"⭐ لا تعتبر أوراقاً مالية: الأوراق التجارية (الشيكات والكمبيالات)\n⭐ الاعتمادات المستندية والحوالات والأدوات التي تتداولها البنوك حصراً فيما بينها\n⭐ بوالص التأمين وحقوق المنتفعين في صناديق التقاعد التي تتم تغذيتها من غير مصادر مساهماتهم","qs":[{"q":"أي مما يلي يُعد ورقة مالية وفقاً لقانون الأوراق المالية؟","o":["أسناد خيار المساهمة","الشيكات","بوالص التأمين","الاعتمادات المستندية"],"a":0},{"q":"لا تعتبر أوراقاً مالية الأدوات التي تتداولها البنوك:","o":["حصراً فيما بينها","مع عملائها من الشركات","في السوق المالي","مع البنك المركزي فقط"],"a":0}]},{"n":"5","chapter":"تعاريف","notes":[],"source":"على كل مصدر في المملكة ان يقدم الى الهيئة طلباً لتسجيل الاوراق المالية لديها وذلك وفقاً للتعليمات التي يصدرها المجلس.","title":"تسجيل الأوراق المالية لدى الهيئة","memo":"⭐ على كل مصدر في المملكة تقديم طلب لتسجيل الأوراق المالية لدى الهيئة\n⭐ وفقاً للتعليمات التي يصدرها المجلس","qs":[{"q":"يلتزم كل مصدر في المملكة بتقديم طلب لتسجيل أوراقه المالية لدى:","o":["هيئة الأوراق المالية","مركز إيداع الأوراق المالية","السوق المالي","دائرة مراقبة الشركات"],"a":0},{"q":"يتم تسجيل الأوراق المالية لدى الهيئة وفقاً لـ:","o":["التعليمات التي يصدرها المجلس","نظام يصدره مجلس الوزراء","قرار يصدره رئيس الوزراء","الأنظمة الداخلية للسوق المالي"],"a":0}]},{"n":"6","chapter":"تعاريف","notes":[],"source":"تطبق الاحكام المنصوص عليها في هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه على اسهم الشركات وغيرها من الاوراق المالية المتداولة في السوق المالي فيما يتعلق بالامور التالية :-\nأ-حقوق الاطراف الناشئة عن عمليات بيع الاوراق المالية او شرائها اوتحويلها .\nب-الاسلوب والشكل الخاص بتسجيل حقوق الملكية والآثار القانونية المترتبة على ذلك .\nج-تحويل حق الملكية والحقوق المترتبة على هذا التحويل .\nد-حقوق الاطراف ذات العلاقة بعمليات التقاص والتسوية والتحويل .\nهـ-الحقوق المترتبة اثناء عمليات بيع الاوراق المالية او شرائها او تحويلها لدائني اطراف عقود التداول بما في ذلك الحقوق المتعلقة بالاوراق المالية والمقابل النقدي لها .\nو-انعقاد عقود التداول وتوثيقها ووسائل اثباتها والغائها .\nز-التعامل في الاوراق المالية .","title":"نطاق تطبيق القانون على الأوراق المتداولة","memo":"⭐ تطبق أحكام القانون على الأسهم وغيرها من الأوراق المتداولة في السوق المالي في: حقوق أطراف البيع والشراء والتحويل، أسلوب تسجيل حقوق الملكية، تحويل الملكية، التقاص والتسوية، حقوق الدائنين، انعقاد عقود التداول وتوثيقها وإثباتها وإلغائها، والتعامل","qs":[{"q":"تطبق أحكام قانون الأوراق المالية على الأوراق المالية المتداولة في السوق المالي فيما يتعلق بجميع الأمور التالية باستثناء:","o":["تأسيس الشركات المصدرة وتسجيلها","انعقاد عقود التداول وتوثيقها ووسائل إثباتها وإلغائها","حقوق الأطراف ذات العلاقة بعمليات التقاص والتسوية والتحويل","تحويل حق الملكية والحقوق المترتبة عليه"],"a":0},{"q":"تشمل الحقوق التي ينظمها القانون أثناء عمليات بيع الأوراق المالية أو شرائها أو تحويلها حقوق:","o":["دائني أطراف عقود التداول","موظفي السوق المالي","مدققي حسابات المصدر","أعضاء مجلس المفوضين"],"a":0}]},{"n":"7","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- تنشأ هيئة تسمى (هيئة الاوراق المالية) تتمتع بشخصية اعتبارية ذات استقلال مالي واداري ولها بهذه الصفة تملك الاموال المنقولة وغير المنقولة والقيام بجميع التصرفات القانونية اللازمة لتحقيق اهدافها بما في ذلك ابرام العقود والاقتراض وقبول المساعدات والهبات والتبرعات ولها حق التقاضي وينوب عنها في الاجراءات القضائية المحامي العام المدني او أي محام توكله لهذه الغاية .\nب-ترتبط الهيئة برئيس الوزراء .\nج-يكون مقر الهيئة في مدينة عمان .","title":"إنشاء الهيئة وشخصيتها ومقرها","memo":"⭐ هيئة الأوراق المالية: شخصية اعتبارية ذات استقلال مالي وإداري\n⭐ ترتبط برئيس الوزراء، ومقرها مدينة عمان\n⭐ ينوب عنها قضائياً المحامي العام المدني أو أي محام توكله","qs":[{"q":"ترتبط هيئة الأوراق المالية بـ:","o":["رئيس الوزراء","وزير المالية","وزير الصناعة والتجارة","محافظ البنك المركزي"],"a":0},{"q":"ينوب عن هيئة الأوراق المالية في الإجراءات القضائية:","o":["المحامي العام المدني أو أي محام توكله لهذه الغاية","النائب العام حصراً","رئيس الهيئة شخصياً","ديوان التشريع والرأي"],"a":0},{"q":"يكون مقر هيئة الأوراق المالية في:","o":["مدينة عمان","مدينة الزرقاء","مدينة العقبة","أي مدينة يحددها المجلس"],"a":0}]},{"n":"8","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- تهدف الهيئة، وبصورة خاصة ، الى تحقيق ما يلي :-\n١-حماية المستثمرين في الاوراق المالية .\n٢-تنظيم سوق راس المال وتطويره بما يكفل تحقيق العدالة والكفاءة والشفافية.\n٣-حماية سوق راس المال من المخاطر التي قد يتعرض لها .\nب-تتولى الهيئة في سبيل تحقيق اهدافها المهام والصلاحيات الرئيسة التالية :-\n١-تنظيم ومراقبة اصدار الاوراق المالية والتعامل بها .\n٢-ضمان افصاح المصدرين بشكل كامل ودقيق عن المعلومات الجوهرية اللازمة للمستثمرين والمتعلقة بالاصدارات العامة للاوراق المالية .\n٣-تنظيم ومراقبة الافصاح بما في ذلك التقارير الدورية التي يعدها المصدرون.\n٤-تنظيم شؤون الترخيص والاعتماد ومراقبة اعمال المرخص لهم والمعتمدين في سوق راس المال .\n٥-اعتماد معايير الملاءة المالية لشركات الخدمات المالية وفقاً لنظام يصدر لهذه الغاية.\n٦-تنظيم ومراقبة السوق المالي واسواق تداول الاوراق المالية .\n٧-تنظيم المركز ومراقبته .\n٨-تنظيم صناديق الاستثمار المشترك وشركات الاستثمار .","title":"أهداف الهيئة ومهامها","memo":"⭐ الأهداف: حماية المستثمرين، تنظيم سوق رأس المال وتطويره (العدالة والكفاءة والشفافية)، حمايته من المخاطر\n⭐ من المهام: تنظيم ومراقبة إصدار الأوراق والتعامل بها، ضمان إفصاح المصدرين، تنظيم الترخيص والاعتماد، تنظيم السوق المالي والمركز وصناديق الاستثمار\n⭐ معايير الملاءة المالية لشركات الخدمات المالية تعتمد وفقاً لنظام","qs":[{"q":"تهدف الهيئة إلى تنظيم سوق رأس المال وتطويره بما يكفل تحقيق:","o":["العدالة والكفاءة والشفافية","الربحية والسيولة والنمو","الاستقرار النقدي وضبط التضخم","زيادة الإيرادات الضريبية"],"a":0},{"q":"تعتمد الهيئة معايير الملاءة المالية لشركات الخدمات المالية وفقاً لـ:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها الرئيس","قرار من مجلس الوزراء","اتفاقية مع البنك المركزي"],"a":0},{"q":"أي مما يلي ليس من الأهداف التي نص عليها القانون للهيئة؟","o":["تحقيق الأرباح من الاستثمار في الأوراق المالية","حماية المستثمرين في الأوراق المالية","حماية سوق رأس المال من المخاطر","تنظيم سوق رأس المال وتطويره"],"a":0}]},{"n":"9","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- يحظر على الهيئة القيام باي عمل تجاري او المساهمة في المشاريع التجارية او اقراض الاموال و تملك او اصدار الاوراق المالية .\nب-للهيئة بموافقة مجلس الوزراء، الاقتراض وتملك الاوراق المالية المصدرة من الحكومة او المؤسسات الرسمية العامة او المؤسسات العامة او البلديات .","title":"الأعمال المحظورة على الهيئة","memo":"⭐ يحظر على الهيئة: العمل التجاري، المساهمة في المشاريع التجارية، إقراض الأموال، تملك أو إصدار الأوراق المالية\n⭐ استثناء: لها بموافقة مجلس الوزراء الاقتراض وتملك الأوراق المالية الصادرة عن الحكومة أو المؤسسات الرسمية العامة أو المؤسسات العامة أو البلديات","qs":[{"q":"يجوز للهيئة تملك الأوراق المالية المصدرة من الحكومة أو البلديات بموافقة:","o":["مجلس الوزراء","رئيس الوزراء","مجلس المفوضين","وزير المالية"],"a":0},{"q":"أي مما يلي يُحظر على هيئة الأوراق المالية القيام به مطلقاً؟","o":["إقراض الأموال","الاقتراض بموافقة مجلس الوزراء","تملك أوراق مالية صادرة عن البلديات بموافقة مجلس الوزراء","قبول الهبات والتبرعات"],"a":0},{"q":"حالة عملية: رغبت الهيئة في شراء أسهم شركة مساهمة عامة مدرجة في السوق المالي لاستثمار فائض أموالها. ما الحكم؟","o":["محظور لأنه يحظر على الهيئة تملك الأوراق المالية إلا ما صدر عن الحكومة والجهات العامة بموافقة مجلس الوزراء","جائز بقرار من المجلس","جائز بموافقة رئيس الوزراء","جائز إذا لم تتجاوز النسبة (٥%) من رأسمال الشركة"],"a":0}]},{"n":"10","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- يتولى ادارة الهيئة والاشراف على شؤونها مجلس يسمى (مجلس مفوضي الهيئة) يتالف من خمسة مفوضين متفرغين ويشترط في كل منهم ما يلي:\n١-ان يكون أردنياً.\n٢-ان يكون حاصلاً على الشهادة الجامعية الأولى حداً أدنى.\n٣-ان يكون من ذوي الخبرة والاختصاص في الشؤون المالية أو الاقتصادية أو القانونية.\n٤-ان لا يكون وزيراً أو عضواً في مجلس الأمة أو موظفاً عاماً أو موظفاً في المؤسسات العامة أو البلديات أو عضواً أو موظفاً في أي شركة أو مؤسسة.\nب-يعين المفوضون ، بمن فيهم الرئيس ونائبه ، بقرار من مجلس الوزراء بناء على تنسيب رئيس الوزراء لمدة أربع سنوات قابلة للتجديد لمرة واحدة على ان يقترن القرار بالارادة الملكية السامية ، ويجوز بالطريقة ذاتها تغيير أي منهم بتعيين بديل له للمدة المتبقية من مدة المجلس.\nج-تحدد رواتب ومزايا المفوضين وسائر حقوقهم المالية بقرار من مجلس الوزراء .\nد-يؤدي المفوضون امام رئيس الوزراء قبل مباشرتهم لمهامهم اليمين التالية:-\n(اقسم بالله العظيم ان اكون مخلصاً للملك والوطن وان احافظ على الدستور وان احترم القوانين والانظمة المعمول بها وان اقوم بمهام وظيفتي وواجباتها بشرف وامانة واخلاص).","title":"تشكيل مجلس المفوضين وشروط العضوية","memo":"⭐ مجلس المفوضين: خمسة مفوضين متفرغين\n⭐ الشروط: أردني، شهادة جامعية أولى حداً أدنى، خبرة مالية أو اقتصادية أو قانونية، ألا يكون وزيراً أو نائباً/عيناً أو موظفاً عاماً أو في أي شركة\n⭐ التعيين بقرار من مجلس الوزراء بتنسيب رئيس الوزراء لمدة أربع سنوات قابلة للتجديد لمرة واحدة، ويقترن بالإرادة الملكية\n⭐ الرواتب بقرار مجلس الوزراء، واليمين أمام رئيس الوزراء","qs":[{"q":"يتألف مجلس مفوضي هيئة الأوراق المالية من:","o":["خمسة مفوضين متفرغين","سبعة مفوضين متفرغين","خمسة مفوضين غير متفرغين","ثلاثة مفوضين متفرغين"],"a":0},{"q":"مدة تعيين المفوضين في مجلس مفوضي الهيئة:","o":["أربع سنوات قابلة للتجديد لمرة واحدة","ثلاث سنوات قابلة للتجديد","خمس سنوات غير قابلة للتجديد","أربع سنوات قابلة للتجديد دون حد"],"a":0},{"q":"يؤدي المفوضون اليمين قبل مباشرتهم لمهامهم أمام:","o":["رئيس الوزراء","جلالة الملك","رئيس المجلس القضائي","مجلس الوزراء"],"a":0},{"q":"الحد الأدنى من المؤهل العلمي المشترط في المفوض:","o":["الشهادة الجامعية الأولى","شهادة الماجستير","شهادة الدبلوم المتوسط","شهادة الدكتوراه"],"a":0}]},{"n":"11","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- يترتب على كل مفوض عند تعيينه ان يقدم تصريحاً خطياً لدى المجلس عن الاوراق المالية التي يملكها هو او أي من اقربائه او التي تكون تحت تصرفه او تحت تصرف أي من اقربائه وعن أي مساهمات او حصص يملكها هو او أي من اقربائه في أي شركة خدمات مالية او تكون تحت تصرفه او تحت تصرف أي من اقربائه وعن أي تغيير يطرأ على أي منها خلال ثلاثة ايام من تاريخ علمه بهذا التغيير .\nب-يحظر على أي مفوض ممارسة أي مهنة او القيام باي عمل بما في ذلك اشغال المنصب الوزاري او عضوية مجلس الامة او أي منصب او وظيفة في الحكومة وفي المؤسسات الرسمية العامة والمؤسسات العامة والبلديات وفي أي شركة او مؤسسة ، او ان يكون له أي تأثير في اتخاذ القرارات في الجهات المذكورة او ان يقدم المشورة لاي منها .","title":"التزامات المفوضين والمحظورات عليهم","memo":"⭐ يقدم المفوض عند تعيينه تصريحاً خطياً عن الأوراق المالية والحصص في شركات الخدمات المالية التي يملكها هو أو أقرباؤه أو تحت تصرفهم\n⭐ يصرح عن أي تغيير خلال ثلاثة أيام من تاريخ علمه\n⭐ يحظر عليه ممارسة أي مهنة أو عمل أو وظيفة أو تقديم المشورة","qs":[{"q":"يلتزم المفوض بالتصريح عن أي تغيير يطرأ على الأوراق المالية التي يملكها هو أو أقرباؤه خلال:","o":["ثلاثة أيام من تاريخ علمه بالتغيير","سبعة أيام من تاريخ علمه بالتغيير","أربعة عشر يوماً من تاريخ التغيير","ثلاثين يوماً من تاريخ التغيير"],"a":0},{"q":"يقدم المفوض التصريح الخطي عن الأوراق المالية التي يملكها هو أو أقرباؤه لدى:","o":["المجلس","رئيس الوزراء","مركز إيداع الأوراق المالية","دائرة مكافحة الفساد"],"a":0},{"q":"حالة عملية: طلبت شركة مساهمة عامة من أحد المفوضين تقديم استشارة مالية مقابل أجر خارج أوقات الدوام. ما الحكم؟","o":["محظور، إذ يحظر على المفوض تقديم المشورة لأي شركة","جائز بموافقة الرئيس","جائز إذا كانت الشركة غير خاضعة لرقابة الهيئة","جائز بشرط التصريح عنه خلال ثلاثة أيام"],"a":0}]},{"n":"12","chapter":"هيئة الاوراق المالية","notes":[],"source":"يتولى المجلس جميع الصلاحيات اللازمة لتحقيق اهداف الهيئة وفقاً لاحكام هذا القانون وتنفيذ المهام والصلاحيات المقررة له بمقتضى احكامه بما في ذلك ما يلي:-\nأ-رسم السياسة العامة للهيئة ووضع البرامج اللازمة لتنفيذها .\nب-الموافقة على تداول أي ورقة مالية خارج السوق المالي .\nج-الموافقة على ادراج أي ورقة مالية اردنية لدى أي سوق تداول اوراق مالية خارج المملكة .\nد-البت في طلبات تسجيل الأوراق المالية بناءً على تنسيب من الرئيس.\nهـ-تعليق او وقف التعامل باي ورقة مالية للمدة التي يراها مناسبة .\nو-الموافقة على انشاء وتسجيل صناديق الاستثمار المشترك .\nز-منح الترخيص والاعتماد الذي يصدر بموجب احكام هذا القانون.\nح-تقييد او تعليق او ايقاف او الغاء الترخيص او الاعتماد الممنوح لاي شخص للمدة التي يراها مناسبة .\nط-تحديد الرسوم المتعلقة باصدار الترخيص او الاعتماد وتجديد أي منهما .\nي-الموافقة على تحديد بدل الخدمات والاجور والعمولات التي يتقاضاها كل من السوق المالي والمركز بمقتضى انظمتهما الداخلية.\nك-تحديد العمولات التي تتقاضاها شركة الخدمات المالية او المرخص له من عملائهم بحدودها الدنيا والعليا .\nل-اعتماد المعايير المحاسبية ومعايير التدقيق ومعايير تقويم الاداء التي يجب على الجهات الخاضعة لرقابة الهيئة التقيد بها .\nم-تحديد المعايير والشروط الواجب توافرها في مدققي الحسابات المؤهلين لتدقيق حسابات الجهات الخاضعة لرقابة الهيئة واشرافها.\nن-وضع قواعد الحوكمة لأي من الجهات الخاضعة لرقابة الهيئة.\nس-إصدار مدونة سلوك تنظم معاملة موظفي الهيئة مع المستثمرين بما يضمن الاحترام المتبادل.\nع-اقامة علاقات التعاون مع هيئات الاوراق المالية العربية والاجنبية والمنظمات العربية والاقليمية والدولية المختصة باسواق راس المال.\nف-النظر في القرارات المتعلقة بالتعامل بالأوراق المالية والصادرة عن السوق المالي والمركز ووقف تنفيذ أي منها.\nص-اصدار التعليمات اللازمة لادارة الهيئة واي تعليمات او قرارات لتنفيذ احكام هذا القانون والانظمة الصادرة بمقتضاه او تعديل تلك التعليمات او القرارات او الغاؤها .\nق-اعداد مشروعات القوانين والانظمة المتعلقة بالاوراق المالية .\nر-اعداد الموازنة السنوية للهيئة وتقديمها لمجلس الوزراء للمصادقة عليها .\nش-أي امور اخرى يرى الرئيس عرضها على المجلس .","title":"صلاحيات مجلس المفوضين","memo":"⭐ يوافق المجلس على تداول أي ورقة مالية خارج السوق المالي وإدراج ورقة أردنية في سوق خارج المملكة\n⭐ يبت في طلبات تسجيل الأوراق المالية بتنسيب من الرئيس، ويوافق على إنشاء وتسجيل صناديق الاستثمار المشترك\n⭐ يحدد العمولات بحدودها الدنيا والعليا ويعتمد المعايير المحاسبية ومعايير التدقيق ويضع قواعد الحوكمة\n⭐ يعد الموازنة السنوية ويقدمها لمجلس الوزراء للمصادقة","qs":[{"q":"يبت مجلس المفوضين في طلبات تسجيل الأوراق المالية بناءً على تنسيب من:","o":["الرئيس","مدير السوق المالي","مدير مركز الإيداع","نائب الرئيس"],"a":0},{"q":"تقدم الموازنة السنوية لهيئة الأوراق المالية للمصادقة عليها إلى:","o":["مجلس الوزراء","مجلس الأمة","رئيس الوزراء","ديوان المحاسبة"],"a":0},{"q":"تحدد العمولات التي تتقاضاها شركة الخدمات المالية من عملائها بحدودها الدنيا والعليا من قبل:","o":["مجلس المفوضين","السوق المالي","مركز إيداع الأوراق المالية","جمعية شركات الخدمات المالية"],"a":0},{"q":"أي مما يلي ليس من صلاحيات مجلس المفوضين وفقاً للقانون؟","o":["المصادقة على الموازنة السنوية للهيئة","الموافقة على تداول أي ورقة مالية خارج السوق المالي","اعتماد المعايير المحاسبية ومعايير التدقيق","وضع قواعد الحوكمة للجهات الخاضعة لرقابة الهيئة"],"a":0}]},{"n":"13","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- يكون الرئيس هو الرئيس التنفيذي للهيئة وآمر الصرف فيها والمنفذ لسياستها والمسؤول عن ادارة شؤونها ويتولى في سبيل ذلك ما يلي :-\n١-تنفيذ القرارات التي يتخذها المجلس .\n٢-توقيع العقود التي يفوضه المجلس بتوقيعها .\n٣-التوقيع ، منفرداً او بالاشتراك مع غيره ، على التقارير والبيانات المحاسبية والكشوفات المالية والمراسلات والوثائق الخاصة بالهيئة.\nب-يقوم نائب الرئيس بالاعمال والمهام التي يكلفه بها الرئيس ويتولى صلاحيات الرئيس في حال غيابه او شغور مركزه .\nج-يقوم المفوضون بالاعمال والمهام التي يكلفهم بها الرئيس .\nد-للرئيس تفويض أي من صلاحياته المنصوص عليها في هذا القانون لاي مفوض كما يجوز له تفويض أي من صلاحياته لاي موظف مختص في الهيئة على ان يكون التفويض خطياً ومحدداً.","title":"صلاحيات الرئيس ونائبه والمفوضين","memo":"⭐ الرئيس هو الرئيس التنفيذي وآمر الصرف والمنفذ للسياسة والمسؤول عن إدارة الشؤون\n⭐ نائب الرئيس يتولى صلاحيات الرئيس عند غيابه أو شغور مركزه\n⭐ للرئيس تفويض صلاحياته لأي مفوض أو لأي موظف مختص، على أن يكون التفويض خطياً ومحدداً","qs":[{"q":"آمر الصرف في هيئة الأوراق المالية هو:","o":["الرئيس","نائب الرئيس","المدير المالي للهيئة","مجلس المفوضين"],"a":0},{"q":"يشترط في تفويض الرئيس لأي من صلاحياته أن يكون:","o":["خطياً ومحدداً","بموافقة مجلس الوزراء","لمدة لا تزيد على سنة","لمفوض فقط دون الموظفين"],"a":0},{"q":"يتولى صلاحيات الرئيس في حال غيابه أو شغور مركزه:","o":["نائب الرئيس","أقدم المفوضين","من يسميه رئيس الوزراء","مجلس المفوضين مجتمعاً"],"a":0}]},{"n":"14","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- يجتمع المجلس، مرة على الاقل كل شهر وكلما دعت الحاجة، بدعوة من الرئيس او نائبه عند غيابه ويكون اجتماعه قانونياً بحضور ما لا يقل عن اربعة من اعضائه على ان يكون من بينهم الرئيس او نائبه ، ويتخذ قراراته باغلبية ثلاثة اصوات من اعضائه الحاضرين على الاقل ولا يجوز الامتناع عن التصويت وعلى العضو المخالف تثبيت مخالفته خطياً والتوقيع عليها .\nب-تحدد الاحكام والاجراءات المتعلقة باجتماعات المجلس بموجب تعليمات يصدرها لهذه الغاية .","title":"اجتماعات مجلس المفوضين","memo":"⭐ يجتمع مرة على الأقل كل شهر بدعوة من الرئيس أو نائبه عند غيابه\n⭐ النصاب: أربعة أعضاء على الأقل من بينهم الرئيس أو نائبه\n⭐ القرارات بأغلبية ثلاثة أصوات من الحاضرين على الأقل، ولا يجوز الامتناع عن التصويت، ويثبت المخالف مخالفته خطياً","qs":[{"q":"يكون اجتماع مجلس المفوضين قانونياً بحضور ما لا يقل عن:","o":["أربعة من أعضائه على أن يكون من بينهم الرئيس أو نائبه","ثلاثة من أعضائه على أن يكون من بينهم الرئيس","أغلبية أعضائه","خمسة من أعضائه"],"a":0},{"q":"يتخذ مجلس المفوضين قراراته بأغلبية:","o":["ثلاثة أصوات من أعضائه الحاضرين على الأقل","صوتين من أعضائه الحاضرين","أربعة أصوات من أعضائه","الأغلبية المطلقة للحاضرين"],"a":0},{"q":"يجتمع مجلس المفوضين:","o":["مرة على الأقل كل شهر وكلما دعت الحاجة","مرة على الأقل كل أسبوعين","مرة على الأقل كل ثلاثة أشهر","مرة على الأقل كل أسبوع"],"a":0},{"q":"حالة عملية: أراد أحد المفوضين الامتناع عن التصويت على قرار لعدم قناعته به. ما الحكم؟","o":["لا يجوز الامتناع عن التصويت، وعليه إن خالف تثبيت مخالفته خطياً والتوقيع عليها","يجوز الامتناع بشرط تسجيله في المحضر","يجوز بموافقة الرئيس","يجوز ويحسب صوته موافقاً"],"a":0}]},{"n":"15","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- يخضع لرقابة الهيئة واشرافها وفقاً لاحكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاها كل من :-\n١-المصدرين .\n٢-المرخص لهم .\n٣-المعتمدين .\n٤-السوق المالي .\n٥-المركز .\n٦-صناديق الاستثمار المشترك وشركات الاستثمار .\nب-تخضع الجهات المشار اليها في الفقرة (أ) من هذه المادة للتفتيش عليها والتدقيق على وثائقها وقيودها وسجلاتها من الجهة المختصة في الهيئة المخولة قانونياً بذلك .\nج-تحقيقاً للغايات المقصودة من هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه، تشمل الوثائق والقيود والسجلات ، حيثما وردت ، البيانات البنكية والمراسلات والمذكرات والوثائق وملفات الحاسوب او أي وسيلة لحفظ المعلومات والبيانات سواء كانت خطية او الكترونية .","title":"الجهات الخاضعة لرقابة الهيئة","memo":"⭐ يخضع لرقابة الهيئة: المصدرون، المرخص لهم، المعتمدون، السوق المالي، المركز، صناديق الاستثمار المشترك وشركات الاستثمار\n⭐ تخضع للتفتيش والتدقيق على وثائقها وقيودها وسجلاتها\n⭐ تشمل الوثائق: البيانات البنكية والمراسلات وملفات الحاسوب خطية أو إلكترونية","qs":[{"q":"أي مما يلي لا يُعد من الجهات الخاضعة لرقابة هيئة الأوراق المالية وإشرافها وفق المادة (١٥)؟","o":["البنك المركزي","المصدرون","مركز إيداع الأوراق المالية","صناديق الاستثمار المشترك"],"a":0},{"q":"لغايات قانون الأوراق المالية، تشمل الوثائق والقيود والسجلات الخاضعة للتدقيق:","o":["البيانات البنكية والمراسلات وملفات الحاسوب، خطية كانت أو إلكترونية","الوثائق الخطية المصدقة فقط","السجلات المحاسبية دون المراسلات","الوثائق الإلكترونية فقط"],"a":0}]},{"n":"16","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- للمجلس ، وقبل اصدار أي تعليمات بموجب احكام هذا القانون أو الانظمة الصادرة بمقتضاه او اجراء أي تعديل عليها، نشر مشروع التعليمات او تعديلاتها لتمكين الغير من ابداء أي ملاحظات خطية عليها خلال مدة لا تزيد على اربعة عشر يوماً من تاريخ نشرها.\nب-يصدر المجلس التعليمات المشار اليها في الفقرة (أ) من هذه المادة بعد دراسة أي ملاحظات ترد بشأنها على ان تصبح نافذة من التاريخ الذي تحدده تلك التعليمات .\nج-تنشر التعليمات بالوسائل التي تراها الهيئة مناسبة بما في ذلك النشر على موقعها الالكتروني على شبكة الانترنت او أي شبكة معلومات اخرى.","title":"نشر مشروعات التعليمات","memo":"⭐ للمجلس قبل إصدار التعليمات أو تعديلها نشر مشروعها لإبداء الملاحظات الخطية خلال مدة لا تزيد على أربعة عشر يوماً من تاريخ نشرها\n⭐ تصبح نافذة من التاريخ الذي تحدده التعليمات\n⭐ تنشر بالوسائل التي تراها الهيئة مناسبة بما فيها موقعها الإلكتروني","qs":[{"q":"المدة القصوى لإبداء الملاحظات الخطية على مشروع التعليمات الذي ينشره المجلس:","o":["أربعة عشر يوماً من تاريخ نشره","سبعة أيام من تاريخ نشره","ثلاثون يوماً من تاريخ نشره","عشرة أيام عمل من تاريخ نشره"],"a":0},{"q":"تصبح التعليمات التي يصدرها المجلس بعد دراسة الملاحظات نافذة:","o":["من التاريخ الذي تحدده تلك التعليمات","من تاريخ نشرها في الجريدة الرسمية حكماً","بعد ثلاثين يوماً من صدورها","من تاريخ مصادقة مجلس الوزراء عليها"],"a":0}]},{"n":"17","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- للهيئة، من خلال الجهة المختصة فيها ، اجراء أي تحقيق او تفتيش او تدقيق لتحديد ما اذا كان أي شخص قد ارتكب مخالفة لاي من احكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاها.\nب-للهيئة، ومن خلال الجهة المختصة فيها ، التحقيق في أي معلومات او ظروف او ممارسات تراها ضرورية وملائمة لتنفيذ احكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه.\nج-للهيئة ، ومن خلال الجهة المختصة فيها ، وفي سبيل اجراء التحقيقات الواردة في الفقرتين (أ) و (ب) من هذه المادة القيام باي مما يلي :-\n١-تدقيق الوثائق والقيود والسجلات العائدة لاي مرخص له او معتمد او أي من الجهات الخاضعة لرقابة الهيئة واشرافها والحصول على نسخ من أي منها ، والتفتيش عليها باشعار مسبق او بدونه .\n٢-طلب حضور الشهود وسماع شهاداتهم تحت القسم، وتقديم أي وثائق ومستندات ذات علاقة بموضوع التحقيق .\nد-للهيئة الاستعانة بذوي الخبرة والاختصاص في اجراءات التحقيق والتفتيش والتدقيق المشار اليها في الفقرة (أ) من هذه المادة .","title":"صلاحيات الهيئة في التحقيق والتفتيش","memo":"⭐ للهيئة من خلال الجهة المختصة إجراء أي تحقيق أو تفتيش أو تدقيق لتحديد المخالفات\n⭐ التفتيش على السجلات بإشعار مسبق أو بدونه، والحصول على نسخ منها\n⭐ طلب حضور الشهود وسماع شهاداتهم تحت القسم، والاستعانة بذوي الخبرة والاختصاص","qs":[{"q":"تقوم الهيئة بالتفتيش على وثائق وسجلات المرخص لهم في سبيل التحقيق:","o":["بإشعار مسبق أو بدونه","بإشعار مسبق لا يقل عن ثلاثة أيام","بعد الحصول على إذن من المحكمة المختصة","بإشعار مسبق لا يقل عن أسبوع"],"a":0},{"q":"للهيئة في سبيل التحقيق طلب حضور الشهود وسماع شهاداتهم:","o":["تحت القسم","دون قسم","بحضور المدعي العام فقط","بموافقة المحكمة الإدارية"],"a":0},{"q":"يجوز للهيئة في إجراءات التحقيق والتفتيش والتدقيق:","o":["الاستعانة بذوي الخبرة والاختصاص","توقيف المخالف مدة لا تزيد على أسبوع","الحجز على أموال المخالف دون قرار","إحالة الشهود إلى المحكمة مباشرة"],"a":0}]},{"n":"18","chapter":"هيئة الاوراق المالية","notes":[],"source":"تعتبر مخالفة لاحكام هذا القانون ما يلي :-\nأ-عدم استجابة أي مرخص له او معتمد او أي جهة خاضعة لرقابة الهيئة واشرافها لطلبات الهيئة بتقديم الوثائق او المستندات اللازمة او بالحضور للادلاء بالشهادة ، وللمجلس في هذه الحالة الغاء الترخيص او الاعتماد .\nب-عدم استجابة أي شخص، غير المرخص له او غير المعتمد او أي جهة غير خاضعة لرقابة الهيئة واشرافها ، لطلبات الهيئة بتقديم الوثائق او المستندات اللازمة او بالحضور للادلاء بالشهادة.","title":"مخالفة عدم الاستجابة لطلبات الهيئة","memo":"⭐ تعد مخالفة: عدم استجابة المرخص له أو المعتمد أو الجهة الخاضعة للرقابة لطلبات الهيئة بتقديم الوثائق أو الحضور للشهادة، وللمجلس إلغاء الترخيص أو الاعتماد\n⭐ وكذلك عدم استجابة أي شخص غير مرخص أو غير معتمد أو غير خاضع للرقابة","qs":[{"q":"إذا لم يستجب مرخص له لطلب الهيئة بتقديم الوثائق اللازمة أو بالحضور للإدلاء بالشهادة، فللمجلس:","o":["إلغاء الترخيص","إحالته للمحكمة الإدارية فقط","فرض غرامة لا تتجاوز ألف دينار فقط","توقيفه إدارياً"],"a":0},{"q":"عدم استجابة شخص غير مرخص له وغير خاضع لرقابة الهيئة لطلباتها بالحضور للإدلاء بالشهادة:","o":["يعد مخالفة لأحكام القانون","لا يعد مخالفة لعدم خضوعه لرقابة الهيئة","يعد مخالفة فقط إذا كان مساهماً في شركة مدرجة","لا يعد مخالفة إلا بقرار من المحكمة"],"a":0}]},{"n":"19","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- اذا تبين للمجلس، ولاسباب مبررة، ان حماية المستثمرين تقتضي اتخاذ تدبير فوري فله ، وللمدة التي يراها مناسبة ، اتخاذ تدبير او اكثر من التدابير التالية:-\n١-وقف او تعليق أي نشاط يتعلق بالاوراق المالية او بورقة مالية معينة.\n٢-تعليق العرض العام لورقة مالية .\n٣-تعليق اعمال المرخص له او المعتمد .\nب-للمجلس اتخاذ اجراء مؤقت بوقف عمل او نشاط المرخص له او المعتمد اذا ارتكب او حاول ارتكاب أي مخالفة تؤدي الى تبديد الموجودات او تحويل صفتها او الى احداث ضرر بالمصلحة العامة او بالمستثمرين ، ويبقى الاجراء المؤقت نافذاً الى حين استكمال الاجراءات التي يتوجب على الهيئة القيام بها وتنفيذها ما لم يتم الغاء هذا الاجراء او وقفه بقرار من المجلس.\nج-للمجلس ان يقوم باي من الاجراءات المنصوص عليها في الفقرتين (أ) و (ب) من هذه المادة سواء باعطاء الشخص المعني فرصة لسماع اقواله او عدم اعطائه تلك الفرصة وذلك وفقاً لما تقتضيه المصلحة العامة .\nد-للمرخص له أو المعتمد أو الشخص الذي تم فرض تدبير فوري عليه وفق أحكام الفقرتين (أ) و(ب) من هذه المادة أن يقدم إلى الهيئة طلباً لسماع أقواله وبيناته المؤيده له أو لإلغاء هذا الإجراء أو تعليقه أو تقييده.","title":"التدابير الفورية والإجراءات المؤقتة","memo":"⭐ للمجلس لأسباب مبررة ولحماية المستثمرين اتخاذ تدبير فوري: وقف أو تعليق أي نشاط أو ورقة مالية، تعليق العرض العام، تعليق أعمال المرخص له أو المعتمد\n⭐ الإجراء المؤقت بوقف عمل المرخص له عند تبديد الموجودات أو الإضرار بالمصلحة العامة يبقى نافذاً حتى استكمال الإجراءات ما لم يلغه المجلس\n⭐ يجوز اتخاذها بسماع أقوال الشخص أو دون ذلك، وللمعني طلب سماع أقواله أو إلغاء الإجراء","qs":[{"q":"يتخذ المجلس التدابير الفورية لحماية المستثمرين:","o":["سواء بإعطاء الشخص المعني فرصة لسماع أقواله أو عدم إعطائه تلك الفرصة","بعد سماع أقوال الشخص المعني وجوباً","بعد موافقة المحكمة المختصة","بعد إنذار الشخص المعني خطياً لمدة سبعة أيام"],"a":0},{"q":"يبقى الإجراء المؤقت بوقف عمل المرخص له نافذاً:","o":["إلى حين استكمال الإجراءات التي يتوجب على الهيئة القيام بها ما لم يلغه المجلس أو يوقفه","لمدة ثلاثين يوماً فقط","لمدة لا تزيد على ثلاثة أشهر","إلى حين صدور حكم قطعي من المحكمة"],"a":0},{"q":"أي مما يلي لا يُعد من التدابير الفورية التي نصت عليها المادة (١٩)؟","o":["فرض غرامة مالية على المرخص له","تعليق العرض العام لورقة مالية","تعليق أعمال المرخص له أو المعتمد","وقف أو تعليق أي نشاط يتعلق بورقة مالية معينة"],"a":0}]},{"n":"20","chapter":"هيئة الاوراق المالية","notes":[],"source":"للمجلس ، وفق ما يراه مناسباً ، الاعلان عن أي مخالفة لاحكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه وذلك لتنبيه المستثمرين الى وقوع تلك المخالفة لتفادي الآثار المترتبة عليها .","title":"الإعلان عن المخالفات","memo":"⭐ للمجلس وفق ما يراه مناسباً الإعلان عن أي مخالفة لأحكام القانون\n⭐ الغاية: تنبيه المستثمرين إلى وقوعها لتفادي آثارها","qs":[{"q":"الغاية من إعلان المجلس عن المخالفات المرتكبة لأحكام قانون الأوراق المالية:","o":["تنبيه المستثمرين إلى وقوعها لتفادي الآثار المترتبة عليها","التشهير بالمخالف كعقوبة إضافية","تحصيل الغرامات المفروضة","إبلاغ المحكمة المختصة بها"],"a":0},{"q":"يعلن المجلس عن أي مخالفة لأحكام قانون الأوراق المالية:","o":["وفق ما يراه مناسباً","وجوباً في كل حالة","بعد صدور حكم قضائي قطعي","بموافقة رئيس الوزراء"],"a":0}]},{"n":"21","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- إذا تبين للمجلس من خلال الجهة المختصة قيام أي شخص بمخالفة أحكام هذا القانون والأنظمة والتعليمات والقرارات الصادرة بمقتضاه فللرئيس أو من يفوضه خطياً توجيه إشعار خطي لذلك الشخص لسماع أقواله وتقديم بيناته وتحديد موعد الجلسة وتاريخها على ان يتضمن الاشعار طبيعة المخالفة وحق الشخص المعني في تقديم دفاعه خلال المدة المحددة في الاشعار وتوكيل محام له.\nب-ينظر المجلس من خلال الجهة المختصة في رد الشخص على الإشعار ولها القيام بأي من الإجراءات الواردة في المادة (١٧) من هذا القانون.\nج-ترفع الجهة المختصة في الهيئة تنسيبها بشأن المخالفة إلى الرئيس متضمناً الإجراءات التي تم اتخاذها والمعلومات والوثائق التي تم جمعها ويقوم الرئيس بعرضها على المجلس لاتخاذ القرار المناسب بشأنها.\nد-إذا تبين للمجلس بأن الشخص ارتكب أي مخالفة لأي من أحكام هذا القانون والأنظمة والتعليمات والقرارات الصادرة بمقتضاه فللمجلس اتخاذ تدبير أو أكثر من التدابير التالية:\n١-إصدار أمر للشخص المخالف بإزالة المخالفة والتوقف عن ارتكابها أو التوقف عن أي إجراء يؤدي إلى ارتكابها حسب مقتضى الحال وذلك خلال المدة التي يحددها.\n٢-فرض غرامة مالية لا يتجاوز مقدارها مائة الف دينار وفقاً لأحكام الفقرة (أ) من المادة (٢٢) من هذا القانون.\n٣-الأمر بوقف إصدار أي أوراق مالية ذات علاقة بالمخالفة أو تداولها.\n٤-تعليق أو إلغاء أو تقييد ترخيص أو اعتماد الشخص المخالف إذا كان مرخصا له أو معتمداً، حسب مقتضى الحال.\n٥-تعليق تعامل المخالف في السوق المالي للمدة التي يراها مناسبة.\nهـ-١-يكون قرار المجلس الصادر وفقا لأحكام الفقرة (د) من هذه المادة مسببا وقابلا للاعتراض عليه خلال أربعة عشر يوم عمل من تاريخ تبليغه، وللمجلس قبول الاعتراض كليا أو جزئيا أو رفضه.\n٢-يبت المجلس في الاعتراض خلال أربعة عشر يوم عمل من تاريخ تسجيله لدى الهيئة ويكون القرار مسببا وقابلا للطعن أمام المحكمة الإدارية.","title":"إجراءات النظر في المخالفات والتدابير","memo":"⭐ للرئيس أو من يفوضه خطياً توجيه إشعار خطي للمخالف يتضمن طبيعة المخالفة وحقه في الدفاع وتوكيل محام\n⭐ تدابير المجلس: أمر بإزالة المخالفة، غرامة لا تتجاوز مائة ألف دينار، وقف إصدار أو تداول الأوراق، تعليق أو إلغاء أو تقييد الترخيص، تعليق التعامل في السوق\n⭐ القرار مسبب ويعترض عليه خلال أربعة عشر يوم عمل من تبليغه، ويبت المجلس خلال أربعة عشر يوم عمل من تسجيله\n⭐ قرار البت في الاعتراض قابل للطعن أمام المحكمة الإدارية","qs":[{"q":"الحد الأقصى للغرامة المالية التي يجوز للمجلس فرضها على مخالف أحكام قانون الأوراق المالية:","o":["مائة ألف دينار","خمسون ألف دينار","مائتا ألف دينار","عشرة آلاف دينار"],"a":0},{"q":"مدة الاعتراض على قرار المجلس الصادر بفرض تدبير على المخالف:","o":["أربعة عشر يوم عمل من تاريخ تبليغه","ثلاثون يوماً من تاريخ صدوره","ستون يوماً من تاريخ تبليغه","سبعة أيام عمل من تاريخ تبليغه"],"a":0},{"q":"يطعن في قرار المجلس الصادر بالبت في الاعتراض أمام:","o":["المحكمة الإدارية","محكمة بداية عمان","محكمة الاستئناف","محكمة التمييز"],"a":0},{"q":"يوجه الإشعار الخطي للشخص المخالف لسماع أقواله وتقديم بيناته من قبل:","o":["الرئيس أو من يفوضه خطياً","مجلس الوزراء","المحكمة المختصة","مدير السوق المالي"],"a":0}]},{"n":"22","chapter":"هيئة الاوراق المالية","notes":[],"source":"أ- يراعي المجلس عند تحديد مقدار الغرامة التي يفرضها على أي شخص ارتكب مخالفة لأحكام هذا القانون والأنظمة والتعليمات والقرارات الصادرة بمقتضاه أياً من الأمور التي تستوجبها حماية التعامل في الأوراق المالية بما في ذلك الاعتبارات التالية:-\n١-إنطواء المخالفة على خداع أو احتيال أو تلاعب أو تجاهل متعمد أو إهمال جسيم للمتطلبات المنصوص عليها في هذا القانون.\n٢-ما يترتب على المخالفة من إضرار بأي شخص بصورة مباشرة أو غير مباشرة .\n٣-ما ينجم عن المخالفة من إثراء غير مشروع أو تجنب خساره مع الأخذ بعين الاعتبار التعويضات التي تم دفعها للمتضررين من ارتكاب المخالفة.\nب-للمجلس احالة المخالفات المرتكبة لاحكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه الى المحكمة المختصة.","title":"معايير تحديد الغرامة والإحالة للمحكمة","memo":"⭐ يراعي المجلس عند تحديد الغرامة: انطواء المخالفة على خداع أو احتيال أو تلاعب أو تجاهل متعمد أو إهمال جسيم\n⭐ الإضرار بأي شخص مباشرة أو غير مباشرة، والإثراء غير المشروع أو تجنب الخسارة مع مراعاة التعويضات المدفوعة\n⭐ للمجلس إحالة المخالفات إلى المحكمة المختصة (محكمة بداية عمان)","qs":[{"q":"يأخذ المجلس بعين الاعتبار عند تقدير الغرامة الناجمة عن الإثراء غير المشروع:","o":["التعويضات التي تم دفعها للمتضررين من المخالفة","رأسمال الشركة المخالفة","عدد سنوات ترخيص المخالف","حجم تداول السوق المالي في يوم المخالفة"],"a":0},{"q":"أي مما يلي ليس من الاعتبارات التي نص عليها القانون عند تحديد مقدار الغرامة؟","o":["جنسية الشخص المخالف","انطواء المخالفة على خداع أو احتيال أو تلاعب","ما يترتب على المخالفة من إضرار بأي شخص","ما ينجم عن المخالفة من إثراء غير مشروع أو تجنب خسارة"],"a":0},{"q":"للمجلس إحالة المخالفات المرتكبة لأحكام قانون الأوراق المالية إلى:","o":["المحكمة المختصة","المحكمة الإدارية","ديوان المحاسبة","مجلس الوزراء"],"a":0}]},{"n":"23","chapter":"هيئة الاوراق المالية","notes":[],"source":"شريطة المعاملة بالمثل للهيئة تزويد أي هيئة للاوراق المالية او أي جهة غير اردنية منظمة لسوق راس المال ، وبناء على طلبها، بمعلومات عن المرخص لهم او عملهم لمساعدتها على أي تحقيق تقوم به ، كما يجوز للهيئة ان تقوم بنفسها باجراء التحقيق لهذه الغاية .","title":"التعاون مع الهيئات الأجنبية","memo":"⭐ شريطة المعاملة بالمثل، للهيئة تزويد أي هيئة أوراق مالية أو جهة غير أردنية منظمة لسوق رأس المال بمعلومات عن المرخص لهم بناء على طلبها\n⭐ يجوز للهيئة أن تجري التحقيق بنفسها لهذه الغاية","qs":[{"q":"يشترط لتزويد الهيئة لهيئة أوراق مالية غير أردنية بمعلومات عن المرخص لهم:","o":["المعاملة بالمثل","موافقة مجلس الوزراء","موافقة المرخص له","صدور قرار قضائي"],"a":0},{"q":"تزود الهيئة الجهات غير الأردنية المنظمة لسوق رأس المال بالمعلومات عن المرخص لهم:","o":["بناءً على طلبها لمساعدتها على أي تحقيق تقوم به","تلقائياً بشكل دوري","بموجب اتفاقية يصادق عليها مجلس الأمة","مقابل رسوم يحددها المجلس"],"a":0}]},{"n":"24","chapter":"هيئة الاوراق المالية","notes":[],"source":"تعتبر المعلومات التي يطلع عليها المفوضون وموظفو الهيئة سرية وذلك تحت طائلة المسؤولية القانونية الا انه يجوز للمجلس ولاسباب مبررة الكشف عن المعلومات التي يراها لازمة لحماية المستثمرين .","title":"سرية المعلومات","memo":"⭐ المعلومات التي يطلع عليها المفوضون وموظفو الهيئة سرية تحت طائلة المسؤولية القانونية\n⭐ يجوز للمجلس لأسباب مبررة الكشف عن المعلومات اللازمة لحماية المستثمرين","qs":[{"q":"الجهة التي يجوز لها الكشف عن المعلومات السرية التي يطلع عليها موظفو الهيئة لحماية المستثمرين:","o":["المجلس ولأسباب مبررة","الرئيس منفرداً","أي مفوض","المحكمة المختصة فقط"],"a":0},{"q":"تعتبر المعلومات التي يطلع عليها المفوضون وموظفو الهيئة:","o":["سرية تحت طائلة المسؤولية القانونية","علنية يجوز نشرها","سرية لمدة سنة واحدة فقط","سرية ما لم يطلبها أي مستثمر"],"a":0}]},{"n":"25","chapter":"شؤون الهيئة المالية","notes":[],"source":"يكون للهيئة موازنة مستقلة وتبدأ سنتها المالية في اليوم الاول من شهر كانون الثاني من السنة وتنتهي في اليوم الحادي والثلاثين من شهر كانون الاول من السنة ذاتها .","title":"موازنة الهيئة وسنتها المالية","memo":"⭐ للهيئة موازنة مستقلة\n⭐ السنة المالية تبدأ في ١ كانون الثاني وتنتهي في ٣١ كانون الأول من السنة ذاتها","qs":[{"q":"تبدأ السنة المالية لهيئة الأوراق المالية في:","o":["اليوم الأول من شهر كانون الثاني","اليوم الأول من شهر نيسان","اليوم الأول من شهر تموز","اليوم الأول من شهر تشرين الأول"],"a":0},{"q":"موازنة هيئة الأوراق المالية:","o":["موازنة مستقلة","جزء من الموازنة العامة للدولة","ملحقة بموازنة وزارة المالية","ملحقة بموازنة البنك المركزي"],"a":0}]},{"n":"26","chapter":"شؤون الهيئة المالية","notes":[],"source":"على المجلس ان يقدم الى مجلس الوزراء خلال الثلاثة اشهر الاولى من بداية السنة المالية تقريرا موجزا عن انشطة الهيئة خلال السنة السابقة مرفقا بنسخ من ميزانيتها السنوية وحساباتها الختامية مصدقة من مدقق حسابات قانوني .","title":"التقرير السنوي للهيئة","memo":"⭐ يقدم المجلس إلى مجلس الوزراء خلال الثلاثة أشهر الأولى من بداية السنة المالية تقريراً موجزاً عن أنشطة السنة السابقة\n⭐ مرفقاً بالميزانية السنوية والحسابات الختامية مصدقة من مدقق حسابات قانوني","qs":[{"q":"يقدم المجلس تقريره الموجز عن أنشطة الهيئة خلال السنة السابقة إلى مجلس الوزراء خلال:","o":["الثلاثة أشهر الأولى من بداية السنة المالية","الشهر الأول من بداية السنة المالية","الستة أشهر الأولى من بداية السنة المالية","أربعة أشهر من انتهاء السنة المالية"],"a":0},{"q":"يرفق بالتقرير السنوي للهيئة الميزانية السنوية والحسابات الختامية مصدقة من:","o":["مدقق حسابات قانوني","ديوان المحاسبة","وزير المالية","رئيس الوزراء"],"a":0}]},{"n":"27","chapter":"شؤون الهيئة المالية","notes":[],"source":"أ- تتقاضى الهيئة رسوما عما يلي :-\n١-تقديم نشرة الاصدار اليها وتسجيل الاوراق المالية لديها .\n٢-منح الترخيص او الاعتماد او تجديدهما وفقا لاحكام هذا القانون.\n٣-تسجيل صندوق الاستثمار المشترك .\n٤-ادراج او قبول تداول الاوراق المالية في السوق المالي .\n٥-عضوية المصدر العام والشركة المساهمة العامة في المركز.\n٦-تداول ونقل ملكية الاوراق المالية .\nب-يحدد مقدار الرسوم المنصوص عليها في الفقرة (أ) من هذه المادة بمقتضى انظمة تصدر استنادا لاحكام هذا القانون.","title":"الرسوم التي تتقاضاها الهيئة","memo":"⭐ تتقاضى الهيئة رسوماً عن: تقديم نشرة الإصدار وتسجيل الأوراق، الترخيص والاعتماد وتجديدهما، تسجيل صندوق الاستثمار، الإدراج، عضوية المصدر العام في المركز، تداول ونقل ملكية الأوراق\n⭐ يحدد مقدار الرسوم بمقتضى أنظمة","qs":[{"q":"يحدد مقدار الرسوم التي تتقاضاها الهيئة بمقتضى:","o":["أنظمة تصدر استناداً لأحكام القانون","تعليمات يصدرها المجلس","قرار من الرئيس","قرار من وزير المالية"],"a":0},{"q":"أي مما يلي لا يُعد من الأمور التي تتقاضى الهيئة عنها رسوماً وفقاً للمادة (٢٧)؟","o":["تقديم الشكاوى من المستثمرين","تسجيل صندوق الاستثمار المشترك","تداول ونقل ملكية الأوراق المالية","منح الترخيص أو الاعتماد أو تجديدهما"],"a":0}]},{"n":"28","chapter":"شؤون الهيئة المالية","notes":[],"source":"تتكون الموارد المالية للهيئة مما يلي :-\nأ-الرسوم وبدل الخدمات والعمولات التي تتقاضاها وفقا لاحكام هذا القانون والانظمة والتعليمات الصادرة بمقتضاه.\nب-الغرامات التي يفرضها المجلس بمقتضى احكام هذا القانون والغرامات التي تفرضها المحاكم .\nج-بدل استخدام مرافقها وعوائد استثمار اموالها وبيع اصولها.\nد-المساعدات والهبات والتبرعات وأي موارد أخرى شريطة موافقة مجلس الوزراء عليها.\nهـ-المبالغ التي تخصصها الحكومة لها في الموازنة العامة او لتغطية العجز في حساب الايرادات واجمالي النفقات .","title":"الموارد المالية للهيئة","memo":"⭐ الموارد: الرسوم وبدل الخدمات والعمولات، الغرامات (من المجلس والمحاكم)، بدل استخدام المرافق وعوائد الاستثمار وبيع الأصول\n⭐ المساعدات والهبات والتبرعات بشرط موافقة مجلس الوزراء\n⭐ المبالغ التي تخصصها الحكومة في الموازنة العامة أو لتغطية العجز","qs":[{"q":"يشترط لقبول المساعدات والهبات والتبرعات كمورد مالي للهيئة موافقة:","o":["مجلس الوزراء","مجلس المفوضين","رئيس الوزراء","وزير المالية"],"a":0},{"q":"أي مما يلي لا يعد من الموارد المالية للهيئة وفقاً للقانون؟","o":["أرباح المتاجرة بأسهم الشركات المساهمة العامة","الغرامات التي تفرضها المحاكم","بدل استخدام مرافقها","المبالغ التي تخصصها الحكومة لها في الموازنة العامة"],"a":0}]},{"n":"29","chapter":"شؤون الهيئة المالية","notes":[],"source":"أ- على الرغم مما ورد في أي تشريع آخر، تؤول الى الهيئة جميع الرسوم وبدل الخدمات والعمولات التي تستوفيها والغرامات المحكوم بها من المجلس او المحاكم بموجب احكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه .\nب-اذا وقع عجز في حساب الايرادات واجمالي النفقات لاي سنة مالية ، تقوم الحكومة بتغطية ذلك العجز .","title":"أيلولة الإيرادات وتغطية العجز","memo":"⭐ على الرغم مما ورد في أي تشريع آخر، تؤول للهيئة جميع الرسوم وبدل الخدمات والعمولات والغرامات المحكوم بها من المجلس أو المحاكم\n⭐ تغطي الحكومة أي عجز في حساب الإيرادات وإجمالي النفقات لأي سنة مالية","qs":[{"q":"إذا وقع عجز في حساب الإيرادات وإجمالي النفقات للهيئة لأي سنة مالية فإن الذي يقوم بتغطيته:","o":["الحكومة","صندوق حماية المستثمرين","السوق المالي","مركز إيداع الأوراق المالية"],"a":0},{"q":"الغرامات المحكوم بها من المحاكم بموجب قانون الأوراق المالية تؤول إلى:","o":["هيئة الأوراق المالية","الخزينة العامة","صندوق حماية المستثمرين","وزارة العدل"],"a":0}]},{"n":"30","chapter":"شؤون الهيئة المالية","notes":[],"source":"تخضع حسابات الهيئة لرقابة ديوان المحاسبة ، وعلى المجلس تعيين مدقق حسابات قانوني وتحديد بدل اتعابه .","title":"الرقابة على حسابات الهيئة","memo":"⭐ تخضع حسابات الهيئة لرقابة ديوان المحاسبة\n⭐ يعين المجلس مدقق حسابات قانونياً ويحدد بدل أتعابه","qs":[{"q":"تخضع حسابات هيئة الأوراق المالية لرقابة:","o":["ديوان المحاسبة","وزارة المالية","البنك المركزي","دائرة مراقبة الشركات"],"a":0},{"q":"الجهة التي تعين مدقق الحسابات القانوني للهيئة وتحدد بدل أتعابه:","o":["المجلس","مجلس الوزراء","ديوان المحاسبة","الرئيس"],"a":0}]},{"n":"31","chapter":"شؤون الهيئة المالية","notes":[],"source":"تعتبر اموال الهيئة وحقوقها لدى الغير اموالا عامة يتم تحصيلها وفقا لاحكام قانون تحصيل الاموال الاميرية المعمول به ، ولهذه الغاية يمارس الرئيس صلاحيات الحاكم الاداري ولجنة تحصيل الاموال الاميرية المنصوص عليها في ذلك القانون .","title":"تحصيل أموال الهيئة","memo":"⭐ أموال الهيئة وحقوقها لدى الغير أموال عامة تحصل وفق قانون تحصيل الأموال الأميرية\n⭐ يمارس الرئيس صلاحيات الحاكم الإداري ولجنة تحصيل الأموال الأميرية","qs":[{"q":"تحصل أموال الهيئة وحقوقها لدى الغير وفقاً لأحكام:","o":["قانون تحصيل الأموال الأميرية","قانون التنفيذ","قانون أصول المحاكمات المدنية","قانون ضريبة الدخل"],"a":0},{"q":"يمارس صلاحيات الحاكم الإداري ولجنة تحصيل الأموال الأميرية لغايات تحصيل أموال الهيئة:","o":["الرئيس","وزير المالية","المحافظ","مجلس المفوضين"],"a":0}]},{"n":"32","chapter":"شؤون الهيئة المالية","notes":[],"source":"تتمتع الهيئة بجميع الامتيازات والاعفاءات الممنوحة للوزارات والدوائر الحكومية والمؤسسات الرسمية العامة.","title":"امتيازات الهيئة وإعفاءاتها","memo":"⭐ تتمتع الهيئة بجميع الامتيازات والإعفاءات الممنوحة للوزارات والدوائر الحكومية والمؤسسات الرسمية العامة","qs":[{"q":"تتمتع هيئة الأوراق المالية بالامتيازات والإعفاءات الممنوحة لـ:","o":["الوزارات والدوائر الحكومية والمؤسسات الرسمية العامة","الشركات المساهمة العامة","البنوك المرخصة","المنظمات الدولية"],"a":0}]},{"n":"33","chapter":"صندوق حماية المستثمرين","notes":[],"source":"أ- تنشىء الهيئة صندوقاً يسمى (صندوق حماية المستثمرين) يتمتع بالشخصية الاعتبارية والاستقلال المالي.\nب-تحدد سائر الامور المتعلقة بالصندوق بما في ذلك اهدافه وكيفية ادارته والزامية العضوية فيه وموارده المالية وادارة موجوداته وآلية عمله والالتزامات المترتبة عليه للمستثمرين بالاوراق المالية الاردنية وتصفيته بموجب نظام يصدر لهذه الغاية.\nج-يخضع الصندوق لرقابة الهيئة واشرافها .","title":"صندوق حماية المستثمرين","memo":"⭐ تنشئ الهيئة صندوق حماية المستثمرين بشخصية اعتبارية واستقلال مالي\n⭐ أهدافه وإدارته وإلزامية العضوية وموارده وتصفيته تحدد بموجب نظام\n⭐ يخضع لرقابة الهيئة وإشرافها","qs":[{"q":"تحدد أهداف صندوق حماية المستثمرين وكيفية إدارته وإلزامية العضوية فيه وتصفيته بموجب:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها المجلس","قرار من رئيس الهيئة","النظام الداخلي للسوق المالي"],"a":0},{"q":"الجهة التي تنشئ صندوق حماية المستثمرين ويخضع لرقابتها وإشرافها:","o":["هيئة الأوراق المالية","مجلس الوزراء","مركز إيداع الأوراق المالية","السوق المالي"],"a":0}]},{"n":"34","chapter":"الافصاح","notes":[],"source":"أ-١- لا يجوز لاي شخص ان يقوم باي عرض عام الا اذا تقدم بنشرة اصدار الى الهيئة ومرفقا بها جميع المعلومات والبيانات التي تمكن المستثمر من اتخاذ قراره الاستثماري.\n٢-يصدر المجلس تعليمات يحدد فيها المعلومات والبيانات الواجب تضمينها في نشرة الاصدار وارفاقها بها .\nب-يتم عرض الاوراق المالية باي من الوسائل التالية:-\n١-نشرة الاصدار .\n٢-اعلان يتضمن ملخصاً عن نشرة الاصدار واي معلومات او بيانات تتطلبها الهيئة او تسمح بها بموجب التعليمات التي يصدرها المجلس .\n٣-مادة مكتوبة مرفقة مع نشرة الاصدار او تسبقها على ان تكون نشرة الاصدار قد اصبحت نافذة .\nج-لا يعتبر بيع الاوراق المالية ، بموجب العرض العام ، ملزما للمشتري الا اذا تسلم نسخة من نشرة الاصدار النافذة.\nد-على كل شخص يرغب في تسويق أو بيع أوراق مالية غير أردنية داخل المملكة الحصول على موافقة الهيئة المسبقة وفقاً للتعليمات التي يصدرها المجلس لهذه الغاية.","title":"نشرة الإصدار ووسائل عرض الأوراق المالية","memo":"⭐ لا يجوز أي عرض عام إلا بتقديم نشرة إصدار للهيئة مرفقاً بها المعلومات اللازمة لاتخاذ القرار الاستثماري\n⭐ وسائل العرض: نشرة الإصدار، إعلان يتضمن ملخصها، مادة مكتوبة مرفقة أو سابقة بشرط نفاذ النشرة\n⭐ البيع بموجب العرض العام غير ملزم للمشتري إلا إذا تسلم نسخة من نشرة الإصدار النافذة\n⭐ تسويق أو بيع أوراق مالية غير أردنية في المملكة يتطلب موافقة الهيئة المسبقة","qs":[{"q":"لا يعتبر بيع الأوراق المالية بموجب العرض العام ملزماً للمشتري إلا إذا:","o":["تسلم نسخة من نشرة الإصدار النافذة","سدد كامل ثمن الأوراق المالية","تم تسجيل البيع لدى مركز الإيداع","مضى ثلاثون يوماً على الاكتتاب"],"a":0},{"q":"يشترط لتسويق أو بيع أوراق مالية غير أردنية داخل المملكة:","o":["الحصول على موافقة الهيئة المسبقة","موافقة البنك المركزي","موافقة مجلس الوزراء","إدراجها في السوق المالي"],"a":0},{"q":"الجهة التي تحدد بتعليمات المعلومات والبيانات الواجب تضمينها في نشرة الإصدار:","o":["المجلس","مجلس الوزراء","مدير الإصدار","السوق المالي"],"a":0},{"q":"يجوز عرض الأوراق المالية بمادة مكتوبة مرفقة مع نشرة الإصدار أو تسبقها بشرط:","o":["أن تكون نشرة الإصدار قد أصبحت نافذة","موافقة مدير الإصدار","نشرها في صحيفتين يوميتين","ألا يتجاوز عدد المستثمرين ثلاثين شخصاً"],"a":0}]},{"n":"35","chapter":"الافصاح","notes":[],"source":"أ- يجب ان تشمل المعلومات والبيانات التي تقدم مرفقة بنشرة الاصدار، اضافة الى أي متطلبات اخرى تفرضها الهيئة وفقا لاحكام المادة (٣٤) من هذا القانون، نسخا مما يلي :-\n١-أي اتفاقية او اتفاقيات تم ابرامها مع مدير الاصدار .\n٢-الرأي القانوني المتعلق بقانونية الاصدار .\n٣-عقد تاسيس المصدر اذا كان شركة مساهمة عامة او شركة مساهمة خاصة ونسخة من نظامها الاساسي واي مستندات لها علاقة بهذه الشركة .\n٤-عقد الشراكة او عقد التاسيس واي وثيقة اخرى تتعلق بتنظيمها اذا كان المصدر شركة او شكلا آخر، ونسخة من الاتفاقيات الاساسية والوثائق الرسمية التي تؤثر في اسعار الاسهم او الاسناد او ادوات الدين التي عرضت او التي سيتم عرضها .\n٥-جميع العقود التي تحتوي على معلومات جوهرية وأي حقوق امتياز، ويجوز للهيئة عدم الافصاح عن مضمون أي جزء من أي من تلك العقود اذا رأت ان الافصاح عن هذا الجزء قد يؤدي الى اضعاف قيمة العقد وانها غير ضرورية لحماية المستثمرين .\n٦-الاتفاقيات المعقودة بين المصدر ووكيل الدفع والحافظ الامين للاوراق المالية محل العرض.\nب-يجوز للهيئة، بمقتضى تعليمات يصدرها المجلس ، طلب أي معلومات او بيانات اضافة لما ورد في الفقرة (أ) من هذه المادة ليتم تضمينها في وثيقة خطية او الكترونية وارفاقها بنشرة الاصدار وذلك بموجب تعليمات يصدرها المجلس .","title":"المرفقات الإلزامية لنشرة الإصدار","memo":"⭐ ترفق بالنشرة نسخ من: اتفاقيات مدير الإصدار، الرأي القانوني بقانونية الإصدار، عقد التأسيس والنظام الأساسي، العقود ذات المعلومات الجوهرية وحقوق الامتياز، الاتفاقيات مع وكيل الدفع والحافظ الأمين\n⭐ يجوز للهيئة عدم الإفصاح عن جزء من العقود إذا كان الإفصاح يضعف قيمة العقد وغير ضروري لحماية المستثمرين\n⭐ للهيئة طلب معلومات إضافية بمقتضى تعليمات يصدرها المجلس","qs":[{"q":"أي مما يلي لا يُعد من المرفقات التي نصت عليها المادة (٣٥) لنشرة الإصدار؟","o":["قائمة بأسماء المستثمرين المكتتبين","الرأي القانوني المتعلق بقانونية الإصدار","أي اتفاقية تم إبرامها مع مدير الإصدار","الاتفاقيات المعقودة بين المصدر ووكيل الدفع والحافظ الأمين"],"a":0},{"q":"يجوز للهيئة عدم الإفصاح عن مضمون أي جزء من العقود المرفقة بنشرة الإصدار إذا رأت أن الإفصاح عنه:","o":["قد يؤدي إلى إضعاف قيمة العقد وأنه غير ضروري لحماية المستثمرين","يتطلب موافقة الأطراف المتعاقدة","يتعلق بعقد مدته أقل من سنة","يتعلق بعقد قيمته أقل من مائة ألف دينار"],"a":0},{"q":"تطلب الهيئة أي معلومات أو بيانات إضافية لإرفاقها بنشرة الإصدار بمقتضى:","o":["تعليمات يصدرها المجلس","نظام يصدره مجلس الوزراء","قرار من مدير الإصدار","طلب من المحكمة المختصة"],"a":0}]},{"n":"36","chapter":"الافصاح","notes":[],"source":"يجوز للمجلس وفق اسس يحددها الاعفاء من تقديم نشرة اصدار في أي من الحالات التالية :-\nأ-اذا كان عدد المستثمرين الذين يوجه العرض العام اليهم محدودا ولديهم القدرة على تقييم مخاطر الاستثمار وتحملها.\nب-اذا كانت الاموال المنوي تحصيلها بواسطة العرض محدودة .\nج-اذا كان الافصاح المقدم للمستثمرين دقيقا وكافيا لاعتباره بديلا لنشرة الاصدار .","title":"حالات الإعفاء من نشرة الإصدار","memo":"⭐ للمجلس وفق أسس يحددها الإعفاء من نشرة الإصدار إذا: كان عدد المستثمرين محدوداً ولديهم القدرة على تقييم المخاطر وتحملها\n⭐ أو كانت الأموال المنوي تحصيلها محدودة\n⭐ أو كان الإفصاح المقدم دقيقاً وكافياً كبديل للنشرة","qs":[{"q":"الجهة المختصة بالإعفاء من تقديم نشرة الإصدار:","o":["المجلس وفق أسس يحددها","مجلس الوزراء","السوق المالي","مدير الإصدار"],"a":0},{"q":"يجوز الإعفاء من تقديم نشرة الإصدار في جميع الحالات التالية باستثناء:","o":["إذا كان المصدر شركة مساهمة عامة قائمة منذ أكثر من خمس سنوات","إذا كانت الأموال المنوي تحصيلها بواسطة العرض محدودة","إذا كان عدد المستثمرين محدوداً ولديهم القدرة على تقييم مخاطر الاستثمار وتحملها","إذا كان الإفصاح المقدم للمستثمرين دقيقاً وكافياً لاعتباره بديلاً لنشرة الإصدار"],"a":0}]},{"n":"37","chapter":"الافصاح","notes":[],"source":"أ- يشترط في نشرة الاصدار ان تكون مقدمة وفقا للانموذج الخطي او الالكتروني الذي تحدده الهيئة بموجب التعليمات الصادرة عن المجلس وان تكون موقعة من كل من رئيس مجلس الادارة وكل من المدير العام او المدير التنفيذي والمدير المالي للمصدر إضافة الى من يلي :-\n١-مؤسسين يملكون أكثر من (٧٥%) من أسهم التأسيس إذا كانت الشركة في مرحلة التأسيس.\n٢-غالبية اعضاء مجلس ادارة المصدر اذا كان شركة مساهمة عامة او شركة مساهمة خاصة .\n٣-مدير الاصدار او مديري الاصدار، حسب مقتضى الحال.\n٤-مدقق الحسابات الذي صادق على صحة التقارير المالية المرفقة بالنشرة .\nب-يجوز للمجلس ان يحدد صيغة او شكلا معينا للتوقيع الالكتروني لاعتماده يكون مساويا في حجيته للتوقيع الخطي وفقاً لقانون المعاملات الالكترونية .","title":"شكل نشرة الإصدار والتوقيع عليها","memo":"⭐ توقع النشرة من رئيس مجلس الإدارة والمدير العام أو التنفيذي والمدير المالي للمصدر\n⭐ إضافة إلى: مؤسسين يملكون أكثر من (٧٥%) من أسهم التأسيس (في مرحلة التأسيس)، غالبية أعضاء مجلس الإدارة، مدير الإصدار، مدقق الحسابات المصادق على التقارير المالية\n⭐ للمجلس تحديد صيغة للتوقيع الإلكتروني مساوية في حجيتها للخطي وفق قانون المعاملات الإلكترونية","qs":[{"q":"إذا كانت الشركة في مرحلة التأسيس، يجب أن توقع نشرة الإصدار من مؤسسين يملكون:","o":["أكثر من (٧٥%) من أسهم التأسيس","أكثر من (٥٠%) من أسهم التأسيس","أكثر من (٤٠%) من أسهم التأسيس","جميع أسهم التأسيس"],"a":0},{"q":"يجب أن توقع نشرة الإصدار إذا كان المصدر شركة مساهمة عامة من:","o":["غالبية أعضاء مجلس إدارة المصدر","ثلث أعضاء مجلس إدارة المصدر","جميع أعضاء مجلس إدارة المصدر","رئيس مجلس الإدارة فقط"],"a":0},{"q":"أي مما يلي لا يُشترط توقيعه على نشرة الإصدار وفقاً للمادة (٣٧)؟","o":["المستشار القانوني للمصدر","المدير المالي للمصدر","مدير الإصدار","مدقق الحسابات الذي صادق على صحة التقارير المالية المرفقة"],"a":0}]},{"n":"38","chapter":"الافصاح","notes":[],"source":"أ- تصبح نشرة الاصدار علنية بمجرد موافقة المجلس على إنفاذها.\nب-على الهيئة تمكين الجمهور من الاطلاع على نشرة الاصدار النافذة وغيرها من المعلومات المقدمة وفق احكام هذا القانون .\nج-يجوز للمجلس، بناء على طلب مبرر من المصدر او مدير الاصدار ، ان يقرر اعتبار بعض المعلومات المقدمة مع نشرة الاصدار سرية على اساس ان عرضها للجمهور قد يؤدي الى افشاء اسرار تجارية، ولهذه الغاية يقوم المجلس بتنظيم جلسة سماع اقوال خاصة لاصدار القرار المناسب بشأن الطلب .","title":"علنية نشرة الإصدار وسرية بعض معلوماتها","memo":"⭐ تصبح نشرة الإصدار علنية بمجرد موافقة المجلس على إنفاذها\n⭐ على الهيئة تمكين الجمهور من الاطلاع على النشرة النافذة\n⭐ للمجلس بطلب مبرر من المصدر أو مدير الإصدار اعتبار بعض المعلومات سرية لتجنب إفشاء أسرار تجارية، بعد جلسة سماع أقوال خاصة","qs":[{"q":"تصبح نشرة الإصدار علنية:","o":["بمجرد موافقة المجلس على إنفاذها","بمجرد تقديمها إلى الهيئة","بعد مضي ثلاثين يوماً على تقديمها","بعد نشرها في الجريدة الرسمية"],"a":0},{"q":"يجوز للمجلس اعتبار بعض المعلومات المقدمة مع نشرة الإصدار سرية بناءً على طلب مبرر من:","o":["المصدر أو مدير الإصدار","أي مستثمر","مدقق الحسابات","السوق المالي"],"a":0},{"q":"السبب الذي يبرر اعتبار بعض معلومات نشرة الإصدار سرية:","o":["أن عرضها للجمهور قد يؤدي إلى إفشاء أسرار تجارية","أنها تتعلق بمكافآت أعضاء مجلس الإدارة","أنها تتعلق بالتوقعات المستقبلية للأرباح","أن المصدر شركة مساهمة خاصة"],"a":0}]},{"n":"39","chapter":"الافصاح","notes":[],"source":"تصبح نشرة الاصدار نافذة المفعول بعد مضي ثلاثين يوما على تاريخ تقديمها الى الهيئة، الا اذا قرر المجلس وخلال هذه المدة نفاذ نشرة الاصدار او رفضها ، وله تحديد المدة التي تكون فيها هذه النشرة نافذة المفعول .","title":"نفاذ نشرة الإصدار","memo":"⭐ تصبح النشرة نافذة بعد مضي ثلاثين يوماً على تاريخ تقديمها للهيئة\n⭐ إلا إذا قرر المجلس خلال هذه المدة نفاذها أو رفضها\n⭐ للمجلس تحديد مدة نفاذ النشرة","qs":[{"q":"تصبح نشرة الإصدار نافذة المفعول بعد مضي:","o":["ثلاثين يوماً على تاريخ تقديمها إلى الهيئة","أربعة عشر يوماً على تاريخ تقديمها إلى الهيئة","ستين يوماً على تاريخ تقديمها إلى الهيئة","تسعين يوماً على تاريخ تقديمها إلى الهيئة"],"a":0},{"q":"حالة عملية: قدمت شركة نشرة إصدار للهيئة، وبعد عشرين يوماً قرر المجلس نفاذها. ما الحكم؟","o":["تصبح نافذة بقرار المجلس دون انتظار انقضاء الثلاثين يوماً","لا تصبح نافذة إلا بعد مضي ثلاثين يوماً","قرار المجلس باطل لصدوره قبل انقضاء المدة","تحتاج إلى مصادقة مجلس الوزراء"],"a":0}]},{"n":"40","chapter":"الافصاح","notes":[],"source":"على المصدر اعلام الهيئة ، خطيا او الكترونيا ، باي تغيير يطرأ على المعلومات الواردة في نشرة الاصدار حال حدوثه سواء تم اعلان نفاذ النشرة ام لم يتم .","title":"الإفصاح عن التغييرات في نشرة الإصدار","memo":"⭐ على المصدر إعلام الهيئة خطياً أو إلكترونياً بأي تغيير على معلومات النشرة حال حدوثه\n⭐ سواء تم إعلان نفاذ النشرة أم لم يتم","qs":[{"q":"يلتزم المصدر بإعلام الهيئة بأي تغيير يطرأ على المعلومات الواردة في نشرة الإصدار:","o":["حال حدوثه، سواء تم إعلان نفاذ النشرة أم لم يتم","خلال ثلاثين يوماً من حدوثه","بعد إعلان نفاذ النشرة فقط","قبل إعلان نفاذ النشرة فقط"],"a":0},{"q":"وسيلة إعلام المصدر للهيئة بالتغييرات على معلومات نشرة الإصدار:","o":["خطياً أو إلكترونياً","خطياً فقط","بإعلان في صحيفتين يوميتين","عن طريق السوق المالي"],"a":0}]},{"n":"41","chapter":"الافصاح","notes":[],"source":"أ- تقوم الهيئة بمراجعة نشرة الاصدار والمعلومات المرفقة بها وفق احكام المواد (٣٤) و (٣٥) و (٣٧) من هذا القانون لتحديد فيما اذا كانت هذه النشرة تحقق متطلبات هذا القانون والانظمة والتعليمات والقرارات الصادرة بموجبه ، ولهذه الغاية ينظم المجلس جلسات سماع اقوال لتقييم صحة ودقة وكفاية المعلومات التي تم تقديمها اليها .\nب-للمجلس رفض نشرة الاصدار او تعليق نفاذها اذا تبين له ما يلي:-\n١-ان نشرة الاصدار او ايا من المعلومات المرفقة بها لا تتفق ومتطلبات هذا القانون او الانظمة او التعليمات او القرارات الصادرة بمقتضاه .\n٢-ان نشرة الاصدار او ايا من المعلومات المرفقة بها تتضمن بيانات غير صحيحة او غير دقيقة او مضللة ، او انها لا تتضمن معلومات جوهرية تمكن المستثمر من اتخاذ قراره الاستثماري او اذا كانت تتضمن معلومات تم عرضها بصورة تجعل المعلومات الاخرى في النشرة غير صحيحة او غير دقيقة او مضللة .\n٣-اذا لم يتم دفع الرسوم المقررة على تقديم وتسجيل نشرة الاصدار.","title":"مراجعة نشرة الإصدار ورفضها","memo":"⭐ الهيئة تراجع نشرة الإصدار وفق المواد (٣٤) و(٣٥) و(٣٧)، والمجلس ينظم جلسات سماع أقوال لتقييم صحة ودقة وكفاية المعلومات\n⭐ للمجلس رفض النشرة أو تعليق نفاذها: عدم توافقها مع القانون، أو تضمنها بيانات غير صحيحة أو مضللة أو إغفال معلومات جوهرية، أو عدم دفع الرسوم المقررة","qs":[{"q":"الجهة التي تنظم جلسات سماع أقوال لتقييم صحة ودقة وكفاية المعلومات المقدمة في نشرة الإصدار هي:","o":["مجلس مفوضي الهيئة","السوق المالي","مركز إيداع الأوراق المالية","وزير الصناعة والتجارة"],"a":0},{"q":"للمجلس عند تبين مخالفة نشرة الإصدار لمتطلبات القانون أن:","o":["يرفض النشرة أو يعلق نفاذها","يحيل المصدر إلى التصفية الإجبارية","يلغي تسجيل المصدر لدى المركز","يفرض على المصدر عرض تملك عام"],"a":0},{"q":"أي مما يلي لا يعد من الحالات التي يجوز فيها للمجلس رفض نشرة الإصدار أو تعليق نفاذها؟","o":["عدم تحقيق المصدر أرباحاً في السنة المالية السابقة","عدم دفع الرسوم المقررة على تقديم وتسجيل النشرة","تضمن النشرة بيانات غير دقيقة أو مضللة","عدم تضمن النشرة معلومات جوهرية تمكن المستثمر من اتخاذ قراره الاستثماري"],"a":0}]},{"n":"42","chapter":"الافصاح","notes":[],"source":"يعد مخالفا لاحكام هذا القانون :-\nأ-المصدر الذي يقدم نشرة اصدار تتضمن بيانات غير صحيحة تتعلق بمعلومات جوهرية او حذفا لتلك المعلومات.\nب-الشخص الذي يوقع على نشرة اصدار تتضمن بيانات غير صحيحة متعلقة بمعلومات جوهرية او حذفا لتلك المعلومات .\nج-الشخص الذي لا يلتزم بمتطلبات نشرة الاصدار المحددة من الهيئة .\nد-الشخص الذي يقوم بعرض أوراق مالية للبيع قبل تسجيلها لدى الهيئة.","title":"مخالفات نشرة الإصدار","memo":"⭐ يعد مخالفاً: المصدر الذي يقدم نشرة فيها بيانات غير صحيحة عن معلومات جوهرية أو حذف لها، ومن يوقع عليها\n⭐ ويعد مخالفاً من لا يلتزم بمتطلبات النشرة المحددة من الهيئة، ومن يعرض أوراقاً مالية للبيع قبل تسجيلها لدى الهيئة","qs":[{"q":"قامت شركة بعرض أسهمها للبيع على الجمهور قبل تسجيلها لدى الهيئة، فإن هذا التصرف:","o":["يعد مخالفاً لأحكام قانون الأوراق المالية","جائز إذا تم الإعلان عنه في صحيفة يومية","جائز إذا كان العرض لا يتجاوز (٤٠%) من الأسهم","جائز بموافقة السوق المالي"],"a":0},{"q":"وفق القانون، يعد مخالفاً لأحكامه الشخص الذي يوقع على نشرة إصدار تتضمن:","o":["بيانات غير صحيحة متعلقة بمعلومات جوهرية أو حذفاً لتلك المعلومات","توقعات مستقبلية لأرباح المصدر","أسماء أعضاء مجلس إدارة المصدر","بيانات مالية مدققة من مدقق حسابات قانوني"],"a":0}]},{"n":"43","chapter":"الافصاح","notes":[],"source":"أ- على كل مصدر ان يقدم الى الهيئة ، ووفقا للتعليمات التي يصدرها المجلس ، التقارير الدورية المبينة ادناه وان يقوم بنشرها:-\n١-تقريرا سنويا، يتضمن البيانات المالية مدققة من مدقق حسابات قانوني خلال تسعين يوما من تاريخ انتهاء سنته المالية .\n٢-تقرير ربع سنوي يقدم خلال ثلاثين يوما من تاريخ انتهاء الربع المعني مراجعاً من مدقق حسابات قانوني.\n٣-تقريرا عن نتائج اعماله الاولية بعد قيام مدقق حسابات قانوني باجراء عملية المراجعة الاولية لها ، وذلك خلال خمسة واربعين يوما من انتهاء سنته المالية حدا اعلى .\n٤-تقريرا يتعلق بانتخاب مجلس الادارة واي تغيير في تشكيلة او هوية أي من اعضائه.\nب-للمجلس تنظيم شكل ومحتوى التقارير الواردة في الفقرة (أ) من هذه المادة على ان يحدد فيها الاشخاص الذين يتعين عليهم التوقيع عليها مع الاخذ بعين الاعتبار امكانية اعتماد التقارير المقدمة بصورة الكترونية .\nج-يجوز نشر التقارير المشار اليها في الفقرة (أ) من هذه المادة في صحيفة يومية محلية او بواسطة وسائل البريد الخطي او الالكتروني لعنوان كل من حملة الاوراق المالية او بواسطة أي وسيلة اخرى تعتمدها الهيئة وفق احكام التعليمات التي يصدرها المجلس .\nد-على كل مصدر اصدار بيان علني بأي معلومة جوهرية فور علمه بها وتزويد الهيئة بها .","title":"التقارير الدورية للمصدر","memo":"⭐ التقرير السنوي (بيانات مالية مدققة) خلال (٩٠) يوماً من انتهاء السنة المالية\n⭐ التقرير ربع السنوي خلال (٣٠) يوماً من انتهاء الربع مراجعاً من مدقق حسابات قانوني\n⭐ تقرير النتائج الأولية خلال (٤٥) يوماً من انتهاء السنة المالية حداً أعلى، وتقرير عن انتخاب مجلس الإدارة وأي تغيير فيه\n⭐ على المصدر إصدار بيان علني بأي معلومة جوهرية فور علمه بها وتزويد الهيئة بها","qs":[{"q":"يلتزم المصدر بتقديم تقريره السنوي المتضمن البيانات المالية المدققة إلى الهيئة خلال:","o":["تسعين يوماً من تاريخ انتهاء سنته المالية","ثلاثين يوماً من تاريخ انتهاء سنته المالية","خمسة وأربعين يوماً من تاريخ انتهاء سنته المالية","ستين يوماً من تاريخ انتهاء سنته المالية"],"a":0},{"q":"يقدم المصدر التقرير ربع السنوي مراجعاً من مدقق حسابات قانوني خلال:","o":["ثلاثين يوماً من تاريخ انتهاء الربع المعني","خمسة عشر يوماً من تاريخ انتهاء الربع المعني","خمسة وأربعين يوماً من تاريخ انتهاء الربع المعني","تسعين يوماً من تاريخ انتهاء الربع المعني"],"a":0},{"q":"الحد الأعلى لتقديم المصدر تقريراً عن نتائج أعماله الأولية بعد المراجعة الأولية من مدقق الحسابات هو:","o":["خمسة وأربعون يوماً من انتهاء سنته المالية","ثلاثون يوماً من انتهاء سنته المالية","تسعون يوماً من انتهاء سنته المالية","ستون يوماً من انتهاء سنته المالية"],"a":0},{"q":"علم مصدر بمعلومة جوهرية تتعلق بنشاطه، فإن عليه:","o":["إصدار بيان علني بها فور علمه بها وتزويد الهيئة بها","تضمينها في التقرير ربع السنوي التالي","تضمينها في التقرير السنوي فقط","إبلاغ السوق المالي بها خلال ثلاثين يوماً"],"a":0}]},{"n":"44","chapter":"الافصاح","notes":[],"source":"تحدد التعليمات التي يصدرها المجلس الاشخاص الذين يتوجب عليهم اعلام الهيئة عما يملكونه او يقع تحت تصرفهم من الاوراق المالية من أي اصدارات لحسابهم الشخصي او لحسابات تحت تصرفهم .","title":"الإفصاح عن ملكية الأوراق المالية","memo":"⭐ تعليمات يصدرها المجلس تحدد الأشخاص الذين يتوجب عليهم إعلام الهيئة عما يملكونه أو يقع تحت تصرفهم من أوراق مالية لحسابهم الشخصي أو لحسابات تحت تصرفهم","qs":[{"q":"يلتزم الأشخاص المحددون بالتعليمات بإعلام الهيئة عن الأوراق المالية التي:","o":["يملكونها أو تقع تحت تصرفهم لحسابهم الشخصي أو لحسابات تحت تصرفهم","يرغبون في بيعها خلال السنة المالية فقط","يملكها أقاربهم من الدرجة الثالثة","تزيد قيمتها على مليون دينار فقط"],"a":0},{"q":"تحدد الأشخاص الذين يتوجب عليهم إعلام الهيئة عما يملكونه أو يقع تحت تصرفهم من الأوراق المالية بموجب:","o":["تعليمات يصدرها المجلس","نظام يصدره مجلس الوزراء","الأنظمة الداخلية للسوق المالي","تعليمات يصدرها مركز إيداع الأوراق المالية"],"a":0}]},{"n":"45","chapter":"الافصاح","notes":[],"source":"أ- لا يجوز لاي شخص طلب شراء اوراق مالية او مبادلتها بهدف تملك (٤٠ %) أو أكثر من الاوراق المالية المصدرة من مصدر عام الا عن طريق عرض تملك عام وفقاً لنظام يصدر لهذه الغاية.\nب-يعتبر عرض التملك العام لشراء او مبادلة أي اوراق مالية عرضا لجميع مالكي هذه الاوراق .\nج-على الشخص الذي قدم عرض التملك العام ان يدفع الى أي من الراغبين في بيع الاوراق المالية التي يملكونها ، محل العرض ، مبلغا مساويا لاعلى سعر دفعه الى أي من بائعي هذه الاوراق المالية دون تمييز .\nد-اذا كان عدد الاوراق المالية المعروضة للبيع او المبادلة في عرض التملك العام اكثر من عدد الاوراق المالية المطلوب شراؤها او مبادلتها ، فيكون الشراء او المبادلة من المالكين الراغبين في البيع او المبادلة كل بنسبة عدد الاوراق المالية المطلوب شراؤها او مبادلتها مقارنة مع مجمل عدد الاوراق المالية المعروضة للبيع او المبادلة .","title":"عرض التملك العام","memo":"⭐ لا يجوز طلب شراء أو مبادلة أوراق مالية بهدف تملك (٤٠%) أو أكثر من أوراق مصدر عام إلا عن طريق عرض تملك عام وفق نظام\n⭐ عرض التملك العام عرض لجميع مالكي الأوراق، ويدفع لكل بائع مبلغاً مساوياً لأعلى سعر دفعه لأي بائع دون تمييز\n⭐ إذا زادت الأوراق المعروضة عن المطلوبة يكون الشراء من كل مالك بنسبة المطلوب إلى مجمل المعروض","qs":[{"q":"لا يجوز لأي شخص طلب شراء أوراق مالية بهدف تملك نسبة معينة أو أكثر من الأوراق المالية المصدرة من مصدر عام إلا عن طريق عرض تملك عام، وهذه النسبة هي:","o":["(٤٠%)","(٢٥%)","(٥٠%)","(١٠%)"],"a":0},{"q":"في عرض التملك العام، يلتزم مقدم العرض بأن يدفع لأي من الراغبين في البيع مبلغاً مساوياً:","o":["لأعلى سعر دفعه إلى أي من بائعي هذه الأوراق المالية دون تمييز","لمتوسط الأسعار التي دفعها للبائعين","لسعر إغلاق الورقة في السوق المالي يوم تقديم العرض","للقيمة الاسمية للورقة المالية"],"a":0},{"q":"قدم شخص عرض تملك عام لشراء مليون سهم، فعرض المساهمون مليوني سهم للبيع، فإن الشراء يتم:","o":["من كل مالك بنسبة عدد الأوراق المطلوب شراؤها إلى مجمل عدد الأوراق المعروضة","من المالكين حسب أسبقية تقديم عروضهم","من كبار المالكين أولاً","بالقرعة بين المالكين الراغبين في البيع"],"a":0}]},{"n":"46","chapter":"الافصاح","notes":[],"source":"أ- على مجلس إدارة المصدر تشكيل اللجنتين التاليتين من بين أعضائه:-\n١-لجنة التدقيق وتتألف من ثلاثة أعضاء على الأقل من غير التنفيذيين.\n٢-لجنة الترشيحات والمكافآت.\nب-تحدد الشؤون المتعلقة باللجنتين المشار إليهما في الفقرة (أ) من هذه المادة ومهام كل منها وصلاحياتها ومدة عملها بموجب تعليمات يصدرها المجلس.","title":"لجنتا التدقيق والترشيحات","memo":"⭐ على مجلس إدارة المصدر تشكيل لجنتين من بين أعضائه: لجنة التدقيق (ثلاثة أعضاء على الأقل من غير التنفيذيين) ولجنة الترشيحات والمكافآت\n⭐ مهام اللجنتين وصلاحياتهما ومدة عملهما تحدد بتعليمات يصدرها المجلس","qs":[{"q":"تتألف لجنة التدقيق التي يشكلها مجلس إدارة المصدر من:","o":["ثلاثة أعضاء على الأقل من غير التنفيذيين","عضوين على الأقل من الأعضاء التنفيذيين","خمسة أعضاء على الأقل من غير التنفيذيين","ثلاثة أعضاء على الأقل من التنفيذيين"],"a":0},{"q":"اللجنتان اللتان يجب على مجلس إدارة المصدر تشكيلهما من بين أعضائه هما:","o":["لجنة التدقيق ولجنة الترشيحات والمكافآت","لجنة التدقيق ولجنة إدارة المخاطر","لجنة الترشيحات والمكافآت ولجنة الحوكمة","لجنة الاستثمار ولجنة التدقيق"],"a":0},{"q":"تحدد مهام لجنتي التدقيق والترشيحات والمكافآت وصلاحياتهما ومدة عملهما بموجب:","o":["تعليمات يصدرها المجلس","النظام الأساسي للمصدر","قرار من الهيئة العامة للمصدر","نظام يصدره مجلس الوزراء"],"a":0}]},{"n":"47","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- يحظر على أي شخص مزاولة اعمال أي من الاشخاص المبينين ادناه الا بعد الحصول على ترخيص من المجلس وفقا لنظام يصدر لهذه الغاية:-\n١-الوسيط المالي .\n٢-الوسيط لحسابه .\n٣-امين الاستثمار .\n٤-مدير الاستثمار .\n٥-المستشار المالي .\n٦-مدير اصدار .\n٧-الحافظ الامين .\n٨-أي اعمال اخرى تتعلق بالاوراق المالية يقررها المجلس .\nب-يحظر على أي شخص طبيعي ان يكون معتمدا لاي من الجهات المذكورة في الفقرة (أ) من هذه المادة الا بعد اعتماده لدى الهيئة .\nج-يحدد النظام الذي سيصدر لهذه الغاية طبيعة الاعمال المشار اليها في الفقرة (أ) من هذه المادة ومتطلبات الترخيص لكل منها وشروط الاعتماد للمعتمد ومستوى التدريب والخبرة والكفاءة لجميع الاشخاص ، ويجوز له ان يشترط على مقدم الطلب التقدم لامتحان او أي طريقة اخرى للتاكد من استيفائه للشروط المطلوبة.","title":"الأعمال الخاضعة للترخيص","memo":"⭐ يحظر مزاولة أعمال: الوسيط المالي، الوسيط لحسابه، أمين الاستثمار، مدير الاستثمار، المستشار المالي، مدير الإصدار، الحافظ الأمين، وأي أعمال يقررها المجلس إلا بترخيص من المجلس وفق نظام\n⭐ يحظر على الشخص الطبيعي أن يكون معتمداً لأي منها إلا بعد اعتماده لدى الهيئة\n⭐ يجوز أن يشترط النظام التقدم لامتحان للتأكد من استيفاء الشروط","qs":[{"q":"أي مما يلي لا يعد من الأعمال التي نص القانون على حظر مزاولتها إلا بعد الحصول على ترخيص من المجلس؟","o":["مدقق الحسابات القانوني","الحافظ الأمين","المستشار المالي","مدير الإصدار"],"a":0},{"q":"الجهة التي تمنح الترخيص لمزاولة أعمال الوسيط المالي هي:","o":["المجلس","السوق المالي","مركز إيداع الأوراق المالية","وزارة الصناعة والتجارة"],"a":0},{"q":"لا يجوز لأي شخص طبيعي أن يكون معتمداً لدى وسيط مالي إلا بعد:","o":["اعتماده لدى الهيئة","قبول عضويته في السوق المالي","تسجيله لدى مركز إيداع الأوراق المالية","حصوله على ترخيص من وزارة العمل"],"a":0}]},{"n":"48","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- يتم تقديم طلب الترخيص لاي من الاعمال المشار اليها في الفقرة (أ) من المادة (٤٧) من هذا القانون، الى الهيئة خطيا وحسب الانموذج الذي تعده لهذه الغاية مرفقا بشهادة تعهد بصحة المعلومات الواردة فيه وموقعا من مقدمه.\nب-للهيئة طلب أي معلومات اضافية من مقدم الطلب بما في ذلك المعلومات التي تتعلق بسيرته الذاتية وسجله وعلاقته بالشركات الاخرى وذلك حسب ما تراه لازما للتأكد من سمعته المهنية .\nج-للهيئة اتخاذ الاجراءات اللازمة للتحقق من صحة المعلومات الواردة في الطلب.\nد-يقدم طلب الاعتماد الى الهيئة وفق نظام يصدر لهذه الغاية.\nهـ-يصدر المجلس قراره بمنح الترخيص او الاعتماد او رفض أي منهما خلال ستين يوما من تاريخ تقديم الطلب اليها مستكملا الشروط والمتطلبات .","title":"طلب الترخيص والاعتماد","memo":"⭐ يقدم طلب الترخيص للهيئة خطياً حسب الأنموذج المعتمد مرفقاً بشهادة تعهد بصحة المعلومات وموقعاً من مقدمه\n⭐ للهيئة طلب معلومات إضافية للتأكد من السمعة المهنية والتحقق من صحة المعلومات\n⭐ يصدر المجلس قراره بمنح الترخيص أو الاعتماد أو رفضه خلال (٦٠) يوماً من تقديم الطلب مستكملاً","qs":[{"q":"يصدر المجلس قراره بمنح الترخيص أو الاعتماد أو رفض أي منهما خلال:","o":["ستين يوماً من تاريخ تقديم الطلب مستكملاً الشروط والمتطلبات","ثلاثين يوماً من تاريخ تقديم الطلب مستكملاً الشروط والمتطلبات","تسعين يوماً من تاريخ تقديم الطلب مستكملاً الشروط والمتطلبات","خمسة عشر يوماً من تاريخ تقديم الطلب مستكملاً الشروط والمتطلبات"],"a":0},{"q":"يقدم طلب الترخيص لأي من الأعمال المحددة في المادة (٤٧) إلى الهيئة خطياً مرفقاً به:","o":["شهادة تعهد بصحة المعلومات الواردة فيه موقعة من مقدمه","كفالة بنكية غير مشروطة","موافقة السوق المالي على الطلب","شهادة عضوية في مركز إيداع الأوراق المالية"],"a":0},{"q":"الغاية من حق الهيئة في طلب معلومات إضافية عن السيرة الذاتية لمقدم طلب الترخيص وسجله وعلاقته بالشركات الأخرى هي:","o":["التأكد من سمعته المهنية","تحديد مقدار رسوم الترخيص","تحديد مقدار الكفالة البنكية المطلوبة","تحديد عدد المعتمدين لديه"],"a":0}]},{"n":"49","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"للمجلس الموافقة على طلب تعديل الترخيص نتيجة أي تغيير في المعلومات المتعلقة بموظفي الشركة او أي تغيير في المالكين او المديرين او المسؤولين الاداريين في أي وسيط مالي او وسيط لحسابه او مدير الاستثمار او شركة الخدمات المالية او امين الاستثمار او مدير الاصدار ، على ان يكون الطلب خطيا ومتضمنا المعلومات والوقائع المتعلقة بذلك التغيير.","title":"تعديل الترخيص","memo":"⭐ للمجلس الموافقة على طلب تعديل الترخيص نتيجة تغيير في معلومات الموظفين أو المالكين أو المديرين أو المسؤولين الإداريين لدى المرخص له\n⭐ يجب أن يكون طلب التعديل خطياً ومتضمناً المعلومات والوقائع المتعلقة بالتغيير","qs":[{"q":"الجهة المختصة بالموافقة على طلب تعديل الترخيص نتيجة تغيير في مالكي أو مديري الوسيط المالي هي:","o":["المجلس","السوق المالي","المدير التنفيذي للسوق المالي","مركز إيداع الأوراق المالية"],"a":0},{"q":"يشترط في طلب تعديل الترخيص نتيجة تغيير المالكين أو المديرين أن يكون:","o":["خطياً ومتضمناً المعلومات والوقائع المتعلقة بالتغيير","مقدماً خلال ستين يوماً من حدوث التغيير","مصدقاً من مدقق حسابات قانوني","مرفقاً بكفالة بنكية جديدة"],"a":0}]},{"n":"50","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"للمجلس ان يطلب من المرخص له تقديم كفالات بنكية غير مشروطة او أي ضمانات اخرى يقبلها لضمان الالتزامات المترتبة عليه لعملائه المتعاملين بالاوراق المالية وتقيده باحكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه، ويجوز للمجلس تسييل الكفالات والتصرف بالضمانات إذا خالف المرخص له أحكام هذا القانون والانظمة والتعليمات الصادرة بمقتضاه.","title":"الكفالات والضمانات على المرخص له","memo":"⭐ للمجلس أن يطلب من المرخص له كفالات بنكية غير مشروطة أو أي ضمانات أخرى يقبلها لضمان التزاماته لعملائه وتقيده بالقانون\n⭐ للمجلس تسييل الكفالات والتصرف بالضمانات إذا خالف المرخص له أحكام القانون","qs":[{"q":"يجوز للمجلس أن يطلب من المرخص له تقديم:","o":["كفالات بنكية غير مشروطة أو أي ضمانات أخرى يقبلها","كفالات بنكية مشروطة فقط","رهن عقاري حصراً","وديعة نقدية لدى السوق المالي حصراً"],"a":0},{"q":"خالف وسيط مالي أحكام القانون وكان قد قدم كفالة بنكية للمجلس، فإن للمجلس:","o":["تسييل الكفالة والتصرف بالضمانات","إعادة الكفالة للوسيط وإلغاء ترخيصه فقط","تحويل الكفالة إلى السوق المالي","إيداع الكفالة لدى المحكمة المختصة"],"a":0}]},{"n":"51","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"لا يجوز لاي شخص ان يقوم وفي الوقت نفسه بعمل مدير استثمار وامين استثمار للحساب ذاته او للعميل ذاته .","title":"حظر الجمع بين مدير وأمين الاستثمار","memo":"⭐ لا يجوز لأي شخص أن يقوم في الوقت نفسه بعمل مدير استثمار وأمين استثمار للحساب ذاته أو للعميل ذاته","qs":[{"q":"لا يجوز لأي شخص أن يقوم في الوقت نفسه وللعميل ذاته بعمل:","o":["مدير استثمار وأمين استثمار","وسيط مالي ومستشار مالي","مدير إصدار ووسيط مالي","وسيط لحسابه ومدير إصدار"],"a":0}]},{"n":"52","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"تسجل اسماء وعناوين المرخص لهم والمعتمدين وجميع الاحكام التي تتعلق بهم في سجل المرخصين والمعتمدين ويحفظ لدى الهيئة ويكون متاحا لاطلاع الجمهور .","title":"سجل المرخصين والمعتمدين","memo":"⭐ تسجل أسماء وعناوين المرخص لهم والمعتمدين وجميع الأحكام المتعلقة بهم في سجل يحفظ لدى الهيئة ويكون متاحاً لاطلاع الجمهور","qs":[{"q":"سجل المرخصين والمعتمدين الذي تدون فيه أسماؤهم وعناوينهم والأحكام المتعلقة بهم:","o":["يحفظ لدى الهيئة ويكون متاحاً لاطلاع الجمهور","يحفظ لدى السوق المالي ويكون سرياً","يحفظ لدى المركز ولا يطلع عليه إلا الأعضاء","يحفظ لدى الهيئة ولا يجوز الاطلاع عليه إلا بموافقة المحكمة"],"a":0}]},{"n":"53","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- يصدر المجلس التعليمات والقرارات المتعلقة بالسجلات التي يجب على المرخص له تنظيمها والاحتفاظ بها والتزامه بتقديم نسخ من أي سجلات تطلبها الهيئة .\nب-يحق لموظفي الهيئة المفوضين من الرئيس، في أي وقت، القيام بالتفتيش والاطلاع على السجلات المشار اليها في الفقرة (أ) من هذه المادة وذلك بصورة دورية او عند الضرورة حماية للمستثمرين ولمتطلبات المصلحة العامة .\nج-على المرخص له ان يحتفظ بالسجلات المحاسبية وفقا لمعايير المحاسبة المعتمدة .","title":"سجلات المرخص له والتفتيش عليها","memo":"⭐ يصدر المجلس التعليمات والقرارات المتعلقة بالسجلات التي على المرخص له تنظيمها والاحتفاظ بها\n⭐ لموظفي الهيئة المفوضين من الرئيس التفتيش على السجلات في أي وقت بصورة دورية أو عند الضرورة\n⭐ على المرخص له الاحتفاظ بالسجلات المحاسبية وفق معايير المحاسبة المعتمدة","qs":[{"q":"يحق لموظفي الهيئة القيام بالتفتيش والاطلاع على سجلات المرخص له في أي وقت إذا كانوا مفوضين من:","o":["الرئيس","المجلس القضائي","وزير المالية","المدير التنفيذي للسوق المالي"],"a":0},{"q":"يلتزم المرخص له بالاحتفاظ بالسجلات المحاسبية وفقاً:","o":["لمعايير المحاسبة المعتمدة","للأنظمة الداخلية للسوق المالي","لتعليمات مركز إيداع الأوراق المالية","للأسس التي يحددها العميل في الاتفاقية"],"a":0}]},{"n":"54","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"على الرغم مما ورد في أي تشريع اخر :-\nأ-على المرخص له الفصل بين امواله والاوراق المالية الخاصة به ، واموال عملائه واوراقهم المالية التي تكون وديعة لديه ، وذلك وفق الشروط التي يحددها المجلس والتي يتوجب تضمينها للاتفاقيات المعقودة مع هؤلاء العملاء.\nب-باستثناء الحالات التي يحددها المجلس بموجب التعليمات التي يصدرها ، لا يجوز بأي حال ان يتم توزيع الاموال والموجودات التي بحوزة المرخص له والعائدة لعملائه على دائنيه في حال تصفيته او في حال عدم وفائه بالالتزامات المترتبة عليه .\nج-يتم تحديد اسس تسمية الحسابات ومتطلبات الفصل بينها ومتطلبات الحفظ الامين لاموال العملاء وموجوداتهم بمقتضى تعليمات او قرارات يصدرها المجلس .","title":"فصل أموال العملاء عن أموال المرخص له","memo":"⭐ على الرغم من أي تشريع آخر: على المرخص له الفصل بين أمواله وأوراقه المالية وأموال عملائه وأوراقهم المودعة لديه وفق شروط يحددها المجلس\n⭐ لا يجوز توزيع أموال العملاء وموجوداتهم على دائني المرخص له عند تصفيته أو عدم وفائه بالتزاماته باستثناء الحالات التي يحددها المجلس بتعليمات","qs":[{"q":"تمت تصفية شركة وساطة مالية وطالب دائنوها بتوزيع أموال العملاء الموجودة بحوزتها عليهم، فإن الأصل في هذه الحالة:","o":["عدم جواز توزيعها على الدائنين باستثناء الحالات التي يحددها المجلس بتعليمات","جواز توزيعها على الدائنين بنسبة ديونهم","جواز توزيعها على الدائنين الممتازين فقط","جواز توزيعها بقرار من المصفي"],"a":0},{"q":"الجهة التي تحدد الشروط التي يتم بموجبها فصل المرخص له بين أمواله وأموال عملائه والتي يتوجب تضمينها في اتفاقياته معهم هي:","o":["المجلس","السوق المالي","العميل","مدقق الحسابات القانوني للمرخص له"],"a":0},{"q":"تحدد أسس تسمية الحسابات ومتطلبات الفصل بينها ومتطلبات الحفظ الأمين لأموال العملاء بمقتضى:","o":["تعليمات أو قرارات يصدرها المجلس","نظام يصدره مجلس الوزراء","الأنظمة الداخلية لمركز الإيداع","الاتفاقية الخطية بين العميل والمرخص له"],"a":0}]},{"n":"55","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- لا يجوز للوسيط المالي القيام بتمويل شراء الأوراق المالية لعملائه إلا بعد الحصول على ترخيص باعمال التمويل على الهامش وفقاً لأحكام هذا القانون والانظمة والتعليمات والقرارات الصادرة لهذه الغاية.\nب-يقصد بالتمويل على الهامش قيام الوسيط المالي بتمويل نسبة من قيمة الأوراق المالية التي يقوم بشرائها لعميله وفق التعليمات والقرارات الصادرة عن الهيئة وبموجب اتفاقية تنظم العلاقة بينهما.\nج-تعد ملكية الأوراق المالية الممولة على الهامش ملكية تخول المرخص له بالتمويل حق التقدم على سائر دائني عميله باستيفاء ما له من حق على تلك الأوراق المالية حتى وإن كان لهم حق امتياز خاص أو عام.\nد-للمرخص له بالتمويل على الهامش تحديد حقوقه المتعلقة بالأوراق المالية الخاصة بأي من عملائه دون الرجوع إليه في أي من الحالات التالية:\n١-وفاة العميل.\n٢-صدور قرار بتصفية العميل، أو شهر إفلاسه أو الحجر عليه.\n٣-صدور أمر حجز عن سلطة مختصة على الأوراق المالية العائدة لعميله.\nهـ-على المرخص له بالتمويل على الهامش عند حدوث أي من الحالات المشار إليها في الفقرة (د) من هذه المادة إعلام الهيئة والمركز ببيان خطي يتضمن اسم عميله، ووصف الحالة التي استدعت تحديد حقوقه وعدد الأوراق المالية التي يملكها عميله ونوعها ومقدار الرصيد النقدي المتعلق بالأوراق المالية الممولة خلال مدة لا تتجاوز يوم العمل الثاني لعلمه بوقوع الحالة، وله بعد ذلك أن يبيع من الأوراق المالية التي مولها بالقدر الذي يكفي للوفاء بحقوقه المتعلقة بها، دون الحاجة إلى الحصول على تفويض بذلك.\nو-١-على الرغم مما ورد في الفقرة (و) من المادة (٧٩) من هذا القانون، لا تثبت إشارة الحجز على الأوراق المالية الممولة على الهامش قبل تسوية الحق المتعلق بها وفقاً للإجراءات المحددة في هذا القانون والتعليمات والقرارات الصادرة بمقتضاه.\n٢-لا تحول تصفية مالك الأوراق المالية أو شهر إفلاسه أو الحجر عليه أو وفاته أو صدور قرار بالحجز على الأوراق المالية العائدة له دون حق المرخص له بالتمويل على الهامش من مباشرة بيع الأوراق المالية لعميله بما يكفي للوفاء بحقوقه المتعلقة بها، ويكون المرخص له مسؤولاً عن ضمان الأضرار التي تلحق بعميله أو الغير في حال أساء استخدام الحق الممنوح له بموجب أحكام هذه المادة.","title":"التمويل على الهامش","memo":"⭐ لا يجوز للوسيط المالي تمويل شراء الأوراق المالية لعملائه إلا بعد الحصول على ترخيص بأعمال التمويل على الهامش\n⭐ للممول حق التقدم على سائر دائني العميل ولو كان لهم حق امتياز خاص أو عام\n⭐ حالات تحديد حقوقه دون الرجوع للعميل: الوفاة، التصفية أو الإفلاس أو الحجر، أمر حجز على الأوراق؛ ويعلم الهيئة والمركز خطياً خلال مدة لا تتجاوز يوم العمل الثاني لعلمه ثم يبيع بالقدر الكافي دون تفويض\n⭐ لا تثبت إشارة الحجز على الأوراق الممولة على الهامش قبل تسوية الحق المتعلق بها","qs":[{"q":"يقصد بالتمويل على الهامش:","o":["قيام الوسيط المالي بتمويل نسبة من قيمة الأوراق المالية التي يشتريها لعميله بموجب اتفاقية","قيام البنك بمنح العميل قرضاً بضمان راتبه لشراء الأوراق المالية","قيام المصدر بتقسيط ثمن الأوراق المالية للمكتتبين","قيام السوق المالي بتمويل عمليات التداول بين الوسطاء"],"a":0},{"q":"عند وفاة عميل ممول على الهامش، يجب على المرخص له بالتمويل على الهامش إعلام الهيئة والمركز ببيان خطي خلال مدة لا تتجاوز:","o":["يوم العمل الثاني لعلمه بوقوع الحالة","يوم العمل الخامس لعلمه بوقوع الحالة","خمسة عشر يوماً من علمه بوقوع الحالة","ثلاثين يوماً من علمه بوقوع الحالة"],"a":0},{"q":"أي مما يلي لا يعد من الحالات التي يجوز فيها للمرخص له بالتمويل على الهامش تحديد حقوقه المتعلقة بأوراق عميله دون الرجوع إليه؟","o":["سفر العميل خارج المملكة","وفاة العميل","شهر إفلاس العميل أو الحجر عليه","صدور أمر حجز عن سلطة مختصة على الأوراق المالية العائدة للعميل"],"a":0},{"q":"تتمتع ملكية الأوراق المالية الممولة على الهامش بأنها تخول المرخص له بالتمويل:","o":["حق التقدم على سائر دائني عميله حتى وإن كان لهم حق امتياز خاص أو عام","حق التقدم على الدائنين العاديين فقط دون أصحاب الامتياز","حقاً مساوياً لسائر دائني العميل","حق التقدم على الدائنين بعد استيفاء حقوق الخزينة"],"a":0}]},{"n":"56","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"يعتبر مخالفة لاحكام هذا القانون قيام المرخص له او المعتمد بأي مما يلي :-\nأ-اساءة التصرف باموال العملاء او المساهمين بما في ذلك اساءة توظيفها او استخدامها .\nب-ممارسة الخداع والتضليل والاعمال المحظورة .\nج-التأثير سلبا على المنافسة وذلك بالتلاعب بنسب العمولات او ببدل الخدمات التي يتقاضاها أي منهما من العملاء او الحد من الخدمات المقدمة سواء كان ذلك بشكل منفرد او بالتواطؤ مع الغير.\nد-التأثير سلبا او محاولة التاثير سلبا وباي شكل من الاشكال على سوق راس المال سواء كان ذلك بشكل منفرد او بالتواطؤ مع الغير.","title":"مخالفات المرخص له والمعتمد","memo":"⭐ يعد مخالفة: إساءة التصرف بأموال العملاء أو المساهمين، الخداع والتضليل والأعمال المحظورة\n⭐ التأثير سلباً على المنافسة بالتلاعب بنسب العمولات أو بدل الخدمات أو الحد من الخدمات منفرداً أو بالتواطؤ\n⭐ التأثير سلباً أو محاولة التأثير سلباً على سوق رأس المال منفرداً أو بالتواطؤ","qs":[{"q":"قام وسيط مالي بالتواطؤ مع وسطاء آخرين على تخفيض نسب العمولات بهدف إقصاء منافسيه، فإن هذا التصرف:","o":["يعد مخالفة لأحكام القانون لتأثيره سلباً على المنافسة","جائز لأنه يحقق مصلحة العملاء","جائز إذا وافق عليه السوق المالي","لا يعد مخالفة لأنه لم يتم بشكل منفرد"],"a":0},{"q":"وفقاً للقانون، فإن محاولة المرخص له التأثير سلباً على سوق رأس المال:","o":["تعد مخالفة لأحكام القانون سواء تمت بشكل منفرد أو بالتواطؤ مع الغير","لا تعد مخالفة ما لم يتحقق الأثر فعلاً","تعد مخالفة فقط إذا تمت بالتواطؤ مع الغير","تعد مخالفة فقط إذا ارتكبها المعتمد دون المرخص له"],"a":0}]},{"n":"57","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"على المرخص له او المعتمد وعلى الاشخاص الذين يعملون لدى أي منهما اثناء ممارستهم لانشطتهم ، التقيد بقواعد السلوك المهني وفقا للتعليمات التي يصدرها المجلس بما في ذلك التصرف بامانة واخلاص لصالح عملائهم وبشكل يؤدي الى تعظيم مصالحهم وتحقيق اهدافهم الاستثمارية دون تمييز بينهم او تحميلهم عمولات وبدل خدمات مبالغا فيها او ضمان ارباح معينة لهم او وعدهم بها او ممارسة أي من اساليب الغش والخداع معهم .","title":"قواعد السلوك المهني","memo":"⭐ على المرخص له والمعتمد والعاملين لديهما التقيد بقواعد السلوك المهني وفق تعليمات المجلس\n⭐ التصرف بأمانة وإخلاص لصالح العملاء دون تمييز، ودون تحميلهم عمولات مبالغ فيها أو ضمان أرباح معينة لهم أو وعدهم بها أو ممارسة الغش والخداع","qs":[{"q":"وعد معتمد لدى وسيط مالي عميله بتحقيق أرباح معينة مضمونة على استثماره، فإن هذا التصرف:","o":["يخالف قواعد السلوك المهني","جائز إذا كان الوعد مكتوباً","جائز إذا كان العميل مستثمراً محترفاً","جائز بموافقة الوسيط المالي الذي يعمل لديه"],"a":0},{"q":"أي مما يلي لا يعد من مقتضيات قواعد السلوك المهني الواردة في القانون؟","o":["تقديم مصلحة المرخص له على مصلحة عملائه","التصرف بأمانة وإخلاص لصالح العملاء","عدم التمييز بين العملاء","عدم تحميل العملاء عمولات وبدل خدمات مبالغاً فيها"],"a":0}]},{"n":"58","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"للمجلس ان يرفض طلب الترخيص المقدم من شخص او ان يلغي أي ترخيص ممنوح لشخص اذا تبين له ان مجلس ادارة ذلك الشخص او هيئة مديريه او أي من مديريه او اداريه المسؤولين قد خالف متطلبات الترخيص الواردة في هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه .","title":"رفض الترخيص أو إلغاؤه لمخالفة الإدارة","memo":"⭐ للمجلس رفض طلب الترخيص أو إلغاء الترخيص إذا تبين أن مجلس إدارة الشخص أو هيئة مديريه أو أي من مديريه أو إدارييه المسؤولين خالف متطلبات الترخيص","qs":[{"q":"تبين للمجلس أن أحد المديرين المسؤولين في شركة وساطة مرخصة قد خالف متطلبات الترخيص، فللمجلس:","o":["إلغاء الترخيص الممنوح للشركة","إحالة الشركة إلى التصفية الإجبارية مباشرة","تعليق نشاط السوق المالي","تسييل أموال عملاء الشركة"],"a":0},{"q":"الجهة التي يحق لها رفض طلب الترخيص إذا تبين أن هيئة مديري مقدم الطلب خالفت متطلبات الترخيص هي:","o":["المجلس","السوق المالي","مركز إيداع الأوراق المالية","المحكمة الإدارية"],"a":0}]},{"n":"59","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"يشترط ان تتوافر في المرخص له او المعتمد ، وبصورة مستمرة، جميع متطلبات الترخيص وشروط الاعتماد المقررة في القانون والمحددة بموجب التعليمات التي يصدرها المجلس وذلك تحت طائلة الغاء الترخيص او الاعتماد .","title":"استمرار توافر متطلبات الترخيص","memo":"⭐ يشترط توافر جميع متطلبات الترخيص وشروط الاعتماد في المرخص له أو المعتمد بصورة مستمرة تحت طائلة إلغاء الترخيص أو الاعتماد","qs":[{"q":"الأثر المترتب على عدم استمرار توافر متطلبات الترخيص في المرخص له هو:","o":["إلغاء الترخيص","فرض غرامة يحددها السوق المالي","تحويل الترخيص إلى اعتماد","إيقاف العمل بالترخيص لمدة أسبوع فقط"],"a":0},{"q":"يشترط أن تتوافر متطلبات الترخيص وشروط الاعتماد في المرخص له أو المعتمد:","o":["بصورة مستمرة","عند تقديم الطلب فقط","عند صدور قرار الترخيص فقط","عند تجديد الترخيص فقط"],"a":0}]},{"n":"60","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- للمجلس بعد اخطار الشخص المعني ومنحه فرصة لسماع اقواله رفض او تعليق او الغاء الترخيص او الاعتماد ، حسب مقتضى الحال ، في أي من الحالات التالية:-\n١-مخالفة أي من احكام هذا القانون او الانظمة او التعليمات او القرارات الصادرة بمقتضاه .\n٢-تضمين طلب الترخيص او الاعتماد معلومات غير صحيحة.\n٣-القيام باي عمل محظور .\n٤-ثبوت عدم جدارته في مزاولة اعمال المرخص له او المعتمد .\nب-اذا تمت مخالفة معتمد فيتعين على المجلس عندئذ وإضافة الى اخطاره اشعار الشخص الذي يعمل لديه بذلك.\nج-يحق للمجلس ، مع بيان الاسباب ، ان يقرر تعليق الرخصة او الاعتماد الى حين سماع الاقوال .\nد-يعتبر قرار تعليق الترخيص او الاعتماد سريا لا يجوز نشره ، الى ان يتم اتخاذ قرار نهائي بهذا الشأن ، الا اذا تبين بأن المرخص له قد خالف قرار التعليق بعد اشعاره به، وذلك مع عدم الاخلال بالتزام الاشخاص بالقرار الذي تم اخطارهم به.\nهـ-يدون القرار النهائي برفض الترخيص او الاعتماد او الغائه او تعليقه ، والنتائج التي يتم التوصل اليها بهذا الشأن، في سجل المرخصين والمعتمدين ، ويعتبر حكما تعليق او الغاء ترخيص أي مرخص له تعليقا او الغاء لاعتماد جميع المعتمدين لديه .","title":"رفض الترخيص أو تعليقه أو إلغاؤه","memo":"⭐ للمجلس بعد إخطار الشخص ومنحه فرصة لسماع أقواله رفض أو تعليق أو إلغاء الترخيص أو الاعتماد: مخالفة القانون، معلومات غير صحيحة في الطلب، عمل محظور، ثبوت عدم الجدارة\n⭐ للمجلس مع بيان الأسباب تعليق الرخصة أو الاعتماد إلى حين سماع الأقوال، وقرار التعليق سري لا يجوز نشره حتى القرار النهائي\n⭐ تعليق أو إلغاء ترخيص المرخص له يعتبر حكماً تعليقاً أو إلغاء لاعتماد جميع المعتمدين لديه","qs":[{"q":"قبل أن يقرر المجلس إلغاء ترخيص شخص لثبوت عدم جدارته، يتوجب عليه:","o":["إخطار الشخص المعني ومنحه فرصة لسماع أقواله","الحصول على قرار من المحكمة الإدارية","الحصول على موافقة رئيس الوزراء","إعلام السوق المالي والمركز خلال يومي عمل"],"a":0},{"q":"الأصل في قرار تعليق الترخيص أو الاعتماد قبل اتخاذ القرار النهائي أنه:","o":["سري لا يجوز نشره","يجب نشره في صحيفتين يوميتين","يجب نشره على الموقع الإلكتروني للسوق المالي","علني يدون فوراً في سجل المرخصين"],"a":0},{"q":"قرر المجلس إلغاء ترخيص شركة وساطة مالية لديها خمسة معتمدين، فإن هذا الإلغاء:","o":["يعتبر حكماً إلغاء لاعتماد جميع المعتمدين لديها","لا يؤثر على اعتماد المعتمدين لديها","يوجب على المعتمدين تقديم طلبات اعتماد جديدة خلال ستين يوماً","يعتبر إلغاء لاعتماد المدير التنفيذي فقط"],"a":0},{"q":"إذا تمت مخالفة من قبل معتمد، فيتعين على المجلس إضافة إلى إخطاره:","o":["إشعار الشخص الذي يعمل لديه بذلك","إشعار السوق المالي والمركز","نشر المخالفة في صحيفة يومية","إشعار عملاء المعتمد جميعهم"],"a":0}]},{"n":"61","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"يتعين على المرخص له الذي يقرر التوقف عن مزاولة اعماله المرخصة اعلام الهيئة بذلك ، ويتم في هذه الحالة الغاء الترخيص بعد استكمال المرخص له لجميع المتطلبات التي تحددها الهيئة لتسوية جميع المطالبات والامور ذات العلاقة بالعمل المنوي التوقف عن مزاولته .","title":"التوقف الاختياري عن مزاولة الأعمال","memo":"⭐ على المرخص له الذي يقرر التوقف عن أعماله إعلام الهيئة، ويلغى الترخيص بعد استكماله جميع المتطلبات التي تحددها الهيئة لتسوية المطالبات","qs":[{"q":"قرر وسيط مالي التوقف عن مزاولة أعماله المرخصة، فإن ترخيصه يلغى:","o":["بعد استكماله جميع المتطلبات التي تحددها الهيئة لتسوية جميع المطالبات ذات العلاقة","فور إعلام الهيئة بقراره","بعد مرور ستين يوماً من إعلام الهيئة","بعد موافقة الهيئة العامة للسوق المالي"],"a":0},{"q":"الجهة التي يتعين على المرخص له إعلامها بقراره التوقف عن مزاولة أعماله المرخصة هي:","o":["الهيئة","وزارة الصناعة والتجارة","المحكمة المختصة","مراقب عام الشركات"],"a":0}]},{"n":"62","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- تكون التصفية الاختيارية او الاجبارية لاي مرخص له باطلاع الهيئة ومتابعتها، ولا يسري هذا النص على البنوك فيما يتعلق بموجوداتها المصرفية.\nب-للمجلس اتخاذ الاجراءات القانونية اللازمة لشهر افلاس المرخص له اذا كان شخصا طبيعيا او احالة شركة الخدمات المالية للتصفية الاجبارية .\nج-لا تخضع الأموال والأوراق المالية العائدة لعملاء شركة الخدمات المالية لاجراءات الرهن والحجز والتصفية والافلاس التي تخضع لها شركات الخدمات المالية.","title":"تصفية المرخص له","memo":"⭐ التصفية الاختيارية أو الإجبارية لأي مرخص له تكون باطلاع الهيئة ومتابعتها، ولا يسري ذلك على البنوك فيما يتعلق بموجوداتها المصرفية\n⭐ للمجلس اتخاذ إجراءات شهر إفلاس المرخص له الشخص الطبيعي أو إحالة شركة الخدمات المالية للتصفية الإجبارية\n⭐ أموال وأوراق عملاء شركة الخدمات المالية لا تخضع للرهن والحجز والتصفية والإفلاس التي تخضع لها الشركة","qs":[{"q":"لا يسري حكم كون تصفية المرخص له باطلاع الهيئة ومتابعتها على:","o":["البنوك فيما يتعلق بموجوداتها المصرفية","شركات الخدمات المالية","الوسطاء الماليين الأشخاص الطبيعيين","مديري الاستثمار"],"a":0},{"q":"تعثرت شركة خدمات مالية وأحيلت للتصفية، فإن الأموال والأوراق المالية العائدة لعملائها:","o":["لا تخضع لإجراءات الرهن والحجز والتصفية والإفلاس التي تخضع لها الشركة","تدخل في أموال التصفية وتوزع على الدائنين","تخضع للحجز لصالح الهيئة","توزع مناصفة بين العملاء والدائنين"],"a":0},{"q":"للمجلس إذا كان المرخص له شخصاً طبيعياً أن يتخذ الإجراءات القانونية اللازمة:","o":["لشهر إفلاسه","لإحالته للتصفية الاختيارية","لتعيين مدير تنفيذي بدلاً منه","لنقل ترخيصه إلى شخص آخر"],"a":0}]},{"n":"63","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- تنظم العلاقة بين العميل والمرخص له بموجب اتفاقية خطية تكون متوافقة مع احكام هذا القانون والانظمة والتعليمات الصادرة بمقتضاه .\nب-على كل مرخص له او معتمد عند تعاقده مع عملائه او تعامله بالاوراق المالية لصالحهم، المصادقة على صحة تواقيعهم وذلك بعد التثبت من هويتهم واهليتهم للتعاقد على ان يتحمل المرخص له او المعتمد مسؤولية صحة تلك التواقيع .\nج-يعتبر مرتكبا لجرم التزوير والاحتيال كل مرخص له او معتمد يبيع او يتصرف باوراق مالية دون تفويض من مالكها او دون وجود اتفاقية خطية تخوله ذلك وفقاً لأحكام التعليمات التي يصدرها المجلس.","title":"العلاقة بين العميل والمرخص له","memo":"⭐ تنظم العلاقة بين العميل والمرخص له بموجب اتفاقية خطية متوافقة مع القانون\n⭐ على المرخص له أو المعتمد المصادقة على صحة تواقيع العملاء بعد التثبت من هويتهم وأهليتهم ويتحمل مسؤولية صحتها\n⭐ يعتبر مرتكباً لجرم التزوير والاحتيال من يبيع أو يتصرف بأوراق مالية دون تفويض من مالكها أو دون اتفاقية خطية","qs":[{"q":"تنظم العلاقة بين العميل والمرخص له بموجب:","o":["اتفاقية خطية متوافقة مع أحكام القانون والأنظمة والتعليمات","اتفاق شفهي يثبت بشهادة الشهود","تعليمات السوق المالي دون حاجة لاتفاقية","وكالة عدلية فقط"],"a":0},{"q":"قام وسيط مالي ببيع أسهم أحد العملاء دون تفويض منه ودون وجود اتفاقية خطية تخوله ذلك، فإنه يعتبر مرتكباً لجرم:","o":["التزوير والاحتيال","إساءة الائتمان فقط","التداول بناءً على معلومات داخلية","التلاعب بالأسعار"],"a":0},{"q":"يتحمل مسؤولية صحة تواقيع العملاء عند التعاقد معهم أو التعامل بالأوراق المالية لصالحهم:","o":["المرخص له أو المعتمد","السوق المالي","مركز إيداع الأوراق المالية","العميل نفسه"],"a":0}]},{"n":"64","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ-١- يتم ترخيص سوق تداول الاوراق المالية سوقا ماليا وفقا لاحكام هذا القانون والتعليمات الصادرة عن المجلس بهذا الخصوص .\n٢-يقدم طلب ترخيص سوق تداول الاوراق المالية الى الهيئة مرفقا به انظمته الداخلية والتعليمات التي تنظم عمله واي معلومات او وثائق اخرى يعتبرها المجلس ضرورية او مناسبة لحماية المستثمرين او لتحقيق المصلحة العامة.\nب-لا يجوز ان يرخص سوق تداول الاوراق المالية سوقا ماليا الا اذا تبين للمجلس ان هذا السوق المالي منظم وقادر على الزام اعضائه وذوي العلاقة بهم بالتقيد باحكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه وبانظمته الداخلية وتعليماته.\nج-يشترط في الانظمة الداخلية لسوق تداول الاوراق المالية وتعليماته ان تتضمن ما يلي :-\n١-تحميل اعضائه والمصدرين فيه واي اشخاص اخرين يستخدمون مرافقه ، بشكل عادل ومعقول ، لاي بدل او اجر يتقاضاه السوق المالي .\n٢-ضمان العدالة والكفاءة والشفافية ومنع الخداع والغش والاعمال المحظورة ، وتعزيز التنسيق والتعاون مع الجهات العاملة في سوق راس المال وحماية المستثمرين .\n٣-وضع اسس عادلة عند التمييز بين العملاء او المصدرين او الوسطاء الماليين او الوسطاء لحسابهم .\n٤-فرض عقوبات تأديبية على اعضائه والاشخاص ذوي العلاقة بهم عن مخالفتهم لاحكام أنظمة السوق المالي الداخلية وتعليماته .\n٥-تطبيق اجراءات تداول عادلة ومنصفة في السوق المالي .\n٦-عدم فرض أي قيود غير ضرورية او غير مناسبة على المنافسة.\n٧-وضع معايير للتدريب والخبرة والكفاءة الادارية لاعضائه وموظفيهم واجراءات العقوبات التأديبية لمن لا يستوفي منهم تلك المعايير.\nد-لا يجوز ان يكون المدير التنفيذي للسوق المالي او نائبه عضوا في مجلس ادارة او هيئة مديري مرخص له ، او مسؤولا اداريا او مديرا او موظفا او ممثلا لمرخص له وذلك خلال مدة تولي أي منهما لهذا المركز .\nهـ-يعين المدير التنفيذي للسوق المالي بقرار من مجلس إدارة السوق المالي، وبموافقة المجلس، ويحظر عليه ان يقوم بأي عمل آخر او ان يكون شريكا او مساهما في أي مرخص له او ان يكون ممثلا له.","title":"ترخيص سوق تداول الأوراق المالية","memo":"⭐ يرخص سوق التداول سوقاً مالياً إذا تبين للمجلس أنه منظم وقادر على إلزام أعضائه بأحكام القانون؛ ويقدم الطلب للهيئة مرفقاً بأنظمته الداخلية وتعليماته\n⭐ لا يجوز للمدير التنفيذي للسوق المالي أو نائبه أن يكون عضواً في مجلس إدارة أو هيئة مديري مرخص له أو موظفاً أو ممثلاً له خلال توليه المركز\n⭐ يعين المدير التنفيذي للسوق بقرار من مجلس إدارة السوق وبموافقة المجلس، ويحظر عليه أي عمل آخر أو أن يكون شريكاً أو مساهماً في مرخص له","qs":[{"q":"يعين المدير التنفيذي للسوق المالي بقرار من:","o":["مجلس إدارة السوق المالي وبموافقة المجلس","المجلس وبتنسيب من رئيس الهيئة","مجلس الوزراء بتنسيب من الوزير","الهيئة العامة للسوق المالي"],"a":0},{"q":"يحظر على المدير التنفيذي للسوق المالي أو نائبه أن يكون عضواً في مجلس إدارة أو هيئة مديري مرخص له:","o":["خلال مدة تولي أي منهما لهذا المركز","خلال سنة من تركه المركز فقط","خلال سنتين بعد انتهاء خدمته فقط","خلال السنة الأولى من تعيينه فقط"],"a":0},{"q":"أي مما يلي لا يعد من الأمور التي يشترط أن تتضمنها الأنظمة الداخلية لسوق تداول الأوراق المالية وتعليماته؟","o":["تحديد حد أدنى لأرباح الشركات المدرجة","فرض عقوبات تأديبية على أعضائه عن مخالفتهم لأنظمته","تطبيق إجراءات تداول عادلة ومنصفة","عدم فرض أي قيود غير ضرورية أو غير مناسبة على المنافسة"],"a":0}]},{"n":"65","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- للسوق المالي وفقاً للتعليمات التي يصدرها ان يقوم بالتدقيق والتحقيق والتفتيش على اعضائه وعلى مصدري الاوراق المالية المدرجة لديه للتاكد من عدم مخالفتهم لانظمته الداخلية والتعليمات الصادرة عنه وبما يكفل حماية حقوق جميع الاطراف.\nب-تعتبر المعلومات التي تطلع عليها ادارة السوق المالي وموظفوه ومستشاروه سرية ، ولا يجوز للسوق المالي الافصاح عنها الا بعد موافقة المجلس على ذلك .\nج-للسوق المالي ولاسباب مبررة ووفقاً للحالات المنصوص عليها في انظمته الداخلية والتعليمات الصادرة عنه ان يعلق تداول اوراق مالية معينة او يوقف اعمال أي من اعضائه للمدة التي يراها مناسبة شريطة اعلام الهيئة فوراً بذلك.\nد-اذا تبين للسوق المالي ان عضوا يعاني من صعوبات مالية او ادارية وان استمراره بالعمل يهدد مصالح المستثمرين والدائنين والاعضاء الآخرين او السوق المالي نفسه فعليه اعلام الهيئة فوراً بذلك وللهيئة وبصورة مستعجلة تعليق او منع الخدمات التي يقدمها السوق المالي لذلك العضو او الحد منها.","title":"رقابة السوق المالي على أعضائه","memo":"⭐ للسوق المالي التدقيق والتحقيق والتفتيش على أعضائه ومصدري الأوراق المدرجة\n⭐ المعلومات التي يطلع عليها السوق سرية ولا يجوز الإفصاح عنها إلا بموافقة المجلس\n⭐ للسوق تعليق تداول أوراق مالية معينة أو إيقاف أعمال عضو لأسباب مبررة شريطة إعلام الهيئة فوراً\n⭐ إذا عانى عضو من صعوبات مالية أو إدارية تهدد المصالح فعلى السوق إعلام الهيئة فوراً، وللهيئة بصورة مستعجلة تعليق أو منع أو الحد من خدمات السوق له","qs":[{"q":"لا يجوز للسوق المالي الإفصاح عن المعلومات السرية التي يطلع عليها موظفوه ومستشاروه إلا بعد:","o":["موافقة المجلس","موافقة مجلس إدارة السوق المالي","موافقة العضو المعني","صدور قرار قضائي"],"a":0},{"q":"قرر السوق المالي لأسباب مبررة تعليق تداول أسهم شركة مدرجة، فإن عليه:","o":["إعلام الهيئة فوراً بذلك","الحصول على موافقة رئيس الوزراء مسبقاً","الحصول على موافقة المركز مسبقاً","إعلام الهيئة خلال خمسة عشر يوماً"],"a":0},{"q":"تبين للسوق المالي أن أحد أعضائه يعاني من صعوبات مالية تهدد مصالح المستثمرين، فإن الجهة التي لها بصورة مستعجلة تعليق أو منع الخدمات التي يقدمها السوق لذلك العضو أو الحد منها هي:","o":["الهيئة","مركز إيداع الأوراق المالية","المحكمة المختصة","البنك المركزي"],"a":0}]},{"n":"66","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- لا يجوز لاي وسيط مالي او وسيط لحسابه ان يتداول اوراقا مالية لمصدر عام الا عن طريق سوق مالي ، ما لم تكن الورقة المالية معفاة من هذا الشرط من المجلس .\nب-لا يجوز التداول في السوق المالي الا بواسطة عقود تداول بين الوسطاء، مدونة في سجلات السوق المالي وتتم لحسابهم او لحساب عملائهم ، وفقا للانظمة الداخلية للسوق المالي وتعليماته الملزمة لجميع الاطراف المعنية بالتداول .\nج-تكون القيود المدونة في سجلات السوق المالي وحساباته ، سواء كانت خطية او الكترونية، واي وثائق صادرة عنه دليلا قانونيا على التداول وذلك بالتواريخ المبينة في تلك السجلات او الحسابات او الوثائق ما لم يثبت عكس ذلك .","title":"التداول عن طريق السوق المالي","memo":"⭐ لا يجوز للوسيط المالي أو الوسيط لحسابه تداول أوراق مالية لمصدر عام إلا عن طريق سوق مالي ما لم تكن معفاة من المجلس\n⭐ التداول بعقود بين الوسطاء مدونة في سجلات السوق\n⭐ قيود سجلات السوق خطية أو إلكترونية دليل قانوني على التداول ما لم يثبت عكس ذلك","qs":[{"q":"لا يجوز لأي وسيط مالي أن يتداول أوراقاً مالية لمصدر عام إلا عن طريق سوق مالي، ما لم:","o":["تكن الورقة المالية معفاة من هذا الشرط من المجلس","يوافق العميل على ذلك خطياً","تكن قيمة الصفقة أقل من الحد الذي يقرره المركز","يكن الوسيط عضواً في المركز"],"a":0},{"q":"القيود المدونة في سجلات السوق المالي وحساباته، الخطية أو الإلكترونية، تعتبر:","o":["دليلاً قانونياً على التداول ما لم يثبت عكس ذلك","دليلاً قاطعاً لا يقبل إثبات العكس","قرينة لا يعتد بها إلا بعد مصادقة المركز","غير ملزمة إذا كانت إلكترونية"],"a":0},{"q":"يتم التداول في السوق المالي بواسطة:","o":["عقود تداول بين الوسطاء مدونة في سجلات السوق المالي","عقود مباشرة بين البائع والمشتري دون وسطاء","أوامر تصدرها الهيئة","عقود موثقة لدى كاتب العدل"],"a":0}]},{"n":"67","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"تحدد متطلبات وشروط العضوية في السوق المالي بموجب انظمته الداخلية والتعليمات الصادرة عنه، على ان تتضمن إبرام اتفاقية تنظم حقوق والتزامات كل من السوق المالي والوسيط.","title":"شروط العضوية في السوق المالي","memo":"⭐ تحدد متطلبات وشروط العضوية في السوق المالي بموجب أنظمته الداخلية وتعليماته، على أن تتضمن إبرام اتفاقية تنظم حقوق والتزامات السوق والوسيط","qs":[{"q":"تحدد متطلبات وشروط العضوية في السوق المالي بموجب:","o":["أنظمته الداخلية والتعليمات الصادرة عنه","نظام يصدره مجلس الوزراء","تعليمات يصدرها مركز إيداع الأوراق المالية","قانون الشركات"],"a":0},{"q":"يشترط أن تتضمن متطلبات العضوية في السوق المالي:","o":["إبرام اتفاقية تنظم حقوق والتزامات كل من السوق المالي والوسيط","تقديم كفالة بنكية لصالح المركز","الحصول على موافقة رئيس الوزراء","إيداع نسبة من رأس مال الوسيط لدى السوق"],"a":0}]},{"n":"68","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- يلتزم اعضاء السوق المالي ومصدرو الاوراق المالية المدرجة لديه ومستخدمو مرافقه بانظمة السوق المالي الداخلية والتعليمات الصادرة عنه.\nب-على العضو الذي تم قبول عضويته في السوق المالي توقيع تعهد يؤكد وجوب تقيده بانظمة السوق المالي الداخلية وتعليماته .","title":"التزام الأعضاء بأنظمة السوق","memo":"⭐ يلتزم أعضاء السوق ومصدرو الأوراق المدرجة ومستخدمو مرافقه بأنظمة السوق الداخلية وتعليماته\n⭐ على العضو المقبول توقيع تعهد بالتقيد بأنظمة السوق وتعليماته","qs":[{"q":"على العضو الذي تم قبول عضويته في السوق المالي:","o":["توقيع تعهد يؤكد وجوب تقيده بأنظمة السوق المالي الداخلية وتعليماته","تقديم كفالة بنكية لصالح الهيئة","تعيين مدقق حسابات للسوق المالي","الحصول على موافقة مجلس الوزراء"],"a":0},{"q":"أي مما يلي لا يعد من الفئات الملزمة بأنظمة السوق المالي الداخلية وتعليماته وفقاً لنص القانون؟","o":["مدققو الحسابات الخارجيون للهيئة","أعضاء السوق المالي","مصدرو الأوراق المالية المدرجة لديه","مستخدمو مرافق السوق المالي"],"a":0}]},{"n":"69","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- يشترط لتداول أي ورقة مالية في السوق المالي ان تكون مودعة لدى المركز باستثناء الاوراق المالية التي يقرها المجلس .\nب-على كل شركة مساهمة عامة منشأة في المملكة وكل مصدر عام فيها ان يتقدم بطلب لادراج اوراقه المالية المصدرة لتداولها في السوق المالي.\nج-لا يجوز لاي مصدر اردني ادراج اوراقه المالية في سوق مالي او سوق تداول اوراق مالية خارج المملكة دون الحصول على موافقة المجلس المسبقة على ذلك .\nد-يحدد السوق المالي ، بموجب الانظمة الداخلية والتعليمات التي يصدرها الشروط والمعايير المختلفة التي يتوجب استيفاؤها لقبول تداول الاوراق المالية او ادراجها فيه ، ويجوز له ان يميز بين الاوراق المالية المدرجة وتلك المقبولة للتداول ويتوجب تطبيق معيار واحد لقبول تداول الاوراق المالية من الفئة نفسها والنوع ذاته والعائدة للمصدر ذاته .\nهـ-يجب ان تتضمن انظمة السوق المالي الداخلية وتعليماته المتعلقة بقبول تداول الاوراق المالية او ادراجها فيه قيام المصدر بابرام اتفاقيات مع كل من السوق المالي والمركز تنظم بموجبها حقوق والتزامات كل من المصدر والسوق المالي.\nو-على السوق المالي الذي يرغب في ادراج الاوراق المالية المصدرة منه ادراجاً ذاتياً الحصول على موافقة المجلس على ذلك والالتزام بالشروط والمتطلبات التي يحددها لهذه الغاية.","title":"إيداع الأوراق المالية وإدراجها","memo":"⭐ يشترط لتداول أي ورقة في السوق أن تكون مودعة لدى المركز باستثناء ما يقره المجلس\n⭐ على كل شركة مساهمة عامة وكل مصدر عام التقدم بطلب إدراج أوراقه في السوق المالي\n⭐ لا يجوز لمصدر أردني إدراج أوراقه في سوق خارج المملكة دون موافقة المجلس المسبقة\n⭐ الإدراج الذاتي للسوق المالي يحتاج موافقة المجلس، ويطبق معيار واحد للأوراق من الفئة والنوع والمصدر ذاته","qs":[{"q":"رغبت شركة مساهمة عامة أردنية في إدراج أسهمها في بورصة خارج المملكة، فإن ذلك يتطلب:","o":["الحصول على موافقة المجلس المسبقة","موافقة الهيئة العامة للشركة فقط","موافقة مركز إيداع الأوراق المالية","إعلام السوق المالي بعد الإدراج"],"a":0},{"q":"يشترط لتداول أي ورقة مالية في السوق المالي أن تكون:","o":["مودعة لدى المركز باستثناء الأوراق التي يقرها المجلس","مسجلة لدى وزارة الصناعة والتجارة","مضمونة من بنك مرخص","صادرة عن شركة مضى على تأسيسها سنتان"],"a":0},{"q":"الجهة التي يتعين على السوق المالي الحصول على موافقتها لإدراج الأوراق المالية المصدرة منه إدراجاً ذاتياً هي:","o":["المجلس","الهيئة العامة للسوق المالي","مركز إيداع الأوراق المالية","مجلس الوزراء"],"a":0}]},{"n":"70","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- على السوق المالي ان يقدم الى المجلس الانظمة الداخلية والتعليمات الخاصة به والمتعلقة بالتعامل بالاوراق المالية ، واي تعديلات تطرأ عليها ، للموافقة عليها قبل بدء العمل بها وللمجلس صلاحيات اجراء التعديل عليها .\nب-للمجلس الطلب من مجلس ادارة السوق المالي اجراء التعديلات على الانظمة الداخلية والتعليمات الصادرة عن السوق المالي والمتعلقة بالتعامل بالاوراق المالية ، والتي يراها ضرورية لتحقيق المصلحة العامة وحماية المستثمرين وذلك خلال مدة محددة في الطلب وله بعد انتهاء هذه المدة اجراء التعديلات التي يراها مناسبة وتعتبر تلك التعديلات نافذة اعتبارا من التاريخ الذي يحدده .\nج-لا يجوز تعديل عقد تاسيس السوق المالي او نظامه الاساسي فيما يتعلق بالتعامل بالاوراق المالية الا بموافقة المجلس.","title":"موافقة المجلس على أنظمة السوق","memo":"⭐ يقدم السوق المالي أنظمته الداخلية وتعليماته وتعديلاتها للمجلس للموافقة قبل بدء العمل بها، وللمجلس تعديلها\n⭐ للمجلس الطلب من مجلس إدارة السوق إجراء تعديلات خلال مدة محددة، وبعد انتهائها له إجراؤها وتنفذ من التاريخ الذي يحدده\n⭐ لا يجوز تعديل عقد تأسيس السوق أو نظامه الأساسي فيما يتعلق بالتعامل بالأوراق المالية إلا بموافقة المجلس","qs":[{"q":"الأنظمة الداخلية للسوق المالي المتعلقة بالتعامل بالأوراق المالية تقدم إلى المجلس:","o":["للموافقة عليها قبل بدء العمل بها","للعلم بعد بدء العمل بها","للنشر في الجريدة الرسمية فقط","خلال ثلاثين يوماً من بدء العمل بها"],"a":0},{"q":"طلب المجلس من مجلس إدارة السوق المالي إجراء تعديلات على تعليماته خلال مدة محددة فلم يقم بذلك، فإن للمجلس بعد انتهاء المدة:","o":["إجراء التعديلات التي يراها مناسبة وتكون نافذة من التاريخ الذي يحدده","تعليق نشاط السوق المالي لمدة شهر","حل مجلس إدارة السوق المالي","الطعن لدى المحكمة الإدارية"],"a":0},{"q":"لا يجوز تعديل عقد تأسيس السوق المالي أو نظامه الأساسي فيما يتعلق بالتعامل بالأوراق المالية إلا بموافقة:","o":["المجلس","الهيئة العامة للمركز","رئيس الوزراء","وزير الصناعة والتجارة"],"a":0}]},{"n":"71","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- يتقاضى السوق المالي العمولات والاجور واي بدل ينص على أي منها في انظمته الداخلية والتعليمات التي يصدرها لهذه الغاية.\nب-للسوق المالي فرض الغرامات وفقا لاحكام الانظمة الداخلية والتعليمات التي يصدرها .\nج-تؤول الى السوق المالي الغرامات التي يتم فرضها وفقا لاحكام الفقرة (ب) من هذه المادة .\nد-يعتبر مخالفة لانظمة السوق المالي الداخلية وتعليماته عدم دفع أي بدل او مستحقات مترتبة على العضو او مصدري الاوراق المالية المدرجة وللسوق المالي في هذه الحالة ايقاع عقوبات عليه بما في ذلك فرض الغرامات.","title":"عمولات السوق المالي وغراماته","memo":"⭐ يتقاضى السوق العمولات والأجور المنصوص عليها في أنظمته وتعليماته، وله فرض الغرامات وفقها\n⭐ تؤول الغرامات التي يفرضها السوق إلى السوق المالي\n⭐ عدم دفع العضو أو المصدر أي بدل أو مستحقات يعد مخالفة لأنظمة السوق ويجوز إيقاع عقوبات عليه بما فيها الغرامات","qs":[{"q":"الغرامات التي يفرضها السوق المالي وفقاً لأنظمته الداخلية وتعليماته تؤول إلى:","o":["السوق المالي","الخزينة العامة","الهيئة","مركز إيداع الأوراق المالية"],"a":0},{"q":"تخلف مصدر أوراق مالية مدرجة عن دفع البدلات المستحقة عليه للسوق المالي، فإن ذلك:","o":["يعد مخالفة لأنظمة السوق المالي ويجوز للسوق إيقاع عقوبات عليه بما فيها الغرامات","لا يعد مخالفة ويحصل البدل بالطرق القضائية فقط","يوجب على الهيئة شطب إدراج المصدر فوراً","يرتب على المركز دفع البدل نيابة عنه"],"a":0}]},{"n":"72","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"للمجلس تعليق نشاط السوق المالي لمدة لا تزيد على اسبوع وبموافقة رئيس الوزراء اذا زادت المدة على ذلك .","title":"تعليق نشاط السوق المالي","memo":"⭐ للمجلس تعليق نشاط السوق المالي لمدة لا تزيد على أسبوع، وبموافقة رئيس الوزراء إذا زادت المدة على ذلك","qs":[{"q":"للمجلس تعليق نشاط السوق المالي دون موافقة أي جهة أخرى لمدة لا تزيد على:","o":["أسبوع","ثلاثة أيام","خمسة عشر يوماً","شهر"],"a":0},{"q":"إذا رغب المجلس في تعليق نشاط السوق المالي لمدة تزيد على أسبوع، فإن ذلك يتطلب موافقة:","o":["رئيس الوزراء","وزير المالية","مجلس إدارة السوق المالي","المحكمة الإدارية"],"a":0}]},{"n":"73","chapter":"الترخيص والاعتماد والمراقبة","notes":[],"source":"أ- تكون القرارات الصادرة عن السوق المالي والمتعلقة بالتعامل في الاوراق المالية قابلة للاعتراض لدى المجلس خلال خمسة عشر يوما من اليوم التالي لتاريخ تبليغ القرار ويتوجب على المجلس الفصل في الاعتراض خلال خمسة عشر يوماً من تاريخ تقديم الاعتراض.\nب-يكون القرار الصادر عن المجلس بشان الاعتراض قابلاً للطعن لدى المحكمة الادارية خلال ثلاثين يوماً من تاريخ تبليغه.","title":"الاعتراض على قرارات السوق والطعن","memo":"⭐ قرارات السوق المتعلقة بالتعامل بالأوراق المالية قابلة للاعتراض لدى المجلس خلال (١٥) يوماً من اليوم التالي للتبليغ، ويفصل المجلس خلال (١٥) يوماً من تقديم الاعتراض\n⭐ قرار المجلس بشأن الاعتراض قابل للطعن لدى المحكمة الإدارية خلال (٣٠) يوماً من تبليغه","qs":[{"q":"مدة الاعتراض على قرارات السوق المالي المتعلقة بالتعامل في الأوراق المالية لدى المجلس هي:","o":["خمسة عشر يوماً من اليوم التالي لتاريخ تبليغ القرار","ثلاثون يوماً من تاريخ تبليغ القرار","ستون يوماً من تاريخ صدور القرار","سبعة أيام من تاريخ صدور القرار"],"a":0},{"q":"يكون قرار المجلس بشأن الاعتراض على قرار السوق المالي قابلاً للطعن لدى:","o":["المحكمة الإدارية خلال ثلاثين يوماً من تاريخ تبليغه","محكمة البداية خلال خمسة عشر يوماً من تاريخ تبليغه","محكمة الاستئناف خلال ثلاثين يوماً من تاريخ تبليغه","المحكمة الإدارية خلال ستين يوماً من تاريخ تبليغه"],"a":0},{"q":"يتوجب على المجلس الفصل في الاعتراض المقدم إليه على قرار السوق المالي خلال:","o":["خمسة عشر يوماً من تاريخ تقديم الاعتراض","ثلاثين يوماً من تاريخ تقديم الاعتراض","سبعة أيام من تاريخ تقديم الاعتراض","ستين يوماً من تاريخ تقديم الاعتراض"],"a":0}]},{"n":"74","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"ينشأ في المملكة مركز يسمى (مركز ايداع الاوراق المالية) يعتبر مؤسسة ذات نفع عام لا تهدف الى تحقيق الربح ويتمتع بشخصية اعتبارية ذات استقلال مالي واداري وله بهذه الصفة تملك الاموال المنقولة وغير المنقولة والتصرف بها والقيام بجميع التصرفات القانونية اللازمة لتحقيق اهدافه بما في ذلك ابرام العقود وله حق التقاضي وان ينيب عنه في الاجراءات القضائية أي محام يوكله لهذه الغاية.","title":"إنشاء مركز إيداع الأوراق المالية","memo":"⭐ المركز مؤسسة ذات نفع عام لا تهدف إلى الربح وتتمتع بشخصية اعتبارية ذات استقلال مالي وإداري\n⭐ له تملك الأموال المنقولة وغير المنقولة وإبرام العقود وحق التقاضي وإنابة محام عنه","qs":[{"q":"يعتبر مركز إيداع الأوراق المالية:","o":["مؤسسة ذات نفع عام لا تهدف إلى تحقيق الربح","شركة مساهمة عامة تهدف إلى تحقيق الربح","دائرة حكومية تابعة لوزارة المالية","مديرية تابعة للسوق المالي"],"a":0},{"q":"يتمتع مركز إيداع الأوراق المالية بشخصية اعتبارية ذات:","o":["استقلال مالي وإداري","استقلال إداري فقط وتتبع موازنته للهيئة","استقلال مالي فقط ويتبع إدارياً للسوق المالي","تبعية مالية وإدارية لوزارة المالية"],"a":0}]},{"n":"75","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"أ- يتولى المركز المهام التالية :-\n١-تسجيل الاوراق المالية وحفظ ونقل ملكيتها .\n٢-ايداع الاوراق المالية .\n٣-اجراء التقاص والتسوية للاوراق المالية .\nب-يكون المركز الجهة الوحيدة في المملكة المصرح لها بمزاولة الاعمال المنصوص عليها في الفقرة (أ) من هذه المادة .","title":"مهام مركز الإيداع","memo":"⭐ يتولى المركز: تسجيل الأوراق المالية وحفظ ونقل ملكيتها، إيداعها، إجراء التقاص والتسوية لها\n⭐ المركز الجهة الوحيدة في المملكة المصرح لها بمزاولة هذه الأعمال","qs":[{"q":"أي مما يلي لا يعد من المهام التي يتولاها مركز إيداع الأوراق المالية وفق القانون؟","o":["ترخيص الوسطاء الماليين","تسجيل الأوراق المالية وحفظ ونقل ملكيتها","إيداع الأوراق المالية","إجراء التقاص والتسوية للأوراق المالية"],"a":0},{"q":"الجهة الوحيدة في المملكة المصرح لها بإجراء التقاص والتسوية للأوراق المالية هي:","o":["مركز إيداع الأوراق المالية","السوق المالي","هيئة الأوراق المالية","البنك المركزي الأردني"],"a":0}]},{"n":"76","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"أ- يتولى ادارة المركز مجلس ادارة ومدير تنفيذي متفرغ ، وتحدد بموجب انظمته الداخلية وتعليماته التي تصدر لهذه الغاية الاحكام والاجراءات المتعلقة بهيئته العامة وكيفية تشكيل مجلس ادارته وعقد اجتماعاتهما واتخاذ القرارات والصلاحيات والمهام المنوطة بكل من الهيئة العامة ومجلس الادارة والمدير التنفيذي وسائر الامور الادارية والمالية الاخرى المتعلقة بهم .\nب-يعين المدير التنفيذي للمركز بقرار من مجلس الادارة ، وبموافقة المجلس ويحظر عليه ان يقوم بأي عمل آخر او ان يكون شريكا او مساهما في أي مرخص له او ان يكون ممثلا له.\nج-لا يجوز ان يكون رئيس مجلس ادارة المركز او نائبه شريكا او عضو مجلس ادارة او هيئة مديرين او موظفا في أي مرخص له او ان يكون ممثلا له .\nد-لا يجوز لاي شخص الجمع بين عضوية مجلس ادارة المركز وعضوية مجلس ادارة السوق المالي.","title":"إدارة مركز الإيداع","memo":"⭐ يتولى إدارة المركز مجلس إدارة ومدير تنفيذي متفرغ\n⭐ يعين المدير التنفيذي للمركز بقرار من مجلس إدارة المركز وبموافقة المجلس، ويحظر عليه أي عمل آخر أو أن يكون شريكاً أو مساهماً أو ممثلاً لمرخص له\n⭐ لا يجوز لرئيس مجلس إدارة المركز أو نائبه أن يكون شريكاً أو عضواً أو موظفاً لدى مرخص له، ولا يجوز الجمع بين عضوية مجلس إدارة المركز ومجلس إدارة السوق المالي","qs":[{"q":"يعين المدير التنفيذي لمركز إيداع الأوراق المالية بقرار من:","o":["مجلس إدارة المركز وبموافقة المجلس","المجلس بتنسيب من رئيس الهيئة","مجلس إدارة السوق المالي","الهيئة العامة للمركز دون حاجة لموافقة أي جهة"],"a":0},{"q":"الجمع المحظور صراحة بموجب القانون على أي شخص هو الجمع بين عضوية مجلس إدارة المركز وعضوية:","o":["مجلس إدارة السوق المالي","الهيئة العامة للمركز","لجنة التدقيق في شركة مساهمة عامة غير مرخص لها","جمعية المحاسبين القانونيين"],"a":0},{"q":"يتولى إدارة مركز إيداع الأوراق المالية:","o":["مجلس إدارة ومدير تنفيذي متفرغ","مجلس مفوضي الهيئة","مجلس إدارة السوق المالي","مدير عام يعينه مجلس الوزراء"],"a":0}]},{"n":"77","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"على مجلس ادارة المركز تعيين مدقق حسابات قانوني لتدقيق حسابات المركز .","title":"تدقيق حسابات المركز","memo":"⭐ على مجلس إدارة المركز تعيين مدقق حسابات قانوني لتدقيق حسابات المركز","qs":[{"q":"الجهة المختصة بتعيين مدقق حسابات قانوني لتدقيق حسابات مركز إيداع الأوراق المالية هي:","o":["مجلس إدارة المركز","المجلس","ديوان المحاسبة","الهيئة العامة للسوق المالي"],"a":0}]},{"n":"78","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"يحدد الهيكل التنظيمي للمركز ومجالات عمله وشروط العضوية فيه ومتطلباتها واي بدل يتقاضاه بمقتضى الانظمة الداخلية والتعليمات التي يصدرها المجلس .","title":"الهيكل التنظيمي للمركز","memo":"⭐ يحدد الهيكل التنظيمي للمركز ومجالات عمله وشروط العضوية فيه وأي بدل يتقاضاه بمقتضى الأنظمة الداخلية والتعليمات التي يصدرها المجلس","qs":[{"q":"تحدد شروط العضوية في مركز إيداع الأوراق المالية والبدل الذي يتقاضاه بمقتضى:","o":["الأنظمة الداخلية والتعليمات التي يصدرها المجلس","نظام يصدره مجلس الوزراء","تعليمات يصدرها السوق المالي","قرار من وزير المالية"],"a":0}]},{"n":"79","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"أ- مع مراعاة احكام المادة (٥) من هذا القانون ، على المصدر تسجيل الاوراق المالية التي يصدرها لدى المركز وفقا للتعليمات التي يصدرها .\nب-يتم الغاء شهادات الملكية الخاصة بالاوراق المالية المودعة لدى المركز وفقا للتعليمات التي يصدرها .\nج-يتم تسجيل الاوراق المالية المتداولة في السوق المالي ونقل ملكيتها وتسوية اثمانها بين الوسطاء بموجب قيود تدون في سجلات المركز.\nد-للمركز قبول البيانات الالكترونية من اعضائه ومن السوق المالي وذلك وفقا للانظمة الداخلية والتعليمات التي يصدرها .\nهـ-تكون القيود المدونة في سجلات المركز وحساباته ، سواء كانت خطية او الكترونية ، واي وثائق صادرة عنه دليلا قانونيا على ملكية الاوراق المالية المبينة فيها ، وعلى تسجيل ونقل ملكية تلك الاوراق المالية وعلى تسوية اثمانها وذلك وفق الاسعار وبالتواريخ المبينة في تلك السجلات او الحسابات او الوثائق ما لم يثبت عكس ذلك .\nو-اذا تقرر الحجز على أي ورقة مالية مودعة لدى المركز او فرض أي قيد يمنع التصرف بها بقرار قضائي ، فعلى المركز تثبيت ذلك القيد في سجلاته بتاريخ تسلمه ذلك القرار، ما لم يثبت ان تلك الاوراق المالية المودعة قد تم نقل ملكيتها قبل ذلك التاريخ .\nز-تنشأ الحقوق والالتزامات بين كل من بائع الورقة المالية ومشتريها والغير بتاريخ ابرام العقد في السوق المالي.\nح-على المركز توثيق ملكية الاوراق المالية التي تم بيعها وتثبيت نقل ملكيتها بسجلاته وفقا للتعليمات التي يصدرها .\nط-تتم تسوية عقود تداول الاوراق المالية المودعة لدى المركز على اساس التسليم مقابل الدفع.","title":"التسجيل لدى المركز وآثاره","memo":"⭐ على المصدر تسجيل أوراقه المالية لدى المركز، وتلغى شهادات الملكية للأوراق المودعة لديه\n⭐ قيود المركز خطية أو إلكترونية دليل قانوني على الملكية ونقلها وتسوية الأثمان ما لم يثبت العكس\n⭐ الحجز القضائي يثبت في سجلات المركز بتاريخ تسلمه القرار ما لم يثبت نقل الملكية قبله\n⭐ تنشأ الحقوق والالتزامات بين البائع والمشتري والغير بتاريخ إبرام العقد في السوق المالي، والتسوية على أساس التسليم مقابل الدفع","qs":[{"q":"تنشأ الحقوق والالتزامات بين بائع الورقة المالية ومشتريها والغير بتاريخ:","o":["إبرام العقد في السوق المالي","تسوية الثمن لدى المركز","توثيق نقل الملكية في سجلات المركز","تسليم شهادة الملكية للمشتري"],"a":0},{"q":"تتم تسوية عقود تداول الأوراق المالية المودعة لدى المركز على أساس:","o":["التسليم مقابل الدفع","الدفع المسبق قبل التسليم","التسليم ثم الدفع خلال ثلاثين يوماً","المقاصة السنوية بين الوسطاء"],"a":0},{"q":"صدر قرار قضائي بالحجز على أسهم مودعة لدى المركز، فإن على المركز تثبيت إشارة الحجز في سجلاته بتاريخ:","o":["تسلمه ذلك القرار ما لم يثبت نقل ملكية الأوراق قبل ذلك التاريخ","صدور القرار القضائي في جميع الأحوال","تبليغ مالك الأوراق بالقرار","موافقة المجلس على تنفيذ القرار"],"a":0},{"q":"القيود المدونة في سجلات المركز وحساباته، سواء كانت خطية أو إلكترونية، تعتبر:","o":["دليلاً قانونياً على ملكية الأوراق المالية ما لم يثبت عكس ذلك","دليلاً قاطعاً لا يقبل إثبات العكس","غير معتد بها ما لم تؤيد بشهادات ملكية ورقية","دليلاً على الملكية في حالة القيود الخطية فقط"],"a":0}]},{"n":"80","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"أ- تكون العضوية في المركز الزامية للجهات التالية :-\n١-الشركات المساهمة العامة .\n٢-الشخص الاعتباري المرخص له بممارسة اعمال الوسيط المالي أو الوسيط لحسابه .\n٣-الحافظ الامين .\n٤-أي جهة اخرى يحددها المجلس .\nب-لموظفي المركز المخولين من المرجع المختص التفتيش على وثائق وسجلات أي من اعضائه والحصول على نسخ منها ، سواء اكان ذلك باشعار مسبق ام بدونه وذلك فيما يتعلق بمهام المركز ، شريطة ان يتم التفتيش اثناء ساعات العمل .\nج-على العضو في المركز توقيع تعهد يؤكد وجوب تقيده بانظمة المركز الداخلية وتعليماته .\nد-يعتبر مخالفة لاحكام هذا القانون عدم الالتزام باحكام الانظمة الداخلية والتعليمات الصادرة عن المركز او تخلف عضو المركز عن دفع أي بدل واي مبالغ مالية مستحقة عليه للمركز.","title":"العضوية الإلزامية في المركز","memo":"⭐ العضوية في المركز إلزامية لـ: الشركات المساهمة العامة، الشخص الاعتباري المرخص له بأعمال الوسيط المالي أو الوسيط لحسابه، الحافظ الأمين، أي جهة يحددها المجلس\n⭐ لموظفي المركز المخولين التفتيش على وثائق وسجلات أعضائه بإشعار مسبق أو بدونه شريطة أن يكون أثناء ساعات العمل\n⭐ عدم الالتزام بأنظمة المركز أو التخلف عن دفع البدلات المستحقة له يعد مخالفة لأحكام القانون","qs":[{"q":"أي من الجهات التالية لا تعد العضوية في المركز إلزامية لها بنص القانون؟","o":["مكاتب تدقيق الحسابات","الشركات المساهمة العامة","الحافظ الأمين","الشخص الاعتباري المرخص له بممارسة أعمال الوسيط المالي"],"a":0},{"q":"يحق لموظفي المركز المخولين التفتيش على وثائق وسجلات أي من أعضائه:","o":["بإشعار مسبق أو بدونه شريطة أن يتم التفتيش أثناء ساعات العمل","بإشعار مسبق فقط وفي أي وقت","بعد الحصول على قرار قضائي","بإشعار مسبق مدته ثلاثة أيام على الأقل"],"a":0},{"q":"تخلف عضو في المركز عن دفع البدلات المستحقة عليه للمركز، فإن ذلك:","o":["يعد مخالفة لأحكام القانون","لا يرتب أي أثر سوى المطالبة المدنية","يعد مخالفة لأنظمة السوق المالي فقط","يوجب إلغاء ترخيص العضو فوراً"],"a":0}]},{"n":"81","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"أ- على المركز ان يقدم الى المجلس الانظمة الداخلية والتعليمات الخاصة به واي تعديلات تطرأ عليها والمتعلقة بالتعامل بالاوراق المالية للموافقة عليها قبل بدء العمل بها ، على ان تتضمن بصورة خاصة ما يلي:-\n١-اجراءات تسجيل الاوراق المالية ونقل ملكيتها والتقاص والتسوية لعقود التداول الخاصة بها.\n٢-تحديد حقوق والتزامات الاطراف ذات العلاقة بعمليات التقاص والتسوية ونقل ملكية الاوراق المالية .\n٣-الوقت الذي تنشأ عنده حقوق دائني اطراف عمليات التداول بالاوراق المالية ، بما في ذلك الحقوق المتعلقة بالمقابل النقدي او ما يعادله ، والاوراق المالية ذات العلاقة ، وذلك نتيجة لعمليات البيع او الشراء او نقل الملكية .\n٤-المعلومات والبيانات والسجلات التي تعتبر سرية والاشخاص المخولين بالاطلاع عليها بحكم عملهم .\n٥-المعلومات والبيانات والسجلات التي يتوجب على المركز الافصاح عنها ، وتلك التي يجوز للجمهور الاطلاع عليها والحصول على نسخ منها .\n٦-معايير السلوك المهني التي تطبق على كل من اعضاء المركز واعضاء مجلس ادارته ومديره التنفيذي والموظفين فيه .\nب-للمجلس الطلب من مجلس ادارة المركز اجراء التعديلات التي يراها ضرورية على الانظمة الداخلية والتعليمات الصادرة عن المركز والمتعلقة بالتعامل بالاوراق المالية والتي يراها ضرورية ، لحماية المستثمرين وتحقيق المصلحة العامة وذلك خلال مدة محددة في الطلب وله بعد انتهاء هذه المدة اجراء التعديلات التي يراها مناسبة على أي من الانظمة او التعليمات وتعتبر تلك التعديلات نافذة اعتبارا من التاريخ الذي يحدده .\nج-للمجلس النظر في القرارات الصادرة عن المركز والمتعلقة بالتعامل بالأوراق المالية للتأكد من اتفاقها مع احكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه واتخاذ القرارات المناسبة بشأنها.","title":"أنظمة المركز وتعليماته ورقابة المجلس","memo":"⭐ يقدم المركز أنظمته الداخلية وتعليماته وتعديلاتها المتعلقة بالتعامل بالأوراق المالية إلى المجلس للموافقة عليها قبل بدء العمل بها\n⭐ تتضمن: إجراءات التسجيل ونقل الملكية والتقاص والتسوية، حقوق الأطراف، وقت نشوء حقوق الدائنين، المعلومات السرية والمعلومات الواجب الإفصاح عنها، معايير السلوك المهني\n⭐ للمجلس طلب تعديلات خلال مدة محددة في الطلب، وله بعد انتهائها إجراء التعديلات بنفسه وتنفذ من التاريخ الذي يحدده\n⭐ للمجلس النظر في قرارات المركز المتعلقة بالتعامل بالأوراق المالية للتأكد من اتفاقها مع القانون","qs":[{"q":"يقدم المركز أنظمته الداخلية وتعليماته المتعلقة بالتعامل بالأوراق المالية للموافقة عليها قبل بدء العمل بها إلى:","o":["المجلس","مجلس الوزراء","الوزير","الهيئة العامة للمركز"],"a":0},{"q":"طلب المجلس من مجلس إدارة المركز إجراء تعديلات على تعليماته خلال مدة محددة ولم يستجب المركز، فإن للمجلس بعد انتهاء المدة:","o":["إجراء التعديلات التي يراها مناسبة وتنفذ اعتباراً من التاريخ الذي يحدده","إحالة الأمر إلى المحكمة المختصة لإلزام المركز","التنسيب لمجلس الوزراء بحل مجلس إدارة المركز","تمديد المدة لمرة واحدة فقط دون أن يملك التعديل"],"a":0},{"q":"أي مما يلي لا يعد من الأمور التي يجب أن تتضمنها الأنظمة الداخلية والتعليمات الخاصة بالمركز وفق المادة؟","o":["شروط ترخيص الوسطاء الماليين","إجراءات تسجيل الأوراق المالية ونقل ملكيتها والتقاص والتسوية","المعلومات والسجلات التي تعتبر سرية والأشخاص المخولين بالاطلاع عليها","معايير السلوك المهني لأعضاء المركز وموظفيه"],"a":0}]},{"n":"82","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"أ- يتقاضى المركز العمولات والاجور واي بدل ينص على أي منها في انظمته الداخلية .\nب-للمركز فرض الغرامات وفقا لاحكام الانظمة الداخلية والتعليمات التي يصدرها .\nج-تؤول الى المركز الغرامات التي يتم فرضها وفقا لاحكام الفقرة (ب) من هذه المادة .","title":"عمولات المركز وغراماته","memo":"⭐ يتقاضى المركز العمولات والأجور وأي بدل منصوص عليه في أنظمته الداخلية\n⭐ للمركز فرض الغرامات وفق أنظمته الداخلية وتعليماته\n⭐ تؤول الغرامات التي يفرضها المركز إلى المركز نفسه","qs":[{"q":"تؤول الغرامات التي يفرضها المركز وفقاً لأنظمته الداخلية وتعليماته إلى:","o":["المركز","الخزينة العامة","الهيئة","صندوق ضمان التسوية"],"a":0},{"q":"يتقاضى المركز العمولات والأجور وأي بدل استناداً إلى ما ينص عليه في:","o":["أنظمته الداخلية","نظام يصدره مجلس الوزراء","تعليمات يصدرها الوزير","قرار من رئيس الهيئة"],"a":0}]},{"n":"83","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"للمركز الحجز على الاوراق المالية المملوكة لاي من اعضائه في حال تخلفه عن تسوية الالتزامات المترتبة عليه والمتعلقة بمهام المركز .","title":"حجز المركز على أوراق أعضائه","memo":"⭐ للمركز الحجز على الأوراق المالية المملوكة لأي من أعضائه إذا تخلف عن تسوية الالتزامات المتعلقة بمهام المركز","qs":[{"q":"تخلف أحد أعضاء المركز عن تسوية الالتزامات المترتبة عليه والمتعلقة بمهام المركز، فإن للمركز:","o":["الحجز على الأوراق المالية المملوكة لذلك العضو","حبس العضو مدة لا تزيد على سنة","إلغاء ترخيص العضو مباشرة","تحصيل المبلغ وفق قانون الجرائم الاقتصادية"],"a":0}]},{"n":"84","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"أ- على الرغم مما ورد في أي تشريع آخر، عند صدور قرار بافلاس او بتصفية او الحجز على الوسيط المالي او الوسيط لحسابه او العضو في المركز وقبل الشروع في اجراءات الافلاس او التصفية او الحجز وفقا لاحكام التشريعات النافذة ، يتخذ المركز وفقا للتعليمات التي يصدرها ، الاجراءات اللازمة لاتمام تسوية عقود التداول التي كان العضو طرفا فيها قبل صدور ذلك القرار وتكون عقود التداول تلك بعد تسويتها نافذة في مواجهة الغير.\nب-على الرغم مما ورد في الفقرة (أ) من هذه المادة ، للمجلس من تلقاء نفسه او بناء على طلب أي طرف ذي علاقة تعديل او الغاء عقود التداول المشار اليها في الفقرة (أ) من هذه المادة او أي جزء منها على ان يكون هذا التعديل او الالغاء مبررا .","title":"تسوية عقود العضو المفلس أو المصفى","memo":"⭐ رغم أي تشريع آخر: عند صدور قرار بإفلاس أو تصفية أو حجز على الوسيط أو العضو، يتخذ المركز (قبل الشروع بالإجراءات) إجراءات إتمام تسوية عقود التداول السابقة للقرار\n⭐ عقود التداول بعد تسويتها نافذة في مواجهة الغير\n⭐ للمجلس من تلقاء نفسه أو بطلب ذي علاقة تعديل أو إلغاء تلك العقود أو جزء منها على أن يكون ذلك مبرراً","qs":[{"q":"عند صدور قرار بإفلاس عضو في المركز، يتخذ المركز إجراءات إتمام تسوية عقود التداول التي كان العضو طرفاً فيها:","o":["قبل الشروع في إجراءات الإفلاس","بعد انتهاء إجراءات الإفلاس","بعد موافقة وكيل التفليسة","بعد صدور حكم قطعي من المحكمة"],"a":0},{"q":"تكون عقود التداول التي يتم تسويتها من قبل المركز بعد صدور قرار تصفية العضو:","o":["نافذة في مواجهة الغير","باطلة بطلاناً مطلقاً","موقوفة على إجازة المصفي","قابلة للإبطال بطلب الدائنين"],"a":0},{"q":"الجهة التي لها تعديل أو إلغاء عقود التداول الخاصة بالعضو الذي صدر قرار بإفلاسه، على أن يكون ذلك مبرراً، هي:","o":["المجلس","مجلس إدارة المركز","المحكمة المختصة","مراقب عام الشركات"],"a":0}]},{"n":"85","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"أ- اذا وقع عجز في حساب الايرادات واجمالي النفقات في المركز لاي سنة مالية يغطى من الاحتياطي العام واذا لم يكف الاحتياطي العام لتغطية هذا العجز فعلى اعضاء المركز ان يدفعوا بالتساوي المبلغ الكافي لتغطيته ويكون ما تم دفعه دينا لهم على صافي الايرادات المتحققة فيما بعد .\nب-على الرغم مما ورد في الفقرة (أ) من هذه المادة لمجلس ادارة المركز بموافقة المجلس اقتراض المبلغ الكافي لتغطية العجز او أي جزء منه .\nج-في حال انقضاء الشخصية الاعتبارية للمركز بحله او بتصفيته او باي شكل من الاشكال تؤول امواله الى الخزينة العامة .","title":"عجز المركز وانقضاؤه","memo":"⭐ يغطى عجز المركز من الاحتياطي العام، فإن لم يكف يدفع الأعضاء بالتساوي ويكون ما دفعوه ديناً لهم على صافي الإيرادات اللاحقة\n⭐ لمجلس إدارة المركز بموافقة المجلس اقتراض المبلغ الكافي لتغطية العجز أو جزء منه\n⭐ عند انقضاء شخصية المركز بحله أو تصفيته تؤول أمواله إلى الخزينة العامة","qs":[{"q":"إذا وقع عجز في حساب إيرادات ونفقات المركز لأي سنة مالية فإنه يغطى أولاً من:","o":["الاحتياطي العام","مساهمة الأعضاء بالتساوي","صندوق ضمان التسوية","الخزينة العامة"],"a":0},{"q":"لم يكف الاحتياطي العام لتغطية عجز المركز، فدفع الأعضاء المبلغ الكافي لتغطيته. يكون ما دفعه الأعضاء:","o":["ديناً لهم على صافي الإيرادات المتحققة فيما بعد","تبرعاً غير مسترد","زيادة في رأسمال المركز","ديناً على الخزينة العامة"],"a":0},{"q":"في حال انقضاء الشخصية الاعتبارية للمركز بحله أو بتصفيته تؤول أمواله إلى:","o":["الخزينة العامة","أعضاء المركز بالتساوي","الهيئة","صندوق ضمان التسوية"],"a":0}]},{"n":"86","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"تعتبر اموال المركز وحقوقه لدى الغير اموالا عامة يتم تحصيلها وفقا لاحكام قانون تحصيل الاموال الاميرية المعمول به .","title":"أموال المركز أموال عامة","memo":"⭐ أموال المركز وحقوقه لدى الغير أموال عامة تحصل وفق قانون تحصيل الأموال الأميرية","qs":[{"q":"تحصّل أموال المركز وحقوقه لدى الغير وفقاً لأحكام:","o":["قانون تحصيل الأموال الأميرية","قانون التنفيذ","قانون أصول المحاكمات المدنية","قانون الشركات"],"a":0}]},{"n":"87","chapter":"مركز ايداع الاوراق المالية","notes":[],"source":"للمجلس تعليق نشاط المركز لمدة لا تزيد على اسبوع، وبموافقة رئيس الوزراء اذا زادت المدة على ذلك .","title":"تعليق نشاط المركز","memo":"⭐ للمجلس تعليق نشاط المركز مدة لا تزيد على أسبوع\n⭐ إذا زادت المدة على أسبوع يشترط موافقة رئيس الوزراء","qs":[{"q":"للمجلس تعليق نشاط المركز دون الحاجة لموافقة أي جهة أخرى لمدة لا تزيد على:","o":["أسبوع","ثلاثة أيام","شهر","ستة أشهر"],"a":0},{"q":"أراد المجلس تعليق نشاط المركز لمدة عشرة أيام، فإنه يحتاج إلى موافقة:","o":["رئيس الوزراء","مجلس الوزراء","الوزير","مجلس إدارة المركز"],"a":0}]},{"n":"88","chapter":"صندوق ضمان التسوية","notes":[],"source":"أ- ينشأ في المركز صندوق يسمى (صندوق ضمان التسوية) يتمتع بشخصية اعتبارية ذات استقلال مالي ويتولى المركز ادارته.\nب-تكون العضوية فيه الزامية للوسيط المالي وللوسيط لحسابه واي جهة اخرى يحددها النظام الداخلي للصندوق.\nج-يهدف الصندوق ، وبصورة خاصة ، الى تحقيق الاهداف التالية:-\n١-تغطية العجز النقدي لدى عضو الصندوق المشتري للاوراق المالية.\n٢-تغطية العجز في رصيد الاوراق المالية الذي يظهر لدى عضو الصندوق البائع نتيجة تداول الاوراق المالية في السوق المالي .\nد-يضع مجلس ادارة المركز ، بموافقة المجلس ، نظاما داخليا تحدد بمقتضاه كيفية ادارة الصندوق بما في ذلك بدل اشتراكات اعضائه والانتساب اليه والالتزامات المترتبة عليهم له وادارة موجوداته وطريقة عمله والالتزامات المترتبة عليه لاعضائه واحكام واجراءات تصفيته.\nهـ-يعتبر الصندوق الخلف القانوني والواقعي لصندوق ضمان الوسطاء الماليين وتؤول اليه جميع حقوقه والتزاماته وموجوداته وسجلاته وامواله .\nو-يخضع الصندوق لرقابة الهيئة واشرافها والتفتيش عليه والتدقيق على سجلاته.","title":"صندوق ضمان التسوية","memo":"⭐ ينشأ في المركز صندوق ضمان التسوية بشخصية اعتبارية واستقلال مالي ويديره المركز\n⭐ العضوية إلزامية للوسيط المالي والوسيط لحسابه وأي جهة يحددها النظام الداخلي للصندوق\n⭐ أهدافه: تغطية العجز النقدي لدى العضو المشتري، وتغطية العجز في رصيد الأوراق المالية لدى العضو البائع\n⭐ يضع نظامه الداخلي مجلس إدارة المركز بموافقة المجلس؛ وهو الخلف القانوني لصندوق ضمان الوسطاء الماليين ويخضع لرقابة الهيئة","qs":[{"q":"يتولى إدارة صندوق ضمان التسوية:","o":["المركز","الهيئة","السوق المالي","مجلس الوزراء"],"a":0},{"q":"أي مما يلي لا تكون العضوية في صندوق ضمان التسوية إلزامية له بموجب نص المادة مباشرة؟","o":["مدير الاستثمار","الوسيط المالي","الوسيط لحسابه","أي جهة أخرى يحددها النظام الداخلي للصندوق"],"a":0},{"q":"يعتبر صندوق ضمان التسوية الخلف القانوني والواقعي لـ:","o":["صندوق ضمان الوسطاء الماليين","صندوق حماية المستثمر","مركز إيداع الأوراق المالية","صندوق الاستثمار المشترك"],"a":0},{"q":"يضع النظام الداخلي لصندوق ضمان التسوية:","o":["مجلس إدارة المركز بموافقة المجلس","مجلس الوزراء بتنسيب من المجلس","المجلس بتنسيب من السوق المالي","الهيئة العامة لأعضاء الصندوق"],"a":0}]},{"n":"89","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"أ- يهدف صندوق الاستثمار المشترك إلى استثمار أموال الصندوق في الأوراق المالية من خلال إدارة متخصصة وعلى أساس توزيع مخاطر الاستثمار، ولا يجوز له ممارسة أي أعمال أخرى لا تتفق مع أعمال الاستثمار في الأوراق المالية.\nب-يتكون رأسمال صندوق الاستثمار المشترك من مجموع القيم الاسمية للوحدات الاستثمارية في الصندوق، ويجوز للصندوق وفقاً لما يتم تحديده في نظام الصندوق ونشرة الإصدار أن يكون ذا رأسمال متغير (مفتوح) أو ذا رأسمال ثابت (مغلق).","title":"هدف صندوق الاستثمار المشترك ورأسماله","memo":"⭐ يهدف الصندوق إلى استثمار أمواله في الأوراق المالية بإدارة متخصصة وعلى أساس توزيع المخاطر، ولا يجوز له ممارسة أعمال لا تتفق مع ذلك\n⭐ رأسماله = مجموع القيم الاسمية للوحدات الاستثمارية\n⭐ يجوز أن يكون ذا رأسمال متغير (مفتوح) أو ثابت (مغلق) وفق نظام الصندوق ونشرة الإصدار","qs":[{"q":"يتكون رأسمال صندوق الاستثمار المشترك من:","o":["مجموع القيم الاسمية للوحدات الاستثمارية","مجموع القيم السوقية للأوراق المالية المستثمر بها","صافي قيمة أصول الصندوق","رأسمال مدير الاستثمار"],"a":0},{"q":"صندوق الاستثمار المشترك ذو رأس المال المتغير يسمى صندوقاً:","o":["مفتوحاً","مغلقاً","مختلطاً","متوازناً"],"a":0},{"q":"يقوم استثمار أموال صندوق الاستثمار المشترك في الأوراق المالية على أساس:","o":["إدارة متخصصة وتوزيع مخاطر الاستثمار","تركيز الاستثمار في ورقة مالية واحدة","ضمان رأس المال من قبل الهيئة","توزيع أرباح ثابتة على المستثمرين"],"a":0}]},{"n":"90","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"أ- يقسم رأسمال صندوق الاستثمار المشترك إلى وحدات استثمارية متساوية في الحقوق، وتكون مسؤولية مالكي الوحدات الاستثمارية محدودة بمقدار حصصهم في رأسمال الصندوق.\nب-تكون الوحدات الاستثمارية نقدية، وتسدد قيمة الوحدات المكتتب بها دفعة واحدة عند الاكتتاب بها.\nج-لا يجوز لصندوق الاستثمار المشترك بيع وحداته الاستثمارية قبل تسجيله لدى الهيئة شريطة استيفاء الشروط والمتطلبات الواردة في التعليمات الصادرة لهذه الغاية.","title":"الوحدات الاستثمارية","memo":"⭐ يقسم رأسمال الصندوق إلى وحدات متساوية في الحقوق، ومسؤولية مالكيها محدودة بمقدار حصصهم\n⭐ الوحدات نقدية وتسدد قيمتها دفعة واحدة عند الاكتتاب\n⭐ لا يجوز للصندوق بيع وحداته قبل تسجيله لدى الهيئة","qs":[{"q":"تسدد قيمة الوحدات الاستثمارية المكتتب بها في صندوق الاستثمار المشترك:","o":["دفعة واحدة عند الاكتتاب","على قسطين خلال سنة","بنسبة ٢٥% عند الاكتتاب والباقي خلال سنتين","وفق ما يقرره مدير الاستثمار"],"a":0},{"q":"تكون مسؤولية مالكي الوحدات الاستثمارية في صندوق الاستثمار المشترك:","o":["محدودة بمقدار حصصهم في رأسمال الصندوق","غير محدودة وبالتضامن","محدودة بضعف قيمة حصصهم","محدودة بصافي قيمة أصول الصندوق كاملة"],"a":0},{"q":"لا يجوز لصندوق الاستثمار المشترك بيع وحداته الاستثمارية قبل:","o":["تسجيله لدى الهيئة","إدراجه في السوق المالي","موافقة مجلس الوزراء","تسجيله لدى مراقب عام الشركات"],"a":0}]},{"n":"91","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"أ- يحظر على أي شخص تجميع الأموال من الغير والتعامل معها على أنها وحدة واحدة لاستثمارها في الأوراق المالية، وإدارة استثمار هذه الأموال إلا من خلال إنشاء صندوق استثمار مشترك مسجل لدى الهيئة أو شركة استثمار مشترك مرخصه منها وذلك وفقاً لأحكام هذا القانون والأنظمة والتعليمات والقرارات الصادرة بمقتضاه.\nب-تستثنى من أحكام الفقرة (أ) من هذه المادة:-\n١-البنوك المرخصة، فيما يتعلق بممارسة أعمالها المصرفية وفقاً للتشريعات النافذة.\n٢-شركات التأمين المرخصة، فيما يتعلق بممارسة أعمال التأمين وفقاً للتشريعات النافذة.","title":"حظر تجميع الأموال للاستثمار","memo":"⭐ يحظر تجميع الأموال من الغير كوحدة واحدة لاستثمارها في الأوراق المالية إلا من خلال صندوق استثمار مشترك مسجل لدى الهيئة أو شركة استثمار مشترك مرخصة منها\n⭐ يستثنى: البنوك المرخصة (أعمالها المصرفية) وشركات التأمين المرخصة (أعمال التأمين)","qs":[{"q":"لا يجوز تجميع الأموال من الغير والتعامل معها كوحدة واحدة لاستثمارها في الأوراق المالية إلا من خلال:","o":["صندوق استثمار مشترك مسجل لدى الهيئة أو شركة استثمار مشترك مرخصة منها","شركة مساهمة خاصة مسجلة لدى مراقب الشركات","وسيط مالي مرخص من السوق المالي","أي شركة ذات مسؤولية محدودة"],"a":0},{"q":"يستثنى من حظر تجميع الأموال من الغير لاستثمارها في الأوراق المالية، فيما يتعلق بممارسة أعمالها وفق التشريعات النافذة:","o":["شركات التأمين المرخصة","شركات الوساطة المالية","شركات الصرافة","الجمعيات التعاونية"],"a":0},{"q":"أي مما يلي لا يعد من الجهات المستثناة من حظر تجميع الأموال وفق المادة؟","o":["الوسيط لحسابه","البنوك المرخصة فيما يتعلق بأعمالها المصرفية","شركات التأمين المرخصة فيما يتعلق بأعمال التأمين","البنوك المرخصة وشركات التأمين المرخصة وفق التشريعات النافذة"],"a":0}]},{"n":"92","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"أ- يجوز إنشاء صناديق الاستثمار المشترك من قبل الشركات المرخصة لممارسة أعمال إدارة الاستثمار.\nب-يشترط في طالب تأسيس صندوق الاستثمار المشترك ما يلي:-\n١-أن يكون قد مضى على حصوله على ترخيص من المجلس لمزاولة نشاط مدير الاستثمار مدة لا تقل عن سنتين.\n٢-أن يقدم خلال المدة المنصوص عليها في البند (١) من هذه الفقرة بيانات مالية نهائية مدققة لكل سنة من السنتين التي تسبق طلب التأسيس.\nج-يكون مدير الاستثمار مديراً لصندوق الاستثمار المشترك.\nد-يجوز للمجلس استثناء طالب التأسيس من شرط المدة المنصوص عليه في البند (١) من الفقرة (ب) من هذه المادة إذا كان طالب التأسيس بنكاً مرخصاً أو شركة خدمات مالية تابعة له.","title":"تأسيس صندوق الاستثمار المشترك","memo":"⭐ ينشأ الصندوق من قبل الشركات المرخصة لممارسة أعمال إدارة الاستثمار\n⭐ شروط طالب التأسيس: مضي سنتين على الأقل على ترخيصه كمدير استثمار، وتقديم بيانات مالية نهائية مدققة لكل من السنتين السابقتين للطلب\n⭐ مدير الاستثمار هو مدير الصندوق\n⭐ للمجلس استثناء البنك المرخص أو شركة الخدمات المالية التابعة له من شرط المدة","qs":[{"q":"يشترط في طالب تأسيس صندوق الاستثمار المشترك أن يكون قد مضى على حصوله على ترخيص مدير الاستثمار مدة لا تقل عن:","o":["سنتين","سنة","ثلاث سنوات","خمس سنوات"],"a":0},{"q":"يجوز للمجلس استثناء طالب تأسيس صندوق الاستثمار المشترك من شرط المدة إذا كان:","o":["بنكاً مرخصاً أو شركة خدمات مالية تابعة له","شركة تأمين مرخصة","وسيطاً مالياً مضى على ترخيصه سنة","شركة مساهمة عامة مدرجة"],"a":0},{"q":"يكون مديراً لصندوق الاستثمار المشترك:","o":["مدير الاستثمار","أمين الاستثمار","مدقق حسابات الصندوق","رئيس الهيئة"],"a":0}]},{"n":"93","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"أ- يكون لكل صندوق استثمار مشترك مسجل لدى الهيئة شخصية اعتبارية وذمة مالية مستقلة عن البنك أو الشركة التي قامت بانشائه وعن حملة وحداته الاستثمارية.\nب-يمثل مدير صندوق الاستثمار المشترك الصندوق لدى الغير وأمام القضاء ويتولى التوقيع عنه.","title":"شخصية الصندوق وتمثيله","memo":"⭐ لكل صندوق مسجل لدى الهيئة شخصية اعتبارية وذمة مالية مستقلة عن البنك أو الشركة المنشئة وعن حملة وحداته\n⭐ يمثل مدير الصندوق الصندوق لدى الغير وأمام القضاء ويوقع عنه","qs":[{"q":"يمثل صندوق الاستثمار المشترك لدى الغير وأمام القضاء ويتولى التوقيع عنه:","o":["مدير صندوق الاستثمار المشترك","أمين الاستثمار","رئيس الهيئة","مدقق حسابات الصندوق"],"a":0},{"q":"تكون الذمة المالية لصندوق الاستثمار المشترك المسجل لدى الهيئة:","o":["مستقلة عن الشركة التي أنشأته وعن حملة وحداته","جزءاً من ذمة الشركة التي أنشأته","مشتركة بين مدير الاستثمار وحملة الوحدات","تابعة لذمة أمين الاستثمار"],"a":0}]},{"n":"94","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"أ- لصندوق الاستثمار المشترك المغلق ان يتحول إلى صندوق استثمار مشترك مفتوح إذا نص نظامه الأساسي على ذلك على أن يوفق أوضاعه وفقاً لأحكام هذا القانون والأنظمة والتعليمات والقرارات الصادرة بمقتضاه.\nب-لا يجوز لصندوق الاستثمار المشترك المفتوح التوقف عن إصدار وحداته الاستثمارية أو استردادها في المواعيد المحددة في نظامه الأساسي إلا بموافقة المجلس.","title":"تحول الصندوق المغلق والتوقف","memo":"⭐ للصندوق المغلق التحول إلى مفتوح إذا نص نظامه الأساسي على ذلك مع توفيق أوضاعه\n⭐ لا يجوز للصندوق المفتوح التوقف عن إصدار وحداته أو استردادها في المواعيد المحددة إلا بموافقة المجلس","qs":[{"q":"يجوز لصندوق الاستثمار المشترك المغلق أن يتحول إلى صندوق مفتوح إذا:","o":["نص نظامه الأساسي على ذلك","وافق مجلس الوزراء على ذلك","مضى على تأسيسه سنتان","وافق ثلثا حملة الوحدات الاستثمارية"],"a":0},{"q":"أراد صندوق استثمار مشترك مفتوح التوقف عن استرداد وحداته في المواعيد المحددة في نظامه الأساسي، فإن ذلك يتطلب موافقة:","o":["المجلس","أمين الاستثمار","مجلس إدارة المركز","مراقب عام الشركات"],"a":0}]},{"n":"95","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"أ- لصندوق الاستثمار المشترك المفتوح إصدار وحداته الاستثمارية واستردادها ولا تكون قابلة للتحويل إلا بالإرث أو بالخلف القانوني.\nب-يحدد سعر إصدار الوحدات الاستثمارية أو سعر استردادها على أساس صافي قيمة أصول صندوق الاستثمار المشترك المفتوح ووفقاً للاسس التي يحددها المجلس بموجب تعليمات يصدرها لهذه الغاية.","title":"إصدار وحدات الصندوق المفتوح واستردادها","memo":"⭐ للصندوق المفتوح إصدار وحداته واستردادها، ولا تكون قابلة للتحويل إلا بالإرث أو بالخلف القانوني\n⭐ يحدد سعر الإصدار أو الاسترداد على أساس صافي قيمة أصول الصندوق ووفق أسس يحددها المجلس بتعليمات","qs":[{"q":"لا تكون الوحدات الاستثمارية لصندوق الاستثمار المشترك المفتوح قابلة للتحويل إلا:","o":["بالإرث أو بالخلف القانوني","بالبيع في السوق المالي","بموافقة مدير الاستثمار","بالهبة بين الأقارب"],"a":0},{"q":"يحدد سعر إصدار أو استرداد الوحدات الاستثمارية للصندوق المفتوح على أساس:","o":["صافي قيمة أصول الصندوق","القيمة الاسمية للوحدة","سعر الإغلاق في السوق المالي","متوسط سعر الاكتتاب"],"a":0}]},{"n":"96","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"لا يجوز أن يكون لمدير الاستثمار أو أمين الاستثمار أو مدقق حسابات الصندوق أو الشركات التابعة له أو الحليفة أو المملوكة لأي منهم مصلحة مباشرة أو غير مباشرة في استثمار أموال الصندوق.","title":"حظر تعارض المصالح في الصندوق","memo":"⭐ لا يجوز أن يكون لمدير الاستثمار أو أمين الاستثمار أو مدقق حسابات الصندوق أو الشركات التابعة أو الحليفة أو المملوكة لأي منهم مصلحة مباشرة أو غير مباشرة في استثمار أموال الصندوق","qs":[{"q":"أي مما يلي لم تذكره المادة ضمن من يحظر عليهم أن يكون لهم مصلحة مباشرة أو غير مباشرة في استثمار أموال صندوق الاستثمار المشترك؟","o":["حملة الوحدات الاستثمارية","مدير الاستثمار","أمين الاستثمار","مدقق حسابات الصندوق"],"a":0},{"q":"يحظر على مدقق حسابات صندوق الاستثمار المشترك أن تكون له في استثمار أموال الصندوق مصلحة:","o":["مباشرة أو غير مباشرة","مباشرة فقط","تزيد على ٥% من أموال الصندوق","غير مفصح عنها للهيئة فقط"],"a":0}]},{"n":"97","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"أ- للمجلس الموافقة على تنظيم أي شكل آخر من صناديق الاستثمار المشترك في الأوراق المالية.\nب-تحدد الأمور المتعلقة بتنظيم أي من صناديق الاستثمار المشترك بما في ذلك، المتعلقة بإنشائه ومتطلبات تسجيله لدى الهيئة ورأسماله وبيانات نشرة الإصدار ونظامه وشروط عرض الوحدات الاستثمارية وإصدارها والاكتتاب فيها، وحقوق حملة الوحدات الاستثمارية المصدرة وإجراءات تداولها واستردادها، والأجور والعمولات التي يتقاضاها وأسس استثمار أمواله وتعيين المسؤولين عن إدارته ومزودي خدماته وعزل أي منهم وأسباب انقضائه واندماج الصناديق وإجراءات تصفيته، والأمور المتعلقة بعمله بموجب نظام يصدر لهذه الغاية.","title":"تنظيم أشكال الصناديق الأخرى","memo":"⭐ للمجلس الموافقة على تنظيم أي شكل آخر من صناديق الاستثمار المشترك في الأوراق المالية\n⭐ تحدد أمور تنظيم الصناديق (الإنشاء، التسجيل، رأس المال، نشرة الإصدار، الوحدات، الأجور، التصفية والاندماج...) بموجب نظام يصدر لهذه الغاية","qs":[{"q":"الجهة التي لها الموافقة على تنظيم أي شكل آخر من صناديق الاستثمار المشترك في الأوراق المالية هي:","o":["المجلس","مجلس الوزراء","السوق المالي","المركز"],"a":0},{"q":"تحدد الأمور المتعلقة بتنظيم صناديق الاستثمار المشترك، ومنها اندماج الصناديق وإجراءات تصفيتها، بموجب:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها رئيس الهيئة","النظام الداخلي للمركز","قرار من مدير الاستثمار"],"a":0}]},{"n":"98","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"أ- لا يجوز تسجيل أي شركة استثمار مشترك لدى مراقب عام الشركات إلا بعد الحصول على موافقة خطية مبدئية مسبقة من الهيئة.\nب-لا يجوز لشركة الاستثمار المشترك إجراء أي تعديل على عقد تأسيسها أو نظامها الأساسي إلا بعد الحصول على موافقة خطية مسبقة من الهيئة.\nج-يجب أن تكون أسهم شركة الاستثمار المشترك نقدية وأن تسدد قيمة الأسهم المكتتب بها دفعة واحدة.","title":"تسجيل شركة الاستثمار المشترك","memo":"⭐ لا تسجل شركة الاستثمار المشترك لدى مراقب عام الشركات إلا بعد موافقة خطية مبدئية مسبقة من الهيئة\n⭐ لا يجوز تعديل عقد تأسيسها أو نظامها الأساسي إلا بموافقة خطية مسبقة من الهيئة\n⭐ أسهمها نقدية وتسدد قيمتها دفعة واحدة","qs":[{"q":"لا يجوز تسجيل أي شركة استثمار مشترك لدى مراقب عام الشركات إلا بعد الحصول على:","o":["موافقة خطية مبدئية مسبقة من الهيئة","موافقة مجلس الوزراء","موافقة البنك المركزي","إدراج أسهمها في السوق المالي"],"a":0},{"q":"تسدد قيمة أسهم شركة الاستثمار المشترك المكتتب بها:","o":["دفعة واحدة","على أقساط خلال سنتين","بنسبة ٥٠% عند الاكتتاب","نقداً أو عيناً حسب النظام الأساسي"],"a":0},{"q":"أرادت شركة استثمار مشترك تعديل نظامها الأساسي، فإنه يلزمها:","o":["الحصول على موافقة خطية مسبقة من الهيئة","إشعار الهيئة خلال ثلاثين يوماً من التعديل","موافقة مدير الاستثمار فقط","موافقة المركز"],"a":0}]},{"n":"99","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"لا يجوز أن يكون لمدير الاستثمار أو أمين الاستثمار أو مدقق حسابات شركة الاستثمار المشترك أو الشركات التابعة أو الحليفة أو المملوكة لأي منهم أو أعضاء مجلس الإدارة أو مديرها العام أو أي موظف فيها مصلحة مباشرة أو غير مباشرة في أي استثمار لأموال شركة الاستثمار المشترك.","title":"حظر تعارض المصالح في شركة الاستثمار","memo":"⭐ لا يجوز لمدير الاستثمار أو أمين الاستثمار أو مدقق الحسابات أو الشركات التابعة أو الحليفة أو المملوكة لأي منهم أو أعضاء مجلس الإدارة أو المدير العام أو أي موظف أن تكون لهم مصلحة مباشرة أو غير مباشرة في أي استثمار لأموال شركة الاستثمار المشترك","qs":[{"q":"يحظر على أي من الآتية أسماؤهم أن تكون له مصلحة مباشرة أو غير مباشرة في استثمار أموال شركة الاستثمار المشترك، باستثناء:","o":["مساهمي الشركة من الجمهور","المدير العام للشركة","أعضاء مجلس الإدارة","أي موظف في الشركة"],"a":0},{"q":"موظف في شركة استثمار مشترك له مصلحة غير مباشرة في أحد استثمارات أموال الشركة. وفق المادة فإن ذلك:","o":["غير جائز","جائز إذا أفصح عنه لمجلس الإدارة","جائز إذا لم تتجاوز المصلحة ١٠%","جائز لأن الحظر يقتصر على المصلحة المباشرة"],"a":0}]},{"n":"100","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"تحدد إجراءات إصدار أسهم شركة الاستثمار المشترك واستردادها أو تداولها ويحدد رأسمالها وطرق تغطيته والبيانات التي يتوجب توافرها في عقد تأسيسها ونظامها الأساسي ونشرة إصدارها وكيفية إدارتها وإدارة استثماراتها والشروط الواجب توافرها في أعضاء مجلس إدارتها ومديرها العام وتعيين مدير الاستثمار وأمين الاستثمار ومزودي خدماتها وعزل أي منهم والأمور المتعلقة بتنظيم أعمالها بموجب نظام يصدر لهذه الغاية.","title":"تنظيم شركة الاستثمار المشترك بنظام","memo":"⭐ تحدد بموجب نظام: إجراءات إصدار أسهم الشركة واستردادها وتداولها، رأسمالها، بيانات عقد التأسيس والنظام الأساسي ونشرة الإصدار، شروط أعضاء مجلس الإدارة والمدير العام، وتعيين مدير وأمين الاستثمار وعزلهم","qs":[{"q":"تحدد إجراءات إصدار أسهم شركة الاستثمار المشترك واستردادها وتداولها بموجب:","o":["نظام يصدر لهذه الغاية","تعليمات يصدرها مراقب عام الشركات","النظام الداخلي للسوق المالي","قرار من مجلس إدارة الشركة"],"a":0},{"q":"أي مما يلي لم تذكره المادة ضمن الأمور التي تحدد بموجب النظام الخاص بشركة الاستثمار المشترك؟","o":["العقوبات الجزائية على مخالفات الشركة","الشروط الواجب توافرها في أعضاء مجلس إدارتها ومديرها العام","تعيين مدير الاستثمار وأمين الاستثمار وعزل أي منهم","رأسمال الشركة وطرق تغطيته"],"a":0}]},{"n":"101","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"تحدد الأسس والمعايير المتعلقة بتنويع استثمارات صندوق الاستثمار المشترك وشركة الاستثمار المشترك وأنواع التعامل المسموح بها وفقاً لتعليمات يصدرها المجلس لهذه الغاية.","title":"تنويع الاستثمارات","memo":"⭐ تحدد أسس ومعايير تنويع استثمارات الصندوق وشركة الاستثمار المشترك وأنواع التعامل المسموح بها بتعليمات يصدرها المجلس","qs":[{"q":"تحدد الأسس والمعايير المتعلقة بتنويع استثمارات صندوق وشركة الاستثمار المشترك وأنواع التعامل المسموح بها وفق:","o":["تعليمات يصدرها المجلس","نظام يصدره مجلس الوزراء","قرار مدير الاستثمار","النظام الداخلي للمركز"],"a":0}]},{"n":"102","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"يتولى تدقيق حسابات صندوق الاستثمار المشترك وشركة الاستثمار المشترك مدقق حسابات قانوني يتم التعاقد معه وتحديد مهامه.","title":"تدقيق حسابات الصندوق والشركة","memo":"⭐ يتولى تدقيق حسابات صندوق وشركة الاستثمار المشترك مدقق حسابات قانوني يتم التعاقد معه وتحديد مهامه","qs":[{"q":"يتولى تدقيق حسابات صندوق الاستثمار المشترك وشركة الاستثمار المشترك:","o":["مدقق حسابات قانوني يتم التعاقد معه","أمين الاستثمار","ديوان المحاسبة","مدير الاستثمار"],"a":0}]},{"n":"103","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"يتولى أمين الاستثمار تقييم استثمارات صندوق الاستثمار المشترك وشركة الاستثمار المشترك ومتابعتها، والتأكد من تطابقها مع السياسة الاستثمارية الواردة في نظامها الأساسي وأحكام هذا القانون والأنظمة والتعليمات والقرارات الصادرة بمقتضاه مع تبليغ الهيئة عن أي تجاوزات بهذا الشأن.","title":"مهام أمين الاستثمار","memo":"⭐ يتولى أمين الاستثمار تقييم استثمارات الصندوق والشركة ومتابعتها والتأكد من تطابقها مع السياسة الاستثمارية والقانون\n⭐ يبلغ الهيئة عن أي تجاوزات","qs":[{"q":"يتولى تقييم استثمارات صندوق الاستثمار المشترك ومتابعتها والتأكد من تطابقها مع السياسة الاستثمارية:","o":["أمين الاستثمار","مدير الاستثمار","مدقق الحسابات القانوني","المركز"],"a":0},{"q":"إذا اكتشف أمين الاستثمار تجاوزاً للسياسة الاستثمارية الواردة في النظام الأساسي لشركة الاستثمار المشترك فعليه تبليغ:","o":["الهيئة","مراقب عام الشركات","السوق المالي","النيابة العامة"],"a":0}]},{"n":"104","chapter":"صناديق الاستثمار المشترك وشركات الاستثمار","notes":[],"source":"يكون كل من مدير الاستثمار وأمين الاستثمار مسؤولاً عن أي خطأ أو إهمال أو تقصير في مهامه ويتحمل التبعات القانونية عن الأضرار التي تلحق بمالكي الوحدات الاستثمارية أو الأسهم.","title":"مسؤولية مدير وأمين الاستثمار","memo":"⭐ كل من مدير الاستثمار وأمين الاستثمار مسؤول عن أي خطأ أو إهمال أو تقصير في مهامه\n⭐ يتحمل التبعات القانونية عن الأضرار اللاحقة بمالكي الوحدات الاستثمارية أو الأسهم","qs":[{"q":"يتحمل التبعات القانونية عن الأضرار التي تلحق بمالكي الوحدات الاستثمارية نتيجة الخطأ أو الإهمال أو التقصير في مهامه كل من:","o":["مدير الاستثمار وأمين الاستثمار","الهيئة والمركز","السوق المالي والوسيط المالي","مدقق الحسابات وحده"],"a":0},{"q":"لحق ضرر بمالكي أسهم شركة استثمار مشترك بسبب تقصير أمين الاستثمار في مهامه. وفق المادة فإن أمين الاستثمار:","o":["مسؤول ويتحمل التبعات القانونية عن الأضرار","غير مسؤول لأن المسؤولية تقع على مدير الاستثمار فقط","مسؤول فقط إذا ثبت قصده الجرمي","غير مسؤول إلا إذا كان التقصير جسيماً"],"a":0}]},{"n":"105","chapter":"المخالفات والعقوبات","notes":[],"source":"يعتبر مخالفة لاحكام هذا القانون أي مما يلي :-\nأ-تقديم بيانات غير صحيحة او مضللة في أي من الوثائق التي يتم تقديمها الى الهيئة .\nب-عرض اوراق مالية او بيعها بناء على بيانات غير صحيحة او مضللة بشأن :-\n١-الحقوق والميزات التي تمنحها الاوراق المالية التي تم عرضها او بيعها .\n٢-طبيعة الاعمال التي يمارسها المصدر او مدى نجاح تلك الاعمال او الاوضاع المالية للمصدر او التوقعات المستقبلية له .\nج-تصديق مدقق الحسابات على بيانات مالية غير صحيحة او مضللة او مخالفة للمعايير المحاسبية المعتمدة ومعايير التدقيق المعتمدة، ويكون مسؤولا عن تعويض أي شخص تلحق به خسارة مالية نتيجة لذلك.\nد-أي خداع أو تضليل يتعلق بالاوراق المالية أو أي ممارسة محظورة فيما يتعلق بالاعمال المرخصة وفقا لاحكام هذا القانون.\nهـ-تداول أوراق مالية أو حمل الغير على تداولها بناء على معلومات داخلية.\nو-استغلال معلومات داخلية أو سرية لتحقيق مكاسب مادية أو معنوية له أو لغيره، بما في ذلك أعضاء مجلس إدارة السوق المالي والمركز وموظفو كل منهما.\nز-إفشاء المعلومات الداخلية لغير مرجعه المختص أو القضاء.","title":"المخالفات لأحكام القانون","memo":"⭐ من المخالفات: تقديم بيانات غير صحيحة أو مضللة للهيئة؛ عرض أو بيع أوراق مالية بناء على بيانات مضللة\n⭐ تصديق مدقق الحسابات على بيانات مالية غير صحيحة أو مضللة أو مخالفة للمعايير، ويكون مسؤولاً عن تعويض المتضرر\n⭐ التداول أو حمل الغير على التداول بناء على معلومات داخلية، واستغلال المعلومات الداخلية أو السرية\n⭐ إفشاء المعلومات الداخلية لغير مرجعه المختص أو القضاء","qs":[{"q":"مدقق حسابات صادق على بيانات مالية مخالفة لمعايير التدقيق المعتمدة، فتكبد أحد المستثمرين خسارة مالية نتيجة لذلك. وفق المادة فإن المدقق:","o":["يرتكب مخالفة ويكون مسؤولاً عن تعويض المستثمر","لا يسأل إلا إذا ثبت سوء نيته","يتحمل المسؤولية الشركة المصدرة وحدها","يرتكب مخالفة إدارية دون أي مسؤولية عن التعويض"],"a":0},{"q":"لا يعد إفشاء المعلومات الداخلية مخالفة إذا كان الإفشاء إلى:","o":["المرجع المختص أو القضاء","أحد أعضاء مجلس إدارة السوق المالي","وسائل الإعلام","أحد كبار المساهمين"],"a":0},{"q":"أي مما يلي لا يعد مخالفة لأحكام القانون وفق المادة؟","o":["تداول أوراق مالية بناء على معلومات منشورة للجمهور","تداول أوراق مالية أو حمل الغير على تداولها بناء على معلومات داخلية","تقديم بيانات مضللة في الوثائق المقدمة إلى الهيئة","عرض أوراق مالية بناء على بيانات مضللة بشأن الأوضاع المالية للمصدر"],"a":0}]},{"n":"106","chapter":"المخالفات والعقوبات","notes":[],"source":"يحظر على أي شخص القيام بأي مما يلي :-\nأ-بث الشائعات او ترويجها او اعطاء معلومات او بيانات او تصريحات مضللة او غير صحيحة قد تؤثر على سعر أي ورقة مالية او على سمعة أي جهة مصدرة .\nب-التاثير على المعاملات المتعلقة بالاوراق المالية ، سواء منفردا او بالتواطؤ مع غيره ، بقصد اعطاء صورة غير صحيحة عن سعر أي ورقة مالية او حجم تداولها او عن سعر او حجم تداول أي اوراق مالية اخرى ذات علاقة .","title":"حظر الشائعات والتلاعب","memo":"⭐ يحظر بث الشائعات أو ترويجها أو إعطاء معلومات أو تصريحات مضللة قد تؤثر على سعر ورقة مالية أو سمعة جهة مصدرة\n⭐ يحظر التأثير على المعاملات منفرداً أو بالتواطؤ بقصد إعطاء صورة غير صحيحة عن سعر ورقة مالية أو حجم تداولها","qs":[{"q":"قام شخص بالتعامل على سهم بالتواطؤ مع آخرين بقصد إعطاء صورة غير صحيحة عن حجم تداوله. هذا الفعل:","o":["محظور سواء تم منفرداً أو بالتواطؤ مع غيره","محظور فقط إذا تم منفرداً","جائز ما دام لم يؤثر على سعر السهم","جائز إذا تم من خلال وسيط مرخص"],"a":0},{"q":"يحظر بث الشائعات أو إعطاء تصريحات مضللة قد تؤثر على:","o":["سعر أي ورقة مالية أو سمعة أي جهة مصدرة","سعر صرف الدينار فقط","أرباح الوسيط المالي فقط","قرارات مجلس الهيئة فقط"],"a":0}]},{"n":"107","chapter":"المخالفات والعقوبات","notes":[],"source":"أ- يعاقب كل من يخالف ايا من احكام هذا القانون او الانظمة او التعليمات او القرارات الصادرة بمقتضاه بغرامة لا تزيد على (١٠٠,٠٠٠) مائة الف دينار إضافة الى غرامة لا تقل عن ضعف الربح الذي حققه او ضعف الخسارة التي تجنبها على ان لا تزيد على خمسة اضعاف ذلك الربح أو الخسارة .\nب-مع عدم الاخلال بأي عقوبة اشد ورد النص عليها في أي تشريع آخر وإضافة الى الغرامات المبينة في الفقرة (أ) من هذه المادة، يعاقب كل من يخالف ايا من احكام المواد المبينة ادناه بما يلي:-\n١-الحبس مدة لا تزيد على ثلاث سنوات لمخالفة احكام الفقرة (ج) من المادة (٦٣) والفقرتين (هـ) و (و) من المادة (١٠٥) والمادة (١٠٦) من هذا القانون.\n٢-الحبس مدة لا تزيد على سنة لمخالفة احكام البند (١) من الفقرة (أ) من المادة (٣٤) والفقرة (د) من المادة (٤٢) والفقرتين (أ) و (ب) من المادة (٤٧) من هذا القانون .\nج-للمحكمة المختصة ان لا تحكم بعقوبة الحبس اذا كانت المخالفة للمرة الاولى او اذا اودع المخالف لصندوق المحكمة او للهيئة مبلغا كافيا لدفع قيمة الغرامات التي قد يحكم بها ، شريطة دفعها قبل اكتساب الحكم الدرجة القطعية.\nد-يعاقب الشريك والمتدخل والمحرض بالعقوبة ذاتها .\nهـ-لا يعتبر اعضاء مجالس الادارة واعضاء هيئة المديرين والشركاء المتضامنون والموظفون المعنيون لدى الشخص الاعتباري المخالف مسؤولين عن المخالفة ما لم يثبت علمهم بارتكابها.\nو-يكون المحكوم عليه باي مخالفة سواء كان ذلك عن قصد او تقصير او اهمال مسؤولا عن تعويض أي شخص تضرر جراء المخالفة بمقدار الخسارة التي تكبدها او الربح الذي فاته .\nز-للمحكمة المختصة القاء الحجز على موجودات أي شخص يحاكم لديها ضمانا لسداد الغرامات والتعويضات التي قد يحكم بها ولها ان تعين قيما على هذه الموجودات .","title":"العقوبات","memo":"⭐ غرامة لا تزيد على (١٠٠,٠٠٠) دينار + غرامة لا تقل عن ضعف الربح المحقق أو الخسارة المتجنبة ولا تزيد على خمسة أضعافها\n⭐ حبس لا يزيد على ٣ سنوات: م٦٣/ج، م١٠٥/هـ و/و (المعلومات الداخلية)، م١٠٦ (الشائعات والتلاعب)؛ وحبس لا يزيد على سنة: م٣٤/أ/١، م٤٢/د، م٤٧/أ و ب\n⭐ للمحكمة عدم الحكم بالحبس للمرة الأولى أو إذا أودع المخالف مبلغاً كافياً للغرامات شريطة دفعها قبل اكتساب الحكم الدرجة القطعية؛ والشريك والمتدخل والمحرض بالعقوبة ذاتها\n⭐ أعضاء مجلس الإدارة والموظفون لدى الشخص الاعتباري غير مسؤولين ما لم يثبت علمهم؛ وللمحكمة الحجز على الموجودات وتعيين قيّم","qs":[{"q":"الحد الأعلى للغرامة الأساسية لمخالفة أحكام قانون الأوراق المالية هو:","o":["(١٠٠,٠٠٠) دينار","(٥٠,٠٠٠) دينار","(٢٠٠,٠٠٠) دينار","(١,٠٠٠,٠٠٠) دينار"],"a":0},{"q":"حقق مخالف ربحاً قدره (٢٠,٠٠٠) دينار من مخالفته، فإن الغرامة الإضافية تكون بين:","o":["(٤٠,٠٠٠) و(١٠٠,٠٠٠) دينار","(٢٠,٠٠٠) و(٦٠,٠٠٠) دينار","(٤٠,٠٠٠) و(٦٠,٠٠٠) دينار","(١٠,٠٠٠) و(٢٠,٠٠٠) دينار"],"a":0},{"q":"عقوبة الحبس لمخالفة أحكام المادة (١٠٦) المتعلقة ببث الشائعات والتأثير على المعاملات هي الحبس مدة لا تزيد على:","o":["ثلاث سنوات","سنة","ستة أشهر","خمس سنوات"],"a":0},{"q":"ارتكبت شركة مساهمة مخالفة لأحكام القانون، فإن أعضاء مجلس إدارتها:","o":["لا يعتبرون مسؤولين ما لم يثبت علمهم بارتكابها","مسؤولون بالتضامن في جميع الأحوال","مسؤولون إذا كانت المخالفة للمرة الأولى","لا يسألون مطلقاً لأن المسؤولية على الشخص الاعتباري"],"a":0}]},{"n":"108","chapter":"المخالفات والعقوبات","notes":[],"source":"أ- يحق لاي مستثمر تعرض لاضرار مالية نتيجة بيع اوراق مالية مطالبة البائع او المصدر، حسب مقتضى الحال، بالتعويض عن الاضرار التي لحقته شريطة ان يثبت ما يلي :-\n١-ان بيع تلك الاوراق المالية قد تم بصورة مخالفة لاحكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه .\n٢-انه قد تعرض لخسارة مالية نتيجة لبيع تلك الاوراق المالية.\nب-يحق لاي مستثمر تعرض لاضرار مالية نتيجة عدم صحة او دقة او كفاية الافصاح الوارد في نشرة الاصدار او مرفقاتها او التقارير الواجب تقديمها الى الهيئة وفق احكام هذا القانون مطالبة أي شخص وقع على أي منهما بالتعويض عن الاضرار التي لحقته، شريطة ان يثبت ما يلي :-\n١-ان نشرة الاصدار او مرفقاتها او التقرير لم تتضمن معلومات جوهرية وضرورية له لاتخاذ القرار المناسب بشأن بيع او شراء او الاحتفاظ بأوراق مالية .\n٢-ان نشرة الاصدار او مرفقاتها او التقرير تضمن بيانات غير صحيحة او مضللة كان لها اثر على قرار البيع او الشراء او الاحتفاظ بالاوراق المالية .\nج-للمتضرر اقامة دعواه امام المحكمة المختصة خلال مدة لا تزيد على سنتين من تاريخ :-\n١-البيع ، في حال نجمت الاضرار عن بيع اوراق مالية .\n٢-نفاذ نشرة الاصدار ، او تاريخ تقديم التقرير او التاريخ الذي كان ينبغي تقديمه فيه ، وذلك حسب مقتضى الحال .","title":"دعوى تعويض المستثمر","memo":"⭐ للمستثمر المتضرر من بيع أوراق مالية مطالبة البائع أو المصدر بالتعويض إذا أثبت أن البيع مخالف للقانون وأنه تعرض لخسارة نتيجته\n⭐ للمتضرر من عدم صحة أو دقة أو كفاية الإفصاح في نشرة الإصدار أو التقارير مطالبة من وقع عليها إذا أثبت إغفال معلومات جوهرية أو تضمنها بيانات مضللة أثرت على قراره\n⭐ تقام الدعوى خلال مدة لا تزيد على سنتين من تاريخ البيع، أو من نفاذ نشرة الإصدار أو تاريخ تقديم التقرير أو التاريخ الذي كان ينبغي تقديمه فيه","qs":[{"q":"يقيم المستثمر المتضرر دعواه أمام المحكمة المختصة وفق المادة خلال مدة لا تزيد على:","o":["سنتين","سنة","ثلاث سنوات","خمس سنوات"],"a":0},{"q":"تضرر مستثمر بسبب بيانات مضللة في نشرة إصدار. تبدأ مدة إقامة دعواه من تاريخ:","o":["نفاذ نشرة الإصدار","علمه بالضرر","انتهاء الاكتتاب","صدور قرار الهيئة بالمخالفة"],"a":0},{"q":"يحق للمستثمر المتضرر من عدم كفاية الإفصاح الوارد في نشرة الإصدار مطالبة بالتعويض:","o":["أي شخص وقع على نشرة الإصدار أو مرفقاتها","الهيئة التي وافقت على النشرة","السوق المالي","المركز"],"a":0}]},{"n":"109","chapter":"المخالفات والعقوبات","notes":[],"source":"للمجلس تقييد الترخيص او الاعتماد الممنوح وفق احكام هذا القانون او تعليق او الغاء أي منهما في أي من الحالات التالية :-\nأ-مخالفة المرخص له او المعتمد لاي من احكام هذا القانون او الانظمة او التعليمات او القرارات الصادرة بمقتضاه .\nب-اذا ثبت للهيئة بأن ايا منهما قد ارتكب خداعا او احتيالا .\nج-ادانة أي منهما امام المحكمة المختصة بارتكاب خداع او احتيال في أي من المعاملات المتعلقة بالاوراق المالية .","title":"تقييد الترخيص أو إلغاؤه","memo":"⭐ للمجلس تقييد الترخيص أو الاعتماد أو تعليقه أو إلغاؤه في حالات: مخالفة القانون، إذا ثبت للهيئة ارتكاب خداع أو احتيال، الإدانة أمام المحكمة بخداع أو احتيال في معاملات الأوراق المالية","qs":[{"q":"الجهة التي لها تقييد الترخيص الممنوح وفق قانون الأوراق المالية أو تعليقه أو إلغاؤه هي:","o":["المجلس","المحكمة المختصة","مجلس الوزراء","السوق المالي"],"a":0},{"q":"أي مما يلي لا يعد من الحالات التي تجيز للمجلس إلغاء الترخيص وفق المادة؟","o":["تحقيق المرخص له خسائر في سنة مالية","مخالفة المرخص له لأي من أحكام القانون أو التعليمات","ثبوت ارتكاب المرخص له خداعاً أو احتيالاً للهيئة","إدانة المرخص له أمام المحكمة بارتكاب احتيال في معاملات الأوراق المالية"],"a":0}]},{"n":"110","chapter":"المخالفات والعقوبات","notes":[],"source":"أ- تعطى قضايا الاوراق المالية الحقوقية والجزائية صفة الاستعجال لدى المحاكم المختصة بما في ذلك تنفيذ الاحكام الصادرة عنها .\nب-يتم التبليغ في قضايا الاوراق المالية وفقا لاحكام قانون اصول المحاكمات المدنية، الا انه يجوز تبليغ أي شخص يقع مكان اقامته او عمله خارج المملكة اما على عنوانه المختار داخل المملكة ان وجد او عن طريق الاعلان في صحيفة يومية محلية واحدة على الاقل وارسال نسخة من اشعار التبليغ او الاعلان بالبريد المسجل او السريع او الممتاز الى العنوان المعروف لدى الهيئة خارج المملكة ، ويعتبر تاريخ التبليغ في هذه الحالة هو تاريخ اليوم السابع من تاريخ ايداع اشعار التبليغ في البريد .\nج-يجوز الاثبات في قضايا الاوراق المالية بجميع طرق الاثبات بما في ذلك البيانات الالكترونية الصادرة عن الحاسوب وتسجيلات الهاتف ومراسلات اجهزة الفاكسميلي وذلك على الرغم مما ورد في أي تشريع اخر .","title":"إجراءات قضايا الأوراق المالية","memo":"⭐ تعطى قضايا الأوراق المالية الحقوقية والجزائية صفة الاستعجال بما في ذلك تنفيذ الأحكام\n⭐ يجوز تبليغ المقيم خارج المملكة على عنوانه المختار داخلها أو بالإعلان في صحيفة يومية محلية واحدة على الأقل مع إرسال نسخة بالبريد المسجل أو السريع أو الممتاز\n⭐ يعتبر تاريخ التبليغ اليوم السابع من تاريخ إيداع الإشعار في البريد\n⭐ يجوز الإثبات بجميع الطرق بما فيها البيانات الإلكترونية وتسجيلات الهاتف والفاكس","qs":[{"q":"عند تبليغ شخص مقيم خارج المملكة بالإعلان وإرسال نسخة الإشعار بالبريد، يعتبر تاريخ التبليغ هو:","o":["اليوم السابع من تاريخ إيداع الإشعار في البريد","اليوم الخامس عشر من تاريخ النشر","تاريخ نشر الإعلان في الصحيفة","تاريخ استلام الإشعار فعلياً"],"a":0},{"q":"يجوز تبليغ الشخص المقيم خارج المملكة عن طريق الإعلان في صحيفة يومية محلية:","o":["واحدة على الأقل","اثنتين على الأقل","ثلاث صحف","واحدة لمدة ثلاثة أيام متتالية"],"a":0},{"q":"أي مما يلي صحيح بشأن الإثبات في قضايا الأوراق المالية؟","o":["يجوز الإثبات بجميع الطرق بما فيها تسجيلات الهاتف رغم ما ورد في أي تشريع آخر","لا يجوز الإثبات إلا بالبينة الخطية","لا تقبل البيانات الإلكترونية الصادرة عن الحاسوب","يقتصر الإثبات على ما ورد في قانون البينات"],"a":0}]},{"n":"111","chapter":"احكام عامة وانتقالية","notes":[],"source":"أ- على الرغم مما ورد في قانون الشركات، تناط بالهيئة ممارسة المهام والصلاحيات التنظيمية والرقابية المنصوص عليها في قانون الشركات والمتعلقة بالشركات المساهمة العامة والشركات المساهمة الخاصة التي يتم تداول اسهمها في السوق المالي، ولهذه الغاية يمارس المجلس صلاحيات الوزير ويمارس الرئيس صلاحيات المراقب المنصوص عليها في ذلك القانون.\nب-تحدد جميع الشؤون المتعلقة بممارسة الهيئة للمهام والصلاحيات التنظيمية والرقابية المنصوص عليها في الفقرة ( أ ) من هذه المادة بمقتضى نظام يصدر لهذه الغاية.","title":"صلاحيات الهيئة وفق قانون الشركات","memo":"⭐ رغم قانون الشركات: تمارس الهيئة المهام التنظيمية والرقابية المتعلقة بالشركات المساهمة العامة والمساهمة الخاصة المتداولة أسهمها في السوق المالي\n⭐ يمارس المجلس صلاحيات الوزير، ويمارس الرئيس صلاحيات المراقب\n⭐ تحدد الشؤون المتعلقة بذلك بنظام","qs":[{"q":"لغايات ممارسة الهيئة صلاحياتها الرقابية على الشركات المساهمة العامة وفق قانون الشركات، يمارس رئيس الهيئة صلاحيات:","o":["المراقب","الوزير","المجلس","المدير التنفيذي للسوق"],"a":0},{"q":"يمارس المجلس، لغايات الرقابة على الشركات المساهمة العامة بموجب قانون الشركات، صلاحيات:","o":["الوزير","المراقب","مجلس الوزراء","الهيئة العامة للشركة"],"a":0},{"q":"أي من الشركات التالية تخضع للمهام التنظيمية والرقابية للهيئة وفق المادة؟","o":["الشركة المساهمة الخاصة التي يتم تداول أسهمها في السوق المالي","الشركة ذات المسؤولية المحدودة","شركة التضامن","الشركة المساهمة الخاصة غير المتداولة أسهمها"],"a":0}]},{"n":"112","chapter":"احكام عامة وانتقالية","notes":[],"source":"تمنح الاوراق المالية ، وفقا لاحكام هذا القانون ، الميزات التالية :-\nأ-الصفة النهائية والقطعية لتداولها في الاسواق المالية .\nب-حقوق ملكية واثمان مستحقة وفقا لحسابات المركز .\nج-عدم جواز الغاء التسويات النهائية لعقود التداول في السوق المالي.","title":"ميزات الأوراق المالية","memo":"⭐ الصفة النهائية والقطعية لتداولها في الأسواق المالية\n⭐ حقوق ملكية وأثمان مستحقة وفقاً لحسابات المركز\n⭐ عدم جواز إلغاء التسويات النهائية لعقود التداول في السوق المالي","qs":[{"q":"تمنح الأوراق المالية وفق القانون حقوق ملكية وأثماناً مستحقة وفقاً لحسابات:","o":["المركز","السوق المالي","الوسيط المالي","الهيئة"],"a":0},{"q":"أي مما يلي لا يعد من الميزات التي تمنحها الأوراق المالية وفق المادة؟","o":["جواز إلغاء التسويات النهائية بقرار من الوسيط","الصفة النهائية والقطعية لتداولها في الأسواق المالية","حقوق ملكية وأثمان مستحقة وفقاً لحسابات المركز","عدم جواز إلغاء التسويات النهائية لعقود التداول"],"a":0}]},{"n":"113","chapter":"احكام عامة وانتقالية","notes":[],"source":"يجب ان لا تقل نسبة ملكية الحكومة في شركة بورصة عمان في أي وقت من الاوقات عن نسبة (٥١%) من رأس مال الشركة .","title":"ملكية الحكومة في بورصة عمان","memo":"⭐ يجب ألا تقل ملكية الحكومة في شركة بورصة عمان في أي وقت عن (٥١%) من رأس مالها","qs":[{"q":"يجب أن لا تقل نسبة ملكية الحكومة في شركة بورصة عمان في أي وقت من الأوقات عن:","o":["٥١%","٥٠%","٢٥%","٧٥%"],"a":0}]},{"n":"114","chapter":"احكام عامة وانتقالية","notes":[],"source":"أ- اذا استقال مجلس ادارة السوق المالي او المركز او فقد أي منهما نصابه القانوني او لاي سبب يتعلق بالمصلحة العامة او مصلحة سوق رأس المال فللمجلس تشكيل لجنة ادارة مؤقتة من ذوي الخبرة والاختصاص .\nب-تكون مدة اللجنة المنصوص عليها في الفقرة (أ) من هذه المادة ستة اشهر، قابلة للتجديد لمرة واحدة ، تتولى ادارة السوق المالي او المركز ودعوة هيئتها العامة خلال هذه المدة لانتخاب مجلس ادارة جديد وفقا للانظمة الداخلية للسوق المالي او المركز .","title":"لجنة الإدارة المؤقتة","memo":"⭐ للمجلس تشكيل لجنة إدارة مؤقتة من ذوي الخبرة إذا استقال مجلس إدارة السوق أو المركز أو فقد نصابه أو لسبب يتعلق بالمصلحة العامة أو مصلحة سوق رأس المال\n⭐ مدة اللجنة ستة أشهر قابلة للتجديد لمرة واحدة، وتدعو الهيئة العامة لانتخاب مجلس إدارة جديد","qs":[{"q":"مدة لجنة الإدارة المؤقتة التي يشكلها المجلس لإدارة السوق المالي أو المركز:","o":["ستة أشهر قابلة للتجديد لمرة واحدة","سنة قابلة للتجديد لمرة واحدة","ثلاثة أشهر قابلة للتجديد مرتين","ستة أشهر غير قابلة للتجديد"],"a":0},{"q":"فقد مجلس إدارة المركز نصابه القانوني، فإن للمجلس:","o":["تشكيل لجنة إدارة مؤقتة من ذوي الخبرة والاختصاص","حل المركز وتحويل أمواله للخزينة","تعيين رئيس الهيئة مديراً للمركز","التنسيب لمجلس الوزراء بتعيين مجلس جديد"],"a":0},{"q":"تتولى لجنة الإدارة المؤقتة خلال مدتها دعوة الهيئة العامة للسوق المالي أو المركز من أجل:","o":["انتخاب مجلس إدارة جديد","تصفية السوق أو المركز","تعديل الأنظمة الداخلية","زيادة رأس المال"],"a":0}]},{"n":"115","chapter":"احكام عامة وانتقالية","notes":[],"source":"أ- للهيئة انشاء صندوق ادخار وصندوق اسكان لموظفيها ومستخدميها تنظم شؤونهما بمقتضى نظام يصدر لهذه الغاية .\nب-للسوق المالي والمركز انشاء صناديق ادخار واسكان لموظفيها ومستخدميها تنظم شؤونها بمقتضى انظمتها الداخلية .\nج-تتمتع الصناديق المشار اليها في الفقرتين (أ) و (ب) من هذه المادة بالشخصية الاعتبارية.","title":"صناديق الادخار والإسكان","memo":"⭐ للهيئة إنشاء صندوق ادخار وصندوق إسكان لموظفيها بنظام\n⭐ للسوق المالي والمركز إنشاء صناديق ادخار وإسكان تنظم بأنظمتها الداخلية\n⭐ تتمتع هذه الصناديق بالشخصية الاعتبارية","qs":[{"q":"تنظم شؤون صندوقي الادخار والإسكان لموظفي الهيئة بمقتضى:","o":["نظام يصدر لهذه الغاية","الأنظمة الداخلية للمركز","تعليمات يصدرها رئيس الهيئة","قرار من الموظفين"],"a":0},{"q":"تنظم شؤون صناديق الادخار والإسكان التي ينشئها السوق المالي لموظفيه بمقتضى:","o":["أنظمته الداخلية","نظام يصدره مجلس الوزراء","تعليمات وزير المالية","قانون الضمان الاجتماعي"],"a":0}]},{"n":"116","chapter":"احكام عامة وانتقالية","notes":[],"source":"على الرغم مما ورد في قانون رسوم طوابع الواردات المعمول به ، تعفى من رسوم طوابع الواردات نشرات اصدار الاوراق المالية وتسجيلها وعمليات ومعاملات التداول بالاوراق المالية .","title":"الإعفاء من رسوم طوابع الواردات","memo":"⭐ رغم قانون رسوم طوابع الواردات تعفى منها: نشرات إصدار الأوراق المالية وتسجيلها وعمليات ومعاملات التداول","qs":[{"q":"تعفى نشرات إصدار الأوراق المالية وتسجيلها وعمليات ومعاملات التداول بالأوراق المالية من:","o":["رسوم طوابع الواردات","ضريبة الدخل","الضريبة العامة على المبيعات","رسوم التسجيل لدى المركز"],"a":0},{"q":"أي مما يلي لم تذكره المادة ضمن المعفى من رسوم طوابع الواردات؟","o":["عقود تأسيس شركات الاستثمار المشترك","نشرات إصدار الأوراق المالية","تسجيل الأوراق المالية","عمليات ومعاملات التداول بالأوراق المالية"],"a":0}]},{"n":"117","chapter":"احكام عامة وانتقالية","notes":[],"source":"أ- يلغى قانون الاوراق المالية المؤقت رقم (٢٣) لسنة ١٩٩٧ وتعديلاته.\nب-لا يعمل بأي نص ورد في أي تشريع آخر الى المدى الذي يتعارض فيه مع احكام هذا القانون والانظمة والتعليمات والقرارات الصادرة بمقتضاه .\nج-تبقى جميع الانظمة والتعليمات والقرارات المعمول بها والصادرة بموجب قانون الاوراق المالية المؤقت رقم (٢٣) لسنة ١٩٩٧ سارية المفعول الى حين الغائها او استبدال غيرها بها .\nد-تبقى جميع الانظمة الداخلية والتعليمات الصادرة عن كل من بورصة عمان والمركز سارية المفعول الى حين الغائها او استبدال غيرها بها .","title":"الإلغاء واستمرار التشريعات","memo":"⭐ يلغى قانون الأوراق المالية المؤقت رقم (٢٣) لسنة ١٩٩٧ وتعديلاته\n⭐ لا يعمل بأي نص في تشريع آخر يتعارض مع هذا القانون\n⭐ تبقى الأنظمة والتعليمات الصادرة بموجب القانون الملغى والأنظمة الداخلية لبورصة عمان والمركز سارية إلى حين إلغائها أو استبدال غيرها بها","qs":[{"q":"ألغى قانون الأوراق المالية رقم (١٨) لسنة ٢٠١٧ قانون الأوراق المالية المؤقت رقم:","o":["(٢٣) لسنة ١٩٩٧","(٢٢) لسنة ٢٠٠٢","(٧٦) لسنة ٢٠٠٢","(٢٣) لسنة ٢٠٠٧"],"a":0},{"q":"الأنظمة والتعليمات الصادرة بموجب قانون الأوراق المالية المؤقت الملغى:","o":["تبقى سارية المفعول إلى حين إلغائها أو استبدال غيرها بها","تلغى حكماً من تاريخ نفاذ القانون الجديد","تبقى سارية لمدة سنة واحدة فقط","تبقى سارية لمدة ستة أشهر فقط"],"a":0}]},{"n":"118","chapter":"احكام عامة وانتقالية","notes":[],"source":"أ- يصدر مجلس الوزراء ، بناء على تنسيب المجلس، الانظمة اللازمة لتنفيذ احكام هذا القانون بما في ذلك الشؤون الادارية والمالية وشؤون اللوازم والاشغال وشؤون الموظفين والمستخدمين في الهيئة بما فيها ايجاد الحوافز التي تساعدهم على توجيه جهودهم لتحقيق اهداف الهيئة ورفع مستواهم العلمي والمهني .\nب-يصدر المجلس التعليمات والقرارات اللازمة لتنفيذ احكام هذا القانون .","title":"إصدار الأنظمة والتعليمات","memo":"⭐ يصدر مجلس الوزراء بتنسيب من المجلس الأنظمة اللازمة لتنفيذ القانون بما فيها شؤون موظفي الهيئة وحوافزهم\n⭐ يصدر المجلس التعليمات والقرارات اللازمة لتنفيذ القانون","qs":[{"q":"تصدر الأنظمة اللازمة لتنفيذ أحكام قانون الأوراق المالية عن:","o":["مجلس الوزراء بناء على تنسيب المجلس","المجلس بناء على تنسيب الرئيس","رئيس الوزراء بناء على تنسيب الوزير","مجلس الأمة"],"a":0},{"q":"يصدر التعليمات والقرارات اللازمة لتنفيذ أحكام قانون الأوراق المالية:","o":["المجلس","مجلس الوزراء","رئيس الوزراء","مجلس إدارة السوق المالي"],"a":0}]},{"n":"119","chapter":"احكام عامة وانتقالية","notes":[],"source":"رئيس الوزراء والوزراء مكلفون بتنفيذ احكام هذا القانون.","title":"تنفيذ القانون","memo":"⭐ رئيس الوزراء والوزراء مكلفون بتنفيذ أحكام هذا القانون.","qs":[{"q":"المكلفون بتنفيذ أحكام قانون الأوراق المالية:","o":["رئيس الوزراء والوزراء","المجلس وحده","رئيس الهيئة","وزير الصناعة والتجارة وحده"],"a":0}]}]};
